INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_5_all_1774921043968', 'A marketing department wants to understand customer segments based on their purchasing behavior, but they do not have predefined categories or labels for these segments. They need an AI approach that can automatically discover hidden patterns and group similar customers together without prior knowledge of the groups. Which type of machine learning is best suited for this task?', '["Option A: Supervised learning, as it uses labeled data to predict outcomes.","Option B: Reinforcement learning, which involves an agent learning through trial and error.","Option C: Deep learning, which uses neural networks for complex pattern recognition.","Option D: Unsupervised learning, to find hidden patterns and structures in unlabeled data."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is Unsupervised learning. This type of machine learning is specifically designed to find hidden patterns and structures in unlabeled datasets, making it ideal for tasks like customer segmentation where predefined categories do not exist. Clustering algorithms, a subset of unsupervised learning, would be used here. Option A (incorrect) is Supervised learning, which requires labeled data (i.e., predefined customer segments) to train a model to predict those labels, which is not the case in this scenario. Option B (incorrect) is Reinforcement learning, which is used for training agents to make sequences of decisions in an environment to maximize a reward, not for discovering patterns in static datasets. Option C (incorrect) is Deep learning, which is a subset of machine learning using neural networks. While deep learning models can be used in both supervised and unsupervised contexts, ''deep learning'' itself is a methodology, not a type of learning defined by the presence or absence of labels for the specific task of finding hidden patterns without prior knowledge.', 5, 'm_5_1', 8, NULL, NULL),
  ('mock_5_all_1774921043968', 'A tech company is developing an advanced system to recognize complex patterns in large image datasets, such as identifying specific objects or anomalies in medical scans. This task requires processing high-dimensional data and learning intricate features directly from the raw pixels. Which category of AI best describes the underlying technology that enables this capability?', '["Option A: Deep learning, a subset of machine learning that uses neural networks with many layers.","Option B: Machine learning, which is a broad field of AI focused on statistical methods.","Option C: Artificial intelligence, which is the overarching concept of machines simulating human intelligence.","Option D: Reinforcement learning, which involves agents learning through interactions with an environment."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is Deep learning. Deep learning is a specialized subset of machine learning that utilizes artificial neural networks with multiple layers (deep neural networks) to learn complex patterns from large amounts of data, particularly effective for tasks involving unstructured data like images, audio, and text. This capability is essential for advanced image recognition. Option B (incorrect) is Machine learning, which is a broader field that encompasses deep learning. While deep learning is a type of machine learning, ''deep learning'' more precisely describes the technology for complex pattern recognition in high-dimensional data. Option C (incorrect) is Artificial intelligence, which is the broadest concept, referring to machines simulating human intelligence. Deep learning is a specific approach within AI. Option D (incorrect) is Reinforcement learning, which is a type of machine learning where an agent learns to make decisions by interacting with an environment and receiving rewards or penalties, which is not the primary method for image pattern recognition.', 5, 'm_5_1', 9, NULL, NULL),
  ('mock_5_all_1774921043968', 'A content creation agency wants to generate unique marketing taglines and product descriptions automatically. They aim to produce creative, human-like text that resonates with different target audiences without relying on a fixed set of templates. Which type of AI model is best suited for generating new, original content based on learned patterns?', '["Option A: Discriminative AI, which classifies or predicts from input data.","Option B: Generative AI, which creates new content by learning data distributions.","Option C: Supervised learning models, trained on labeled datasets of existing taglines.","Option D: Reinforcement learning models, optimized for sequential decision-making in content selection."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is Generative AI. Generative AI models, such as Large Language Models (LLMs), are specifically designed to create new, original content (text, images, audio, code) by learning the underlying patterns and distributions of their training data. This capability is ideal for generating unique marketing taglines and product descriptions. Option A (incorrect) is Discriminative AI, which focuses on classifying, predicting, or distinguishing between different inputs (e.g., classifying a tagline as good or bad), rather than creating new content. Option C (incorrect) refers to Supervised learning models. While they can be used to predict the ''best'' tagline from a predefined set, they are not inherently designed to generate novel content. Option D (incorrect) is Reinforcement learning, which is used for training agents to make optimal decisions in an environment, not primarily for generating creative text content.', 5, 'm_5_1', 10, NULL, NULL),
  ('mock_5_all_1774921043968', 'A data scientist is preparing a dataset for a supervised machine learning model that will predict whether a customer will click on an advertisement. The dataset includes customer demographics (age, income), browsing history, and a column indicating whether they clicked (Yes/No). To train the model effectively, the data scientist needs to clearly define the input variables and the target variable. What are the ''customer demographics'' and ''browsing history'' considered in this context?', '["Option A: Labels, which are the outputs the model predicts.","Option B: Features, which are the input variables used to make predictions.","Option C: Datasets, which are the entire collection of information.","Option D: Models, which are the trained algorithms that make predictions."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) refers to ''Features''. In machine learning, features are the individual measurable properties or characteristics of a phenomenon being observed. In this scenario, customer demographics (age, income) and browsing history are the input variables that the model uses to learn patterns and make predictions. Option A (incorrect) refers to ''Labels'' (or target variables), which are the outputs the model is trying to predict (in this case, whether the customer clicked ''Yes'' or ''No''). Option C (incorrect) refers to ''Datasets'', which is the entire collection of data, including both features and labels. Option D (incorrect) refers to ''Models'', which are the algorithms that have been trained on the features and labels to make predictions.', 5, 'm_5_1', 11, NULL, NULL),
  ('mock_5_all_1774921043968', 'A research team is developing an AI system to analyze complex satellite imagery for urban planning, specifically to identify different types of land use (e.g., residential, commercial, green spaces). This task involves processing vast amounts of pixel data and recognizing intricate spatial patterns. Which fundamental component of deep learning is primarily responsible for learning these hierarchical features from the image data?', '["Option A: Reinforcement learning agents, which learn optimal actions through trial and error.","Option B: Decision trees, which make decisions based on a series of if-else rules.","Option C: Neural networks, composed of interconnected layers that process and transform data.","Option D: Linear regression models, which predict continuous values based on linear relationships."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is Neural networks. Neural networks, particularly deep neural networks (which are the foundation of deep learning), are composed of multiple interconnected layers that process and transform input data. They are highly effective at learning hierarchical features from complex, high-dimensional data like images, making them ideal for tasks such as land use classification in satellite imagery. Option A (incorrect) refers to reinforcement learning agents, which are used for sequential decision-making in dynamic environments, not for static image pattern recognition. Option B (incorrect) refers to decision trees, which are simpler models that make decisions based on a series of rules and are generally less effective for complex image analysis compared to deep neural networks. Option D (incorrect) refers to linear regression models, which are used for predicting continuous values based on linear relationships and are not suitable for complex image classification tasks.', 5, 'm_5_1', 12, NULL, NULL),
  ('mock_5_all_1774921043968', 'A technology company wants to build a highly intelligent chatbot that can engage in natural, human-like conversations, answer complex questions, and even generate creative text responses. The chatbot needs to understand context, nuances, and generate coherent and relevant replies. Which type of AI model forms the foundation for achieving such advanced conversational capabilities?', '["Option A: Foundation models and Large Language Models (LLMs), which are pre-trained on vast amounts of text data.","Option B: Traditional machine learning models, such as Support Vector Machines, for text classification.","Option C: Rule-based expert systems, which follow predefined logical rules for responses.","Option D: Computer vision models, specialized in processing and understanding image data."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) refers to Foundation models and Large Language Models (LLMs). These models are pre-trained on massive datasets of text and code, enabling them to understand, generate, and process human language with remarkable fluency, coherence, and context awareness. They are the core technology behind advanced conversational AI, allowing for human-like interactions and creative text generation. Option B (incorrect) refers to traditional machine learning models like Support Vector Machines. While useful for specific text classification tasks, they lack the generative and contextual understanding capabilities required for advanced human-like conversation. Option C (incorrect) refers to Rule-based expert systems. These systems rely on explicitly programmed rules, which are rigid and cannot handle the complexity, nuance, and creativity required for natural, dynamic conversations. Option D (incorrect) refers to Computer vision models, which are designed for processing and understanding image data, not text-based conversational AI.', 5, 'm_5_1', 13, NULL, NULL),
  ('mock_5_all_1774921043968', 'A real estate agency wants to predict the selling price of houses in a specific neighborhood based on various factors like square footage, number of bedrooms, lot size, and proximity to schools. They have a dataset of historical house sales with all these attributes and their corresponding selling prices. Which common machine learning use case is most appropriate for this prediction task?', '["Option A: Classification, to categorize houses into predefined price bins.","Option B: Regression, to predict a continuous numerical value for the selling price.","Option C: Clustering, to group similar houses without predicting a specific price.","Option D: Recommendation, to suggest similar houses to potential buyers."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is Regression. Regression is a type of supervised learning used when the target variable is a continuous numerical value, such as house prices, stock prices, or temperature. The goal is to predict this continuous output based on the input features. Option A (incorrect) is Classification, which is used to predict a categorical label (e.g., ''high-priced'', ''medium-priced'', ''low-priced''), not a precise continuous numerical value. Option C (incorrect) is Clustering, an unsupervised learning technique used to group data points into clusters based on similarity without a predefined target variable. It would not predict a specific price. Option D (incorrect) is Recommendation, which involves suggesting items to users based on their preferences or past behavior, not predicting a specific numerical value like a house price.', 5, 'm_5_1', 14, NULL, NULL);

