INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_5_all_1774921043968', 'A small business needs to automate a simple inventory check: if the stock of an item falls below 10 units, an alert must be sent. This logic is straightforward and requires a deterministic outcome. The business is evaluating whether to implement a machine learning solution or a traditional programming approach. Which approach is MOST appropriate for this specific problem, considering simplicity and cost-effectiveness?', '["Option A: Develop a machine learning model to predict stock levels and trigger alerts.","Option B: Use Amazon Forecast to predict future stock levels and set thresholds.","Option C: Implement a simple rule-based system using traditional programming logic.","Option D: Train an anomaly detection model using Amazon SageMaker to identify low stock."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is to implement a simple rule-based system using traditional programming logic. For a deterministic problem like ''if stock < 10, then alert'', traditional programming with a simple ''if-then'' rule is the most straightforward, cost-effective, and reliable solution. Machine learning adds unnecessary complexity, computational overhead, and cost when a problem can be solved with explicit rules. Option A (incorrect) suggests developing an ML model, which is overkill for a simple, deterministic rule. It introduces complexity and cost without added benefit. Option B (incorrect) proposes using Amazon Forecast, which is a powerful service for time-series forecasting. While it could predict stock, it''s an expensive and complex solution for a simple threshold-based alert. Option D (incorrect) suggests training an anomaly detection model with Amazon SageMaker. Anomaly detection is for identifying unusual patterns, not for simple, predefined threshold checks, making it an overly complex and costly solution.', 5, 'm_5_2', 15, NULL, NULL),
  ('mock_5_all_1774921043968', 'A financial institution is developing an AI model to approve or deny loan applications. The model is trained on historical data, but there''s concern that the data might reflect historical biases against certain demographic groups. The institution wants to ensure the model''s decisions are fair and do not inadvertently discriminate. Which responsible AI principle should be a primary focus during the model''s development and deployment?', '["Option A: Robustness, to ensure the model is resilient to adversarial attacks.","Option B: Transparency, to understand how the model arrives at its decisions.","Option C: Privacy, to protect sensitive customer information used by the model.","Option D: Fairness, to prevent discriminatory outcomes based on protected attributes."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is Fairness. The scenario explicitly mentions concerns about historical biases in data leading to discriminatory outcomes against demographic groups. Fairness in AI aims to ensure that models do not produce prejudiced or inequitable results for different groups, which is a critical ethical consideration for loan applications. Option A (incorrect) is Robustness, which focuses on the model''s resilience to malicious inputs or data perturbations, not directly on bias in decision-making. Option B (incorrect) is Transparency (or explainability), which is about understanding how a model makes its decisions. While related to fairness (as understanding bias helps address it), fairness is the direct principle addressing discriminatory outcomes. Option C (incorrect) is Privacy, which concerns the protection of sensitive data used by the model, but it does not directly address the issue of biased decision-making itself.', 5, 'm_5_2', 16, NULL, NULL),
  ('mock_5_all_1774921043968', 'A global customer support center receives a high volume of text-based customer feedback in multiple languages. They need to automatically analyze the sentiment of this feedback and translate it into English for their support agents. The solution must be scalable and require minimal custom code. Which combination of AWS AI services can best meet these requirements?', '["Option A: Amazon Comprehend for sentiment analysis and Amazon Translate for language translation.","Option B: Amazon Rekognition for text analysis and Amazon Polly for language translation.","Option C: Amazon Transcribe for sentiment analysis and Amazon Lex for language translation.","Option D: Amazon Forecast for sentiment analysis and Amazon Personalize for language translation."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is Amazon Comprehend for sentiment analysis and Amazon Translate for language translation. Amazon Comprehend is a natural language processing (NLP) service that uses machine learning to find insights and relationships in text, including sentiment analysis. Amazon Translate is a neural machine translation service that delivers fast, high-quality, and affordable language translation. This combination directly addresses the requirements for analyzing sentiment and translating text feedback. Option B (incorrect) suggests Amazon Rekognition (for image/video analysis) and Amazon Polly (text-to-speech), neither of which are suitable for text sentiment analysis or translation. Option C (incorrect) suggests Amazon Transcribe (speech-to-text) and Amazon Lex (conversational AI bot), which are not designed for text sentiment analysis or general language translation. Option D (incorrect) suggests Amazon Forecast (time-series forecasting) and Amazon Personalize (recommendation engine), which are entirely unrelated to text analysis or translation.', 5, 'm_5_2', 17, NULL, NULL),
  ('mock_5_all_1774921043968', 'A media company has a vast archive of video content and wants to automatically identify specific objects, scenes, and activities within these videos to improve content searchability and categorization. They need a managed service that can process large volumes of visual data without requiring them to build and train custom machine learning models. Which AWS AI service is best suited for this computer vision task?', '["Option A: Amazon Comprehend, for analyzing text within the videos.","Option B: Amazon Rekognition, for image and video analysis to detect objects, scenes, and activities.","Option C: Amazon Transcribe, for converting speech in videos to text.","Option D: Amazon Textract, for extracting text and data from scanned documents within video frames."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is Amazon Rekognition. Amazon Rekognition is a fully managed AWS AI service that provides pre-trained computer vision capabilities to detect objects, scenes, activities, text, faces, and celebrities in images and videos. It directly addresses the requirement to automatically identify visual elements within video content without custom model training. Option A (incorrect) is Amazon Comprehend, which is an NLP service for analyzing text, not visual content. Option C (incorrect) is Amazon Transcribe, which converts speech to text, relevant for audio but not for identifying visual objects and scenes. Option D (incorrect) is Amazon Textract, which extracts text and data from scanned documents, not for general object and scene detection in videos.', 5, 'm_5_2', 18, NULL, NULL),
  ('mock_5_all_1774921043968', 'A retail chain wants to optimize its supply chain by accurately predicting future sales for thousands of products across different store locations. This requires analyzing historical sales data, promotional events, and external factors like holidays and weather. The company needs a fully managed service that can build highly accurate forecasts without requiring deep machine learning expertise. Which AWS AI service should they use?', '["Option A: Amazon Rekognition, for analyzing product images to predict sales.","Option B: Amazon Comprehend, for analyzing product descriptions to predict sales.","Option C: Amazon Forecast, for highly accurate time-series forecasting using machine learning.","Option D: Amazon Personalize, for recommending products based on historical sales trends."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is Amazon Forecast. Amazon Forecast is a fully managed service that uses machine learning to deliver highly accurate forecasts based on the same technology used at Amazon.com. It is specifically designed for time-series forecasting problems like predicting product demand, incorporating historical data, related time series (e.g., promotions, holidays), and external factors. It abstracts away the ML complexity, making it ideal for the described scenario. Option A (incorrect) is Amazon Rekognition, a computer vision service for image and video analysis, not forecasting. Option B (incorrect) is Amazon Comprehend, an NLP service for text analysis, not forecasting. Option D (incorrect) is Amazon Personalize, a recommendation engine, which suggests items but does not predict future demand or sales volumes.', 5, 'm_5_2', 19, NULL, NULL),
  ('mock_5_all_1774921043968', 'A content creator wants to produce audio versions of their written articles and also transcribe spoken interviews into text for documentation. They need managed AWS AI services that can handle both converting text to lifelike speech and converting speech from audio files into accurate text. Which combination of AWS AI services would best achieve these two distinct tasks?', '["Option A: Amazon Lex for text-to-speech and Amazon Polly for speech-to-text.","Option B: Amazon Comprehend for text-to-speech and Amazon Rekognition for speech-to-text.","Option C: Amazon Textract for text-to-speech and AWS DeepRacer for speech-to-text.","Option D: Amazon Polly for text-to-speech and Amazon Transcribe for speech-to-text."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is Amazon Polly for text-to-speech and Amazon Transcribe for speech-to-text. Amazon Polly is a service that turns text into lifelike speech, allowing for the creation of audio versions of articles. Amazon Transcribe is an automatic speech recognition (ASR) service that makes it easy to add speech-to-text capabilities to applications, perfect for transcribing spoken interviews. This combination directly addresses both requirements. Option A (incorrect) suggests Amazon Lex (conversational AI bot) and Amazon Polly (text-to-speech), but Lex is not for speech-to-text. Option B (incorrect) suggests Amazon Comprehend (text analysis) and Amazon Rekognition (image/video analysis), neither of which are for text-to-speech or speech-to-text. Option C (incorrect) suggests Amazon Textract (document text extraction) and AWS DeepRacer (reinforcement learning for autonomous driving), which are completely unrelated to the required tasks.', 5, 'm_5_2', 20, NULL, NULL),
  ('mock_5_all_1774921043968', 'An online retailer wants to enhance customer experience by providing highly personalized product recommendations. They have a large dataset of customer interactions, including browsing history, purchase history, and product metadata. The goal is to suggest relevant products to individual customers in real-time, similar to how major e-commerce platforms operate. Which AWS AI service is specifically designed for building and deploying personalized recommendation systems?', '["Option A: Amazon Personalize, for building real-time personalized recommendation systems.","Option B: Amazon Forecast, for predicting future product demand based on historical data.","Option C: Amazon Comprehend, for analyzing customer review sentiment to inform recommendations.","Option D: Amazon Rekognition, for identifying products in images to suggest similar visual items."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is Amazon Personalize. Amazon Personalize is a fully managed machine learning service that enables developers to easily build applications with the same machine learning technology used by Amazon.com for real-time personalization and recommendation. It is specifically designed to address the need for personalized product recommendations based on user interaction and item data. Option B (incorrect) is Amazon Forecast, which is used for time-series forecasting (e.g., predicting sales), not for personalized recommendations. Option C (incorrect) is Amazon Comprehend, an NLP service for text analysis (e.g., sentiment), which could inform recommendations but doesn''t build the recommendation engine itself. Option D (incorrect) is Amazon Rekognition, a computer vision service for image and video analysis, not for building a comprehensive recommendation system based on user behavior.', 5, 'm_5_2', 21, NULL, NULL);

-- Update mock test with question count
UPDATE public.mock_tests
SET total_questions = total_questions + 21
WHERE id = 'mock_5_all_1774921043968';

