INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_5_all_1774921043968', 'A startup needs to develop an internal HR chatbot that can answer questions based on thousands of proprietary HR documents. The solution must offer the LEAST operational overhead for managing the underlying LLM and its knowledge base, while ensuring responses are accurate and grounded in the company''s specific data. Which approach meets these requirements most effectively?', '["Deploy a self-managed open-source LLM on Amazon EC2 instances, and store HR documents in Amazon S3, manually implementing a search and retrieval mechanism.","Utilize Amazon Bedrock with a pre-trained foundation model, and configure an Amazon Bedrock Knowledge Base connected to an Amazon S3 bucket containing the HR documents.","Use Amazon SageMaker JumpStart to deploy a foundation model, and store HR documents in an Amazon DynamoDB table for quick lookups.","Develop a custom LLM from scratch using Amazon SageMaker, and implement a custom RAG solution with Amazon OpenSearch Service for document indexing."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) utilizes Amazon Bedrock, which provides managed access to foundation models, significantly reducing operational overhead. An Amazon Bedrock Knowledge Base automatically handles the ingestion, chunking, embedding, and retrieval of documents from an Amazon S3 bucket, grounding the LLM''s responses in the proprietary data with minimal management. Option A (incorrect) involves self-hosting an LLM on Amazon EC2, which incurs significant operational overhead for infrastructure management, security, and manual RAG implementation. Option C (incorrect) Amazon SageMaker JumpStart is for deploying models, but Amazon DynamoDB is a key-value store, not optimized for semantic similarity search required by RAG, representing a common anti-pattern. Option D (incorrect) developing a custom LLM from scratch is extremely time-consuming and expensive, and a custom RAG solution would still require significant operational effort compared to Amazon Bedrock Knowledge Bases.', 6, 'm_6_3', 1, NULL, NULL),
  ('mock_5_all_1774921043968', 'An e-commerce company is building a real-time image recognition service to automatically tag product images as they are uploaded. This service requires extremely high-performance inference and low latency to process millions of images daily at the lowest possible cost per inference. Which AWS infrastructure component is specifically designed to accelerate deep learning inference workloads efficiently?', '["Amazon EC2 instances with general-purpose CPUs.","AWS Inferentia-based Amazon EC2 instances.","AWS Trainium-based Amazon EC2 instances.","Amazon EC2 instances with standard GPU accelerators."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is AWS Inferentia-based Amazon EC2 instances. AWS Inferentia is purpose-built by AWS for high-performance, low-latency, and cost-effective deep learning inference. It provides superior performance per watt and lowest cost per inference compared to general-purpose CPUs or GPUs for inference workloads. Option A (incorrect) general-purpose CPUs are not optimized for deep learning inference and would not meet the high-performance and low-latency requirements. Option C (incorrect) AWS Trainium is specifically designed for accelerating deep learning *training*, not inference. Option D (incorrect) standard GPU accelerators can perform inference, but AWS Inferentia offers a more specialized and cost-optimized solution for large-scale inference.', 6, 'm_6_3', 2, NULL, NULL),
  ('mock_5_all_1774921043968', 'A data science team is tasked with evaluating multiple foundation models from different providers for a new text summarization application. They require a service that offers a unified API to access these diverse models, enabling rapid experimentation without the overhead of managing any underlying infrastructure. Which AWS service is purpose-built to meet these requirements for accessing and using foundation models?', '["Amazon SageMaker JumpStart, which provides a marketplace for pre-trained models that require manual deployment.","Deploying various open-source models on Amazon EC2 instances and managing their APIs manually.","Building custom models from scratch using Amazon SageMaker and deploying them on SageMaker endpoints.","Amazon Bedrock, offering serverless access to a choice of foundation models through a single API."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is Amazon Bedrock. It provides a fully managed service that offers serverless access to a variety of foundation models from Amazon and third-party providers through a single API, eliminating the need for infrastructure management and enabling rapid experimentation. Option A (incorrect) Amazon SageMaker JumpStart provides pre-trained models but often requires more deployment and management effort compared to Bedrock''s serverless API access for FMs. Option B (incorrect) involves significant operational overhead for self-hosting and managing LLMs, which contradicts the requirement for no infrastructure management. Option C (incorrect) building custom models from scratch is time-consuming and expensive, and not suitable for rapid experimentation with existing FMs.', 6, 'm_6_3', 3, NULL, NULL),
  ('mock_5_all_1774921043968', 'A research institution is developing a semantic search engine for its archive of millions of scientific publications. The goal is to allow researchers to find papers conceptually similar to their queries, rather than just keyword matches. This requires converting documents into vector embeddings and storing them in a database optimized for efficient similarity search. Which AWS service, combined with an appropriate extension, is best suited for this purpose?', '["Amazon DynamoDB, storing document text and performing string matching.","Amazon S3, storing document files and using S3 Select for content filtering.","Amazon OpenSearch Service with k-NN (k-Nearest Neighbor) search capabilities for vector embeddings.","Amazon Relational Database Service (Amazon RDS) with a standard SQL database for keyword indexing."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is Amazon OpenSearch Service with k-NN search capabilities. OpenSearch Service provides a scalable and managed solution for storing vector embeddings and performing efficient k-Nearest Neighbor (k-NN) searches, which is essential for semantic similarity search. Option A (incorrect) Amazon DynamoDB is a key-value store and is not optimized for vector similarity search, only exact-match lookups. Option B (incorrect) Amazon S3 is object storage and while it can store files, it does not natively support efficient semantic similarity search on document embeddings. Option D (incorrect) Amazon RDS with a standard SQL database is primarily for structured data and keyword indexing, not efficient vector similarity search, though pgvector extension can add this capability, OpenSearch is often preferred for large-scale text search.', 6, 'm_6_3', 4, NULL, NULL),
  ('mock_5_all_1774921043968', 'A startup wants to integrate a large language model (LLM) into their customer support chatbot. They need to quickly deploy a pre-trained model and scale it without managing any underlying infrastructure, prioritizing the LEAST operational overhead.', '["Utilize Amazon Bedrock to access a managed foundation model through an API.","Deploy a pre-trained model from Amazon SageMaker JumpStart onto a dedicated Amazon SageMaker Endpoint.","Provision Amazon EC2 instances, install open-source LLM frameworks, and deploy a self-managed model.","Develop a custom LLM from scratch and deploy it using Amazon SageMaker hosting services."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most suitable choice because Amazon Bedrock provides serverless access to leading foundation models through an API, requiring no infrastructure management. This directly addresses the need for the LEAST operational overhead and quick deployment. Option B (incorrect) involves deploying a model on a SageMaker Endpoint, which, while managed, still requires more operational effort than Bedrock, such as endpoint configuration and scaling policies. Option C (incorrect) represents a significant operational burden, as it requires managing EC2 instances, software installations, and scaling, directly violating the ''LEAST operational overhead'' constraint (anti-pattern ap-2.3-001). Option D (incorrect) is the most complex and time-consuming approach, requiring extensive development and management, which is contrary to the requirement for quick deployment and minimal overhead.', 6, 'm_6_3', 5, NULL, NULL),
  ('mock_5_all_1774921043968', 'An enterprise is building a retrieval-augmented generation (RAG) system to allow employees to query internal documentation. The system must efficiently find semantically similar documents to ground LLM responses, requiring the MOST efficient semantic search capabilities.', '["Store documents in Amazon S3 and use keyword search for retrieval.","Implement Amazon OpenSearch Service with k-NN vector search capabilities for document embeddings.","Store document metadata in Amazon DynamoDB and perform exact-match lookups.","Use Amazon RDS for PostgreSQL without the pgvector extension to store document text."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most efficient solution. Amazon OpenSearch Service, when configured with k-NN (k-Nearest Neighbor) vector search, is specifically designed for performing semantic similarity searches on vector embeddings. This allows the RAG system to find documents that are conceptually similar to the user''s query, which is crucial for grounding LLM responses effectively. Option A (incorrect) relies on Amazon S3 for storage and keyword search, which is not efficient for semantic similarity and would not effectively find conceptually related documents. Option C (incorrect) uses Amazon DynamoDB for key-value lookups, which only supports exact-match retrieval and is unsuitable for semantic search across embeddings (anti-pattern ap-2.3-002). Option D (incorrect) uses Amazon RDS for PostgreSQL without the pgvector extension, meaning it lacks the native capabilities for efficient vector storage and similarity search required for RAG.', 6, 'm_6_3', 6, NULL, NULL),
  ('mock_5_all_1774921043968', 'A data science team needs to deploy a pre-trained image generation model from a public repository, but also requires the flexibility to fine-tune it with their own dataset later. They seek a solution that balances ease of initial deployment with future customization potential.', '["Access a pre-trained image generation model directly via Amazon Bedrock''s managed APIs.","Deploy the pre-trained model using Amazon SageMaker JumpStart and then use SageMaker for fine-tuning.","Utilize AWS Inferentia instances to host a custom-built model for inference.","Manually download the model, set up a deep learning environment on Amazon EC2, and manage the entire lifecycle."]'::jsonb, 'mcq', '{2}'::integer[], 'Option B (correct) provides the best balance. Amazon SageMaker JumpStart offers a streamlined way to discover and deploy a wide range of pre-trained models, including image generation models, with just a few clicks. Once deployed, these models are within the SageMaker ecosystem, allowing the team to easily leverage SageMaker''s comprehensive tools for fine-tuning with their own datasets. Option A (incorrect) offers ease of use but less flexibility for deep fine-tuning of the model architecture itself, as Bedrock primarily provides API access to pre-trained models. Option C (incorrect) focuses on inference hardware (AWS Inferentia) and doesn''t directly address the deployment or fine-tuning platform for a pre-trained model. Option D (incorrect) involves significant operational overhead for setup and management, which goes against the ''ease of initial deployment'' aspect.', 6, 'm_6_3', 7, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_6_1
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_5_all_1774921043968', 'A marketing team is using a large language model to generate creative ideas for new product campaigns. They observe that the model''s outputs are often too similar and lack the desired level of creativity and variation. To encourage more diverse and imaginative suggestions, which inference parameter should they adjust, and in what direction?', '["Decrease the `temperature` parameter to make the output more deterministic.","Increase the `max tokens` parameter to allow for longer, more detailed responses.","Decrease the `top-p` parameter to narrow down the range of possible token choices.","Increase the `temperature` parameter to introduce more randomness and creativity."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is the right approach. Increasing the `temperature` parameter makes the model''s output more random and creative by allowing it to consider a wider range of tokens for each step, leading to more diverse and imaginative suggestions. Option A (incorrect) would make the output more deterministic and less creative, which is the opposite of the desired outcome for brainstorming. Option B (incorrect) controls the length of the output, not its creativity or diversity. Option C (incorrect) `top-p` also controls diversity, but decreasing it would narrow the token choices, making the output less diverse and more focused.', 6, 'm_6_1', 8, NULL, NULL),
  ('mock_5_all_1774921043968', 'A developer is using a generative AI model to assist with code generation. They frequently notice that the generated code snippets are incomplete or abruptly truncated, even when the expected output should be longer. The developer needs to ensure the model can provide full, complete responses without being cut off prematurely. Which inference parameter should the developer review and potentially increase?', '["`max tokens`","`temperature`","`top-p`","`seed`"]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is `max tokens`. This parameter directly controls the maximum number of tokens the model will generate in its response. If the output is truncated, increasing `max tokens` will allow the model to produce longer, more complete responses, addressing the issue of incomplete code snippets. Option B (incorrect) `temperature` controls the randomness of the output, not its length. Option C (incorrect) `top-p` controls the diversity of the output by sampling from a cumulative probability distribution. Option D (incorrect) `seed` ensures reproducibility of random generation, but doesn''t affect output length.', 6, 'm_6_1', 9, NULL, NULL),
  ('mock_5_all_1774921043968', 'A company has deployed a generative AI-powered chatbot for customer support. Users have reported instances where the chatbot provides confident, yet factually incorrect, answers regarding company policies or product specifications. This phenomenon, where LLMs generate plausible but false information, is known as a hallucination. To mitigate this risk for high-stakes customer interactions, what is a crucial step to implement?', '["Increase the `temperature` parameter to encourage more creative and varied responses.","Implement a human review process for high-stakes responses or ground the LLM with a reliable knowledge base.","Decrease the `max tokens` parameter to limit the length of potentially incorrect responses.","Rely solely on the LLM''s pre-trained knowledge, assuming it covers all possible customer queries."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is crucial for mitigating hallucinations. For factual or high-stakes tasks, LLM outputs should never be trusted without validation. Implementing a human review process for critical responses or grounding the LLM with a reliable, up-to-date knowledge base (e.g., using RAG) are effective strategies to ensure factual accuracy. Option A (incorrect) increasing `temperature` would likely increase creativity and randomness, potentially exacerbating hallucinations, not mitigating them. Option C (incorrect) decreasing `max tokens` would only shorten the response, not prevent the generation of incorrect information. Option D (incorrect) relying solely on the LLM''s pre-trained knowledge without validation is an anti-pattern that directly leads to hallucinations and is unsuitable for factual tasks.', 6, 'm_6_1', 10, NULL, NULL),
  ('mock_5_all_1774921043968', 'A digital media company is developing a new application that allows users to create unique visual artwork by simply providing text descriptions. The application needs to generate high-quality images that accurately reflect the user''s textual input. Which generative AI modality is primarily responsible for creating new images from text prompts?', '["Image generation.","Text generation.","Audio generation.","Code generation."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is image generation. This generative AI modality is specifically designed to create new visual content, such as images or artwork, from various inputs, most commonly text descriptions (text-to-image). Option B (incorrect) text generation focuses on producing human-like text. Option C (incorrect) audio generation creates new audio content. Option D (incorrect) code generation produces programming code.', 6, 'm_6_1', 11, NULL, NULL),
  ('mock_5_all_1774921043968', 'A content creation team uses an LLM to generate marketing copy. They find the initial zero-shot responses too generic. To improve the relevance and style of the generated text for specific campaigns, they want to provide examples to the model with the LEAST effort in model retraining.', '["Apply zero-shot prompting with more detailed instructions.","Implement few-shot prompting by including relevant examples within the prompt itself.","Fine-tune the foundation model with a large dataset of desired marketing copy examples.","Adjust the model''s temperature parameter to a very low value (e.g., 0) for more deterministic output."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most effective approach for improving relevance and style with the LEAST effort in model retraining. Few-shot prompting involves providing a few examples of desired input-output pairs directly in the prompt, which guides the LLM to generate responses in the desired style and format without requiring any model retraining or fine-tuning. Option A (incorrect) is a basic prompt engineering technique but might not be sufficient to overcome generic responses without examples. Option C (incorrect) involves fine-tuning, which is a resource-intensive and time-consuming process requiring curated training data and compute, making it a high-effort solution (anti-pattern ap-2.2-001). Option D (incorrect) would make the output more deterministic and less creative, which is generally counterproductive for marketing copy that aims for relevance and style, and does not leverage examples to guide the model (anti-pattern ap-2.1-001).', 6, 'm_6_1', 12, NULL, NULL),
  ('mock_5_all_1774921043968', 'A creative writing agency wants to use a generative AI model to brainstorm diverse story ideas and generate varied dialogue options for characters. They need the model to produce a wide range of unique and imaginative outputs, prioritizing HIGH creativity and diversity.', '["Set the model''s temperature inference parameter to a higher value (e.g., 0.7-1.0).","Set the model''s temperature inference parameter to 0.","Increase the `max_tokens` inference parameter to generate longer outputs.","Utilize only zero-shot prompting with very concise instructions."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most effective way to achieve high creativity and diversity in generative AI outputs. A higher temperature value (typically between 0.7 and 1.0) makes the model''s output more random and varied, encouraging it to explore a wider range of possibilities and generate more imaginative responses. Option B (incorrect) would make the model''s output highly deterministic and focused, producing less diverse and creative results, which is an anti-pattern for creative use cases (anti-pattern ap-2.1-001). Option C (incorrect) controls the maximum length of the generated output, not its creativity or diversity. Option D (incorrect) provides minimal guidance to the model and does not inherently promote diversity or creativity; it might even lead to more generic outputs.', 6, 'm_6_1', 13, NULL, NULL),
  ('mock_5_all_1774921043968', 'A legal firm uses an LLM to summarize lengthy legal documents, some of which exceed 100,000 words. The current model frequently truncates content, leading to incomplete summaries. They need a strategy to process these long documents effectively without losing critical information.', '["Ignore the context window limits, assuming the model will adapt to longer inputs.","Implement chunking strategies to break down documents into smaller, manageable sections and process them iteratively.","Increase the `max_tokens` inference parameter to allow the model to process more input.","Switch to a foundation model known to have a significantly smaller context window."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the appropriate strategy. LLMs have finite context windows, and content exceeding this limit will be truncated or ignored. Implementing chunking strategies involves breaking down long documents into smaller segments that fit within the model''s context window. These segments can then be processed iteratively (e.g., summarized individually and then combined) to ensure no critical information is lost. Option A (incorrect) is a common misconception and an anti-pattern (ap-2.1-003); ignoring context window limits will inevitably lead to truncation and incomplete responses. Option C (incorrect) controls the maximum length of the model''s *output*, not the size of its *input* context window. Option D (incorrect) would exacerbate the problem by reducing the amount of text the model can process at once, leading to even more truncation.', 6, 'm_6_1', 14, NULL, NULL);

