-- Module: m_6_2
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_5_all_1774921043968', 'A legal department aims to use generative AI for summarizing complex legal documents and answering specific questions about their content. The primary concern is ensuring the AI''s responses are factually accurate, directly grounded in the provided documents, and avoid generating incorrect or fabricated information (hallucinations). Which generative AI technique is best suited to meet these requirements?', '["Fine-tuning a foundation model on a large dataset of legal documents to specialize its knowledge.","Using a base foundation model directly and relying on its pre-trained knowledge to interpret legal texts.","Implementing Retrieval-Augmented Generation (RAG) by connecting a foundation model to a knowledge base of the legal documents.","Prompt engineering with very detailed, long prompts that include all relevant sections of the legal documents for summarization."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is implementing Retrieval-Augmented Generation (RAG). RAG directly addresses the concern of factual accuracy and hallucinations by grounding the LLM''s responses in specific, verifiable information retrieved from the legal documents, ensuring the output is fact-based. Option A (incorrect) fine-tuning can specialize a model but does not guarantee factual accuracy or prevent hallucinations, and it''s expensive and time-consuming. Option B (incorrect) using a base foundation model without grounding it in company-specific knowledge will likely lead to hallucinations and incorrect answers due to its knowledge cutoff and lack of proprietary context. Option D (incorrect) while detailed prompts are helpful, including entire long documents in prompts can quickly exceed context window limits and is not a scalable solution for large document repositories.', 6, 'm_6_2', 15, NULL, NULL),
  ('mock_5_all_1774921043968', 'A software development team wants to enhance developer productivity by integrating an AI assistant directly into their integrated development environment (IDE). This assistant should be capable of generating code, suggesting fixes, explaining complex code, and answering technical questions, all while understanding the context of their specific codebase. Which AWS service is designed to provide this kind of generative AI-powered assistance for developers?', '["Amazon Bedrock, used to deploy a general-purpose code generation model.","Amazon SageMaker JumpStart, to find and deploy a pre-trained code generation model.","Amazon Q Developer, specifically designed for developer assistance and code generation.","Amazon OpenSearch Service, used as a vector database for code embeddings."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is Amazon Q Developer. This service is specifically designed as a generative AI-powered assistant for developers, offering capabilities like code generation, debugging, explanation, and answering technical questions within the context of a codebase and IDE. Option A (incorrect) Amazon Bedrock provides access to foundation models, but Amazon Q Developer is tailored for the specific developer assistance use case. Option B (incorrect) Amazon SageMaker JumpStart helps deploy pre-trained models, but Amazon Q Developer offers a more integrated and context-aware experience for developers. Option D (incorrect) Amazon OpenSearch Service is a vector database for RAG, not an AI assistant itself.', 6, 'm_6_2', 16, NULL, NULL),
  ('mock_5_all_1774921043968', 'A marketing team wants to generate unique, personalized product descriptions for their extensive catalog of over a million items. They aim to achieve this efficiently, without the high cost and time investment typically associated with training custom machine learning models or extensive data labeling. Which generative AI strategy offers the most cost-effective and rapid solution for this content generation task?', '["Utilizing prompt engineering techniques with a pre-trained foundation model to generate descriptions based on product attributes.","Developing a custom neural network model from scratch using Amazon SageMaker.","Fine-tuning a large foundation model on a custom dataset of existing product descriptions.","Manually writing a template-based system to combine product attributes into descriptions."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is utilizing prompt engineering techniques with a pre-trained foundation model. This approach is highly cost-effective and rapid because it leverages existing, powerful models and requires no model training or extensive data labeling, aligning with the business constraint. Option B (incorrect) developing a custom neural network model from scratch is extremely expensive and time-consuming, requiring deep ML expertise. Option C (incorrect) fine-tuning a foundation model is also expensive and time-consuming, requiring curated training data, and is often an overkill when well-designed prompts can achieve the desired results. Option D (incorrect) manually writing a template-based system would be very labor-intensive and lack the uniqueness and personalization capabilities of generative AI.', 6, 'm_6_2', 17, NULL, NULL),
  ('mock_5_all_1774921043968', 'A financial institution needs to automate the process of extracting critical data points and generating concise summaries from thousands of unstructured financial reports daily. The solution must accurately identify key information and present it in an easily digestible format for analysts, significantly reducing manual review time. Which generative AI use case directly addresses this business problem?', '["Code generation.","Sentiment analysis.","Summarization.","Translation."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is summarization. This generative AI use case is specifically designed to condense lengthy text documents into shorter, coherent summaries, which directly addresses the need to extract critical data points and present them concisely from financial reports. Option A (incorrect) code generation is for producing programming code. Option B (incorrect) sentiment analysis focuses on identifying the emotional tone of text. Option D (incorrect) translation is for converting text between different languages.', 6, 'm_6_2', 18, NULL, NULL),
  ('mock_5_all_1774921043968', 'A large financial institution wants to deploy an internal chatbot for employees to ask questions about company policies and proprietary financial products. The chatbot must provide accurate, up-to-date, and company-specific answers, avoiding generic or incorrect information.', '["Use a base foundation model directly, relying on its pre-training knowledge.","Implement Retrieval-Augmented Generation (RAG) using Amazon Bedrock Knowledge Bases to ground responses in company documentation.","Fine-tune a foundation model extensively with all proprietary company data.","Rely solely on prompt engineering with the base model to guide its responses."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most effective and practical solution. Implementing Retrieval-Augmented Generation (RAG) with Amazon Bedrock Knowledge Bases allows the LLM to retrieve relevant information from proprietary company documentation and use it to ground its responses. This ensures the chatbot provides accurate, up-to-date, and company-specific answers, overcoming the knowledge cutoff of base models and preventing generic or incorrect information (anti-pattern ap-2.2-002). Option A (incorrect) will result in generic answers and cannot access proprietary company information, as base models have a knowledge cutoff and no access to internal data. Option C (incorrect) is a valid approach for deep customization but is significantly more expensive, time-consuming, and complex than RAG for this use case, especially when the primary goal is to ground responses in existing documentation (anti-pattern ap-2.2-001). Option D (incorrect) will not enable the base model to access proprietary information or overcome its knowledge cutoff, leading to generic or potentially incorrect answers.', 6, 'm_6_2', 19, NULL, NULL),
  ('mock_5_all_1774921043968', 'A marketing department needs to adapt a general-purpose LLM to generate product descriptions for a niche e-commerce catalog. They have a small dataset of existing product descriptions and need to achieve this adaptation with the MOST cost-effective and fastest approach.', '["Fine-tune a foundation model with the small dataset of product descriptions.","Implement prompt engineering techniques, potentially with few-shot examples, to guide the LLM''s output.","Develop a custom generative model from scratch specifically for product descriptions.","Utilize Amazon Bedrock Agents to automate the entire product description generation workflow."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) represents the MOST cost-effective and fastest approach. Prompt engineering, especially with few-shot examples, can effectively guide a general-purpose LLM to generate outputs in a desired style and format using a small number of examples directly within the prompt. This avoids the significant cost and time investment associated with model training. Option A (incorrect) involves fine-tuning, which, while effective for deeper customization, is a more expensive and time-consuming process requiring curated training data and compute resources, making it suboptimal for the ''most cost-effective and fastest'' constraint (anti-pattern ap-2.2-001). Option C (incorrect) is the most resource-intensive and time-consuming option, requiring deep ML expertise and significant compute. Option D (incorrect) is designed for orchestrating complex multi-step workflows with LLMs and external tools, which adds complexity and cost, and is not the primary method for adapting an LLM''s output style for a niche domain.', 6, 'm_6_2', 20, NULL, NULL),
  ('mock_5_all_1774921043968', 'A healthcare provider is developing an AI assistant to help doctors quickly access patient medical history and drug interaction information. The system''s output must be factually accurate and reliable, as errors could have severe consequences.', '["Implement human review and validation of LLM outputs, potentially combined with RAG from authoritative medical databases.","Trust LLM outputs without any validation, assuming high accuracy for medical information.","Set the model''s temperature inference parameter to 0 to ensure deterministic responses.","Rely solely on increasing the `max_tokens` inference parameter to ensure comprehensive output."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the only acceptable approach for high-stakes applications like healthcare. LLMs are known to hallucinate, generating plausible-sounding but incorrect information. For critical tasks where factual accuracy is paramount, human review and validation of all LLM outputs are mandatory. Combining this with Retrieval-Augmented Generation (RAG) from authoritative medical databases further grounds the LLM''s responses in verified information, significantly increasing reliability. Option B (incorrect) is a dangerous anti-pattern (ap-2.1-002); trusting LLM outputs without validation for factual or high-stakes tasks can lead to severe consequences. Option C (incorrect) setting the temperature to 0 makes the output deterministic but does not prevent hallucinations or guarantee factual accuracy, as the model''s knowledge is still limited to its training data and prone to generating incorrect information (anti-pattern ap-2.1-001). Option D (incorrect) only controls the length of the generated output and has no bearing on its factual accuracy or reliability.', 6, 'm_6_2', 21, NULL, NULL);

