-- Module: m_7_1
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_5_all_1774921043968', 'A startup is developing a chatbot for customer support that answers common FAQs. The primary requirements are low inference latency for real-time user interaction and the MOST cost-effective solution, as the startup has a limited budget. The answers are straightforward and do not require complex reasoning or extensive knowledge beyond the FAQs. Which design consideration for selecting a foundation model is MOST appropriate?', '["Select a smaller, specialized foundation model optimized for quick responses and lower token costs.","Choose the largest available general-purpose foundation model to ensure the highest possible accuracy.","Implement Retrieval Augmented Generation (RAG) with an Amazon Bedrock Knowledge Base to provide dynamic information.","Fine-tune a foundation model on a custom dataset of customer interactions to improve response quality."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most appropriate design consideration. For straightforward FAQ answers with low latency and cost constraints, a smaller, specialized foundation model is ideal. These models typically have lower inference latency and significantly lower per-token costs compared to larger models, while still providing sufficient accuracy for simple tasks. Option B (incorrect) choosing the largest available general-purpose model would lead to higher costs per token and increased latency, which directly contradicts the ''MOST cost-effective'' and ''low inference latency'' requirements (ap-3.1-001). Option C (incorrect) implementing RAG with an Amazon Bedrock Knowledge Base adds complexity and cost that is unnecessary for simple, static FAQs; RAG is better suited for dynamic or proprietary information. Option D (incorrect) fine-tuning a model would incur additional training costs and operational overhead, which is not the most cost-effective solution for a simple FAQ chatbot, especially given the limited budget.', 7, 'm_7_1', 6, NULL, NULL),
  ('mock_5_all_1774921043968', 'A pharmaceutical company needs to build an AI assistant that can answer complex questions based on its vast repository of internal research papers, clinical trial results, and proprietary drug formulations. The company wants to ensure the assistant provides accurate and up-to-date information without modifying the underlying foundation model. The key constraint is to provide relevant answers from internal data without expensive model fine-tuning. Which Amazon Bedrock capability should be utilized?', '["Amazon Bedrock Knowledge Bases for Retrieval Augmented Generation (RAG).","Fine-tuning a pre-trained foundation model on the company''s proprietary dataset.","Using Amazon Bedrock Guardrails to filter out irrelevant information from public sources.","Selecting the largest available foundation model and relying on its general knowledge."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most suitable capability. Amazon Bedrock Knowledge Bases, used for Retrieval Augmented Generation (RAG), allow foundation models to access, retrieve, and synthesize information from proprietary data sources in real-time. This ensures accurate and up-to-date answers grounded in internal documents without the need for expensive and time-consuming model fine-tuning. Option B (incorrect) fine-tuning a foundation model on proprietary data is a valid customization approach, but the scenario explicitly states the constraint of ''without expensive model fine-tuning,'' making RAG a more appropriate choice for this specific requirement. Option C (incorrect) Amazon Bedrock Guardrails are designed for content moderation and safety, not for retrieving specific information from internal knowledge bases. Option D (incorrect) selecting the largest available foundation model would be more costly and would not inherently provide access to the company''s proprietary internal documents, as its training data is general-purpose (ap-3.1-001).', 7, 'm_7_1', 7, NULL, NULL),
  ('mock_5_all_1774921043968', 'An e-commerce company wants to automate complex customer service workflows. This involves steps like checking order status in a database, updating shipping information via an API, and then sending a personalized email confirmation. The company needs a solution that can orchestrate these multi-step tasks using natural language instructions. Which Amazon Bedrock service is designed to automate such multi-step processes?', '["Amazon Bedrock Agents.","Amazon Bedrock Knowledge Bases.","Amazon Bedrock Model Evaluation.","Amazon Bedrock Guardrails."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the appropriate Amazon Bedrock service. Amazon Bedrock Agents are specifically designed to enable foundation models to perform multi-step tasks by orchestrating interactions with external systems, such as databases and APIs, based on natural language instructions. This perfectly matches the requirement to automate complex customer service workflows involving multiple steps and external integrations. Option B (incorrect) Amazon Bedrock Knowledge Bases are used for Retrieval Augmented Generation (RAG), allowing models to retrieve information from proprietary data, but they do not orchestrate multi-step actions. Option C (incorrect) Amazon Bedrock Model Evaluation is used to assess the performance and quality of foundation models, not to automate workflows. Option D (incorrect) Amazon Bedrock Guardrails are used for content moderation and safety, ensuring model outputs are safe and on-topic, not for orchestrating tasks.', 7, 'm_7_1', 8, NULL, NULL),
  ('mock_5_all_1774921043968', 'A creative marketing agency is using an Amazon Bedrock model to generate taglines for new products. They want to experiment with different levels of creativity and randomness in the generated outputs to find the most engaging options. Which inference parameter should the agency adjust to control the creativity and diversity of the model''s responses?', '["Temperature.","Max tokens.","Top K.","Stop sequences."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the inference parameter that controls the creativity and diversity of the model''s responses. A higher temperature value makes the output more random and creative, while a lower temperature makes it more deterministic and focused. This directly addresses the need to experiment with different levels of creativity. Option B (incorrect) `max_tokens` controls the maximum length of the generated output, not its creativity or randomness. Option C (incorrect) `Top K` sampling limits the model''s token selection to the top K most probable tokens, which can influence diversity but is not the primary control for overall creativity as temperature is. Option D (incorrect) `stop_sequences` are specific strings that, when generated, cause the model to stop generating further tokens, which is used for controlling output structure or preventing unwanted continuation, not creativity.', 7, 'm_7_1', 9, NULL, NULL),
  ('mock_5_all_1774921043968', 'A media company is developing an application that needs to process both text descriptions and images from user submissions to generate rich, contextual stories. For example, a user might upload a photo and provide a short caption, and the application needs to understand both to create a narrative. Which type of foundation model is BEST suited for this use case, considering the need to handle diverse input modalities?', '["A multi-modal foundation model capable of processing and generating content across different modalities like text and images.","A large language model (LLM) that can process text, and a separate image recognition service like Amazon Rekognition to analyze images.","A text-only foundation model, relying on users to describe images comprehensively in their captions.","A fine-tuned language model that has been trained extensively on textual descriptions of images."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the best choice. A multi-modal foundation model is specifically designed to understand and generate content across different modalities, such as text and images, making it ideal for applications that require processing diverse inputs like photos and captions to create a unified narrative. Option B (incorrect) using separate services for each modality (an LLM for text and Amazon Rekognition for images) would require complex orchestration and integration logic to combine the insights, which is less efficient and more complex than a single multi-modal model. Option C (incorrect) relying on a text-only model and user-provided descriptions for images would limit the application''s ability to truly ''understand'' the visual content, potentially leading to less rich or accurate narratives. Option D (incorrect) while fine-tuning a language model on image descriptions could improve its textual understanding of visual concepts, it would still not enable the model to directly process and interpret image pixels, thus failing to fully support multi-modal inputs.', 7, 'm_7_1', 10, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_7_4
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_5_all_1774921043968', 'A content moderation team is evaluating a new generative AI model for an online forum. They need to ensure the model''s outputs are not only grammatically correct but also factually accurate and coherent within the context of discussions. The team is concerned that automated metrics like BLEU and ROUGE might not fully capture these qualitative aspects. Which evaluation method should they prioritize to COMPREHENSIVELY assess the generative model''s quality?', '["Human evaluation by expert reviewers for factual accuracy, coherence, and contextual relevance, complemented by automated metrics.","Solely rely on automated metrics such as BLEU and ROUGE scores to quantify the n-gram overlap with reference texts.","Conduct A/B testing with users and gather feedback on preference, without specific qualitative analysis.","Increase the model''s context window to provide more input, assuming this will inherently improve factual accuracy and coherence."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most comprehensive evaluation method. Human evaluation by expert reviewers is crucial for assessing subjective qualities like factual accuracy, coherence, and contextual relevance, which automated metrics often fail to capture. Complementing this with automated metrics provides a balanced and thorough assessment. This directly addresses the anti-pattern of relying solely on automated metrics (ap-3.1-002). Option B (incorrect) solely relying on automated metrics like BLEU and ROUGE is insufficient because these metrics primarily measure n-gram overlap and do not reliably assess semantic quality, factual accuracy, or coherence, which are critical for generative models (ap-3.1-002). Option C (incorrect) A/B testing can provide user preference data but does not offer the granular qualitative analysis needed to understand *why* certain outputs are better or worse in terms of factual accuracy and coherence. Option D (incorrect) increasing the context window might provide the model with more information, but it does not guarantee improved factual accuracy or coherence, nor does it provide a method for evaluating these aspects.', 7, 'm_7_4', 11, NULL, NULL),
  ('mock_5_all_1774921043968', 'A social media platform is integrating an Amazon Bedrock-powered chatbot for user interactions. The platform has strict community guidelines and needs to prevent the chatbot from generating harmful, biased, or off-topic content. The primary requirement is to ENSURE safe and responsible outputs from the foundation model. Which Amazon Bedrock feature should the platform implement?', '["Amazon Bedrock Guardrails.","Amazon Bedrock Knowledge Bases.","Amazon Bedrock Model Evaluation.","Fine-tuning the foundation model on a curated dataset of safe interactions."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the appropriate Amazon Bedrock feature. Amazon Bedrock Guardrails are specifically designed to implement content moderation, enforce safety policies, filter harmful content, and ensure model outputs remain on-topic and aligned with brand guidelines. This directly addresses the anti-pattern of deploying a foundation model application without content moderation guardrails (ap-3.4-001). Option B (incorrect) Amazon Bedrock Knowledge Bases are used for Retrieval Augmented Generation (RAG) to ground models in proprietary data, not for content moderation or safety. Option C (incorrect) Amazon Bedrock Model Evaluation is used to assess model performance and quality, not to enforce real-time content safety. Option D (incorrect) while fine-tuning can influence model behavior, it is a more complex and less direct method for enforcing strict content policies in real-time compared to dedicated guardrails, and it doesn''t fully eliminate the risk of unintended harmful outputs without additional safeguards.', 7, 'm_7_4', 12, NULL, NULL),
  ('mock_5_all_1774921043968', 'A product development team has implemented two different prompt engineering strategies for an Amazon Bedrock model generating marketing slogans. They want to objectively compare the effectiveness of these two strategies in terms of user engagement and conversion rates, without immediately impacting all users. Which evaluation method is MOST suitable for this comparison?', '["A/B testing or shadow deployment using Amazon Bedrock Model Evaluation features.","Manual review of a small sample of slogans by a single marketing expert.","Relying solely on automated metrics like ROUGE scores for slogan quality.","Increasing the model''s temperature parameter for both strategies to observe which generates more diverse options."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most suitable evaluation method. A/B testing or shadow deployment, often facilitated by Amazon Bedrock Model Evaluation features, allows the team to compare the performance of different prompt strategies in a controlled environment with real user traffic. This provides objective data on user engagement and conversion rates without immediately exposing all users to potentially suboptimal outputs. Option B (incorrect) manual review by a single expert is subjective, not scalable, and does not provide quantitative data on user engagement or conversion rates. Option C (incorrect) relying solely on automated metrics like ROUGE scores is insufficient for evaluating subjective qualities like marketing slogan effectiveness, user engagement, or conversion, as these metrics measure text overlap, not business impact (ap-3.1-002). Option D (incorrect) increasing the temperature parameter would affect the diversity of outputs but does not serve as an evaluation method for comparing the effectiveness of two distinct prompt strategies in a business context.', 7, 'm_7_4', 13, NULL, NULL),
  ('mock_5_all_1774921043968', 'A healthcare provider is deploying an AI assistant to help doctors quickly access patient information and medical guidelines. The primary business objective is to reduce the time doctors spend on information retrieval, thereby improving patient care efficiency. To determine the success of this AI assistant, which evaluation dimension should be the primary focus?', '["Task completion success rates and productivity gains for doctors.","Automated metrics such as BLEU and ROUGE scores for generated text.","The model''s inference latency and throughput.","The diversity and creativity of the model''s responses."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the primary evaluation dimension. Aligning evaluation with business objectives means focusing on metrics that directly measure the desired impact, such as task completion success rates (e.g., doctors finding information quickly) and productivity gains (e.g., reduced time spent on retrieval). This directly assesses the assistant''s effectiveness in improving patient care efficiency. Option B (incorrect) automated metrics like BLEU and ROUGE scores are primarily for text generation quality and do not directly measure the business impact or efficiency gains for doctors. Option C (incorrect) while inference latency and throughput are important performance metrics, they are secondary to the ultimate business objective of improving efficiency and patient care. Option D (incorrect) the diversity and creativity of responses are generally not relevant evaluation dimensions for a healthcare information retrieval assistant, where accuracy and efficiency are paramount.', 7, 'm_7_4', 14, NULL, NULL),
  ('mock_5_all_1774921043968', 'A public sector agency is developing an AI-powered content summarizer for public records. Due to the sensitive nature of the data, the agency is highly concerned about potential biases in the model''s summaries that could lead to unfair or inaccurate representations. They need a method to systematically detect and analyze bias in the foundation model''s outputs. Which AWS service or feature is BEST suited for this task?', '["Amazon SageMaker Clarify.","Amazon Bedrock Guardrails.","Amazon Bedrock Knowledge Bases.","Iterative prompt engineering with human review."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the best-suited AWS service. Amazon SageMaker Clarify is specifically designed to help detect potential bias in machine learning models, including foundation models, and explain their predictions. It can analyze various types of bias in datasets and models, which is crucial for addressing concerns about unfair or inaccurate representations in sensitive public records. Option B (incorrect) Amazon Bedrock Guardrails are primarily for content moderation and ensuring safe, on-topic outputs, not for systematically detecting and analyzing inherent model biases in a structured way. Option C (incorrect) Amazon Bedrock Knowledge Bases are used for Retrieval Augmented Generation (RAG) to ground models in proprietary data, which is unrelated to bias detection. Option D (incorrect) while iterative prompt engineering with human review can help identify some obvious biases, it is not a systematic or scalable method for comprehensive bias detection and analysis across a large dataset or for complex models.', 7, 'm_7_4', 15, NULL, NULL);

