INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_5_all_1774921043968', 'A manufacturing company wants to adapt a general-purpose foundation model to generate highly technical documentation for its specialized machinery. The model needs to understand and use proprietary terminology and specific operational procedures not present in its original training data. The company has a limited, high-quality dataset of existing technical manuals. Which approach is MOST effective for adapting the model to this specialized domain?', '["Fine-tuning the foundation model on the company''s domain-specific technical documentation.","Implementing Retrieval Augmented Generation (RAG) with an Amazon Bedrock Knowledge Base containing the manuals.","Using prompt engineering to provide detailed instructions and examples of the desired technical language.","Performing continued pre-training on a massive, diverse dataset of general technical texts."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most effective approach. Fine-tuning a foundation model on a high-quality, domain-specific dataset allows the model to learn and internalize the proprietary terminology, specific operational procedures, and the unique style required for technical documentation. This adapts the model''s core knowledge to the specialized domain. Option B (incorrect) while RAG with an Amazon Bedrock Knowledge Base can provide access to proprietary information, its primary function is retrieval and grounding, not to fundamentally adapt the model''s generation style or deep understanding of the domain''s nuances for generating new content. Option C (incorrect) prompt engineering can guide the model, but for deeply specialized terminology and complex procedural understanding, it is often insufficient to fully embed the required domain knowledge and generation style into the model. Option D (incorrect) continued pre-training is a much more resource-intensive and complex process, typically requiring massive datasets and significant computational power, which is overkill for adapting to a specific domain with a limited, high-quality dataset.', 7, 'm_7_3', 16, NULL, NULL),
  ('mock_5_all_1774921043968', 'A software development team is building a code generation assistant using Amazon Bedrock. They find that the base foundation model struggles to consistently follow complex coding instructions and generate code snippets that adhere to specific architectural patterns. The team wants to significantly improve the model''s ability to understand and execute instructions for various coding tasks. Which fine-tuning method is BEST suited for this objective?', '["Instruction tuning.","Continued pre-training.","Domain adaptation.","Reinforcement Learning from Human Feedback (RLHF)."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the best-suited fine-tuning method. Instruction tuning specifically focuses on improving a model''s ability to follow instructions and perform tasks as described in prompts. By fine-tuning on a dataset of diverse instructions and corresponding high-quality outputs, the model learns to better understand and execute complex commands, which is precisely what''s needed for a code generation assistant to adhere to specific architectural patterns. Option B (incorrect) continued pre-training involves further training on a large, general dataset, which might improve overall language understanding but is not targeted at instruction following. Option C (incorrect) domain adaptation focuses on making the model perform better in a specific domain (e.g., coding), but instruction tuning is more precise for improving instruction adherence within that domain. Option D (incorrect) RLHF is used to align model behavior with human preferences and values, often for safety or helpfulness, but it''s a more advanced technique and not the primary method for improving basic instruction following capabilities.', 7, 'm_7_3', 17, NULL, NULL),
  ('mock_5_all_1774921043968', 'A data science team needs to fine-tune a large foundation model on Amazon Bedrock for a niche legal domain. They have a relatively small, but highly relevant, dataset of legal documents. Given the size of the base model and the limited computational resources available, the team needs to fine-tune the model EFFICIENTLY while minimizing the number of parameters updated. Which technique is MOST appropriate?', '["Parameter-Efficient Fine-Tuning (PEFT) techniques like LoRA.","Full fine-tuning of all model parameters.","Continued pre-training on a larger, general legal corpus.","Reducing the size of the foundation model to a smaller variant before fine-tuning."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most appropriate technique. Parameter-Efficient Fine-Tuning (PEFT) techniques, such as LoRA (Low-Rank Adaptation), allow for efficient fine-tuning of large foundation models by only updating a small fraction of the model''s parameters. This significantly reduces computational resource requirements and training time, making it ideal for scenarios with limited resources and smaller datasets. Option B (incorrect) full fine-tuning of all model parameters is computationally expensive and requires substantial resources, which contradicts the requirement for efficient fine-tuning with limited resources. Option C (incorrect) continued pre-training involves training on a large corpus, which is a much more resource-intensive process than fine-tuning and is not suitable for adapting to a niche domain with a small dataset. Option D (incorrect) reducing the size of the foundation model might save resources, but it would mean losing the capabilities of the larger model and doesn''t address the efficiency of fine-tuning the *chosen* large model.', 7, 'm_7_3', 18, NULL, NULL),
  ('mock_5_all_1774921043968', 'A startup plans to fine-tune an Amazon Bedrock foundation model to generate personalized marketing emails. They have collected a small dataset of past successful email campaigns, but it is uncurated and contains inconsistencies and duplicates. The team expects significant improvement in email quality after fine-tuning. What is the MOST critical consideration for ensuring effective fine-tuning in this scenario?', '["Curating and expanding the dataset to ensure high quality, diversity, and representativeness before fine-tuning.","Proceeding with fine-tuning immediately, as the model will learn to filter out inconsistencies.","Switching to a larger, more powerful foundation model, which can handle low-quality data better.","Relying solely on advanced prompt engineering techniques to guide the model, instead of fine-tuning."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most critical consideration. The quality, diversity, and representativeness of the training data are paramount for effective fine-tuning. A small, uncurated dataset with inconsistencies will lead to suboptimal results, potentially causing the model to overfit or amplify existing biases rather than improve performance. This directly addresses the anti-pattern of fine-tuning on a small, low-quality dataset expecting significant improvement (ap-3.3-001). Option B (incorrect) proceeding with fine-tuning immediately on a low-quality dataset is an anti-pattern (ap-3.3-001) that will likely lead to poor model performance, as the model will learn from the inconsistencies and errors in the data. Option C (incorrect) larger models are not inherently better at handling low-quality data; they can still learn biases and errors from poor datasets, and choosing a larger model also increases costs (ap-3.1-001). Option D (incorrect) while prompt engineering is valuable, for deeply personalized and consistent marketing emails, fine-tuning provides a more robust and embedded solution for adapting the model''s generation style and knowledge, which cannot be fully achieved by prompts alone.', 7, 'm_7_3', 19, NULL, NULL),
  ('mock_5_all_1774921043968', 'A creative agency wants to use an Amazon Bedrock model to generate short stories in the distinctive style of a specific author. The base foundation model can generate coherent stories, but it lacks the unique vocabulary, sentence structure, and narrative voice of the desired author. The agency needs the model to produce outputs that closely mimic this specific style. Which customization approach is BEST suited for this requirement?', '["Fine-tuning the foundation model on a dataset of the author''s works to embed the specific style and tone.","Implementing Retrieval Augmented Generation (RAG) with an Amazon Bedrock Knowledge Base containing the author''s books.","Using Amazon Bedrock Guardrails to filter out any stories that do not match the author''s style.","Providing a single example of the author''s writing style in a one-shot prompt to guide the model."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the best-suited customization approach. Fine-tuning the foundation model on a dataset of the author''s works allows the model to learn and embed the specific vocabulary, sentence structure, narrative voice, and overall style directly into its parameters. This is the most effective way to make the model consistently generate content that closely mimics a particular artistic style. Option B (incorrect) RAG with an Amazon Bedrock Knowledge Base would allow the model to retrieve information from the author''s books, but its primary purpose is to ground factual responses, not to learn and reproduce a specific writing style for generative tasks. Option C (incorrect) Amazon Bedrock Guardrails are for content moderation and safety, not for enforcing a specific artistic style or tone in generated outputs. Option D (incorrect) while a one-shot prompt can provide a brief example, it is generally insufficient for a model to fully internalize and consistently reproduce a complex and nuanced writing style across multiple generations; fine-tuning provides a much deeper adaptation.', 7, 'm_7_3', 20, NULL, NULL);

