INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_5_all_1774921043968', 'A financial institution is developing an AI model to approve or deny loan applications. Due to regulatory requirements and ethical concerns, the institution must ensure the model''s decisions are fair and do not discriminate against protected groups. They need to detect and mitigate potential biases in the training data and model predictions before deployment.', '["Use Amazon SageMaker Clarify to analyze data and model for bias and explainability.","Implement Amazon Bedrock Guardrails to filter biased outputs from the model.","Utilize AWS Audit Manager to continuously monitor the model''s compliance with fairness regulations.","Deploy Amazon Macie to detect PII in the training data and redact it to prevent bias."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most effective solution. Amazon SageMaker Clarify provides tools to detect and measure bias in machine learning models and training data, and to help explain model predictions, directly addressing the need for fairness and bias mitigation. Option B (incorrect) is primarily for generative AI models on Amazon Bedrock to enforce content policies and is not designed for detecting bias in traditional ML models or training data. Option C (incorrect) is for automating audit evidence collection and compliance checks, which is a governance aspect, but not directly for detecting and mitigating bias within the model itself. Option D (incorrect) is used for discovering and protecting sensitive data (PII) across AWS, which is related to privacy, but not specifically for detecting or mitigating algorithmic or data bias in the context of model fairness.', 8, 'm_8_1', 1, NULL, NULL),
  ('mock_5_all_1774921043968', 'A healthcare provider is building an AI system to assist doctors in diagnosing rare diseases. Given the high-stakes nature of medical diagnoses, the system must incorporate mechanisms to prevent incorrect automated decisions from being directly applied without expert review. The goal is to ensure human accountability and error correction.', '["Rely solely on the AI model''s high accuracy metrics to make direct diagnoses.","Implement a human-in-the-loop pattern where AI predictions are reviewed by medical professionals before final action.","Configure Amazon Bedrock Guardrails to automatically correct any misdiagnoses made by the AI system.","Use Amazon Macie to ensure patient data privacy, which indirectly improves diagnostic accuracy."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the appropriate approach. Implementing a human-in-the-loop pattern ensures that human experts review and validate AI predictions, especially in high-stakes domains like healthcare, preventing unchecked AI errors and maintaining accountability. This directly addresses anti-pattern [ap-4.1-002]. Option A (incorrect) represents anti-pattern [ap-4.1-002] by deploying AI in high-stakes decisions without human oversight, which can lead to significant harm if the model makes errors. Option C (incorrect) is designed for generative AI models to enforce content policies and is not applicable for correcting diagnostic predictions from a traditional AI system. Option D (incorrect) focuses on data privacy, which is important, but does not address the need for human oversight in decision-making.', 8, 'm_8_1', 2, NULL, NULL),
  ('mock_5_all_1774921043968', 'A company is developing a new generative AI application using Amazon Bedrock for customer service. They are concerned about the model generating harmful, biased, or off-topic content. They need a proactive mechanism to filter undesirable outputs and enforce brand guidelines with the LEAST development effort.', '["Manually review all generated content before it reaches customers.","Develop custom post-processing Lambda functions to filter model outputs.","Implement Amazon Bedrock Guardrails to define and enforce content policies.","Use Amazon SageMaker Clarify to detect bias in the training data of the generative model."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the most efficient solution. Amazon Bedrock Guardrails allows defining safety policies, content filters, and custom rules to control the behavior and output of generative AI models, ensuring they adhere to brand guidelines and avoid harmful content with minimal development effort. Option A (incorrect) is a manual and highly inefficient process that does not scale for a customer service application. Option B (incorrect) would require significant custom development and maintenance, increasing operational overhead compared to a managed service like Guardrails. Option D (incorrect) is used for detecting bias and explaining predictions in traditional ML models and training data, not for proactively filtering outputs of generative AI models in real-time based on content policies.', 8, 'm_8_1', 3, NULL, NULL),
  ('mock_5_all_1774921043968', 'An e-commerce company uses an AI model to personalize product recommendations. They discover that the model disproportionately recommends high-priced items to certain demographics, leading to concerns about fairness and potential bias. They want to analyze the model''s behavior to understand and address this issue.', '["Use AWS Audit Manager to review the model''s deployment logs for compliance.","Implement Amazon Macie to identify sensitive customer data used by the model.","Develop a custom monitoring dashboard using Amazon CloudWatch to track recommendation patterns.","Utilize Amazon SageMaker Clarify to analyze the model for bias and explain its recommendations."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is the most suitable service. Amazon SageMaker Clarify is specifically designed to help detect and measure bias in ML models and their training data, as well as provide explainability for model predictions. This directly addresses the need to understand why certain demographics receive specific recommendations and to identify potential fairness issues. Option A (incorrect) is for auditing compliance and governance, not for direct bias detection or model explainability. Option B (incorrect) focuses on PII detection and protection, which is related to privacy but not directly to algorithmic bias in recommendations. Option C (incorrect) could show patterns but wouldn''t inherently explain the root causes of bias or provide the specific metrics and techniques offered by SageMaker Clarify.', 8, 'm_8_1', 4, NULL, NULL),
  ('mock_5_all_1774921043968', 'A public sector organization is building an AI system to process citizen applications for benefits. This system will handle personally identifiable information (PII). The organization must ensure strict data privacy and compliance with data protection regulations throughout the AI lifecycle with minimal manual effort.', '["Leverage Amazon Macie to discover and protect sensitive data in data stores used by the AI system.","Implement Amazon Bedrock Guardrails to prevent the AI model from outputting PII.","Use Amazon SageMaker Clarify to ensure the model''s predictions are not biased against certain groups.","Configure AWS Audit Manager to generate reports on the AI system''s operational efficiency."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most appropriate service. Amazon Macie is a data security and data privacy service that uses machine learning and pattern matching to discover, classify, and protect sensitive data (like PII) in Amazon S3 and other data stores. This directly addresses the requirement for strict data privacy and compliance with minimal manual effort. Option B (incorrect) is for generative AI models on Amazon Bedrock to enforce content policies and is not designed for discovering and protecting PII in data stores. Option C (incorrect) focuses on bias detection and model explainability, not PII discovery and protection. Option D (incorrect) is for auditing compliance and governance, not for direct PII protection.', 8, 'm_8_1', 5, NULL, NULL),
  ('mock_5_all_1774921043968', 'A media company uses an AI model for content categorization. To prevent misclassifications of sensitive content, they need a process where human experts can review and correct the model''s predictions, especially for edge cases. This strategy ensures human oversight for critical AI decisions.', '["Train the AI model with an extremely large dataset to eliminate all classification errors.","Integrate a human-in-the-loop workflow where ambiguous or high-confidence predictions are routed for expert review.","Utilize Amazon Bedrock Guardrails to automatically re-categorize any content flagged as sensitive.","Deploy the model without human intervention, trusting its inherent accuracy for all content."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) describes a human-in-the-loop workflow, which is a key pattern for ensuring human oversight and accountability in AI systems, especially for sensitive or critical decisions. This directly addresses the need for human review and correction, preventing the anti-pattern [ap-4.1-002]. Option A (incorrect) is unrealistic; even large datasets do not guarantee 100% accuracy, and human judgment is still crucial for nuanced or sensitive content. Option C (incorrect) is for generative AI models to enforce content policies, not for re-categorizing content based on human review for traditional ML models. Option D (incorrect) represents anti-pattern [ap-4.1-002] by deploying AI in high-stakes decisions without human oversight, which can lead to significant harm.', 8, 'm_8_1', 6, NULL, NULL),
  ('mock_5_all_1774921043968', 'A startup developed an AI model for hiring without considering fairness during the initial design phase. Now, they face accusations of bias in their hiring recommendations. They need to analyze and address potential biases in the model''s decision-making process to comply with regulations and restore trust.', '["Retrain the model with a new, larger dataset from the same source without further analysis.","Ignore the bias concerns and focus on improving the model''s predictive accuracy.","Use Amazon SageMaker Clarify to detect and quantify bias in the model and its training data.","Implement Amazon Macie to scan for PII in the model''s output, which will resolve the bias."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the appropriate action. Amazon SageMaker Clarify is designed to help detect, quantify, and mitigate bias in ML models and their training data, and to provide explainability for model predictions. This directly addresses the need to analyze and understand the existing bias, which is crucial when responsible AI was treated as an afterthought (anti-pattern [ap-4.1-001]). Option A (incorrect) is unlikely to resolve bias if the underlying data source or methodology is still flawed, and it doesn''t provide insights into the bias itself. Option B (incorrect) is a clear example of anti-pattern [ap-4.1-001], treating responsible AI as an afterthought, which can lead to significant reputational and regulatory issues. Option D (incorrect) is for PII detection and protection, which is a different aspect of responsible AI (privacy) and will not address algorithmic bias.', 8, 'm_8_1', 7, NULL, NULL),
  ('mock_5_all_1774921043968', 'A company is building an AI system to analyze customer feedback for sentiment. They want to ensure that the system''s outputs are robust and not easily manipulated by adversarial inputs or unexpected data variations, maintaining consistent performance under diverse conditions.', '["Fairness, ensuring equitable outcomes across different customer groups.","Privacy, protecting sensitive customer information from unauthorized access.","Transparency, making the model''s internal workings easily understandable to users.","Robustness, ensuring the model''s reliability and resilience against attacks or unexpected data."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) describes robustness, which is a key dimension of responsible AI focusing on the reliability, resilience, and security of an AI system against malicious attacks, data poisoning, or unexpected variations in input data. This ensures consistent and trustworthy performance. Option A (incorrect) refers to fairness, which is about equitable treatment and outcomes. Option B (incorrect) refers to privacy, which is about protecting sensitive data. Option C (incorrect) refers to transparency, which is about making the model''s operations and decisions understandable. While all are important, robustness specifically addresses the system''s resilience against manipulation and unexpected inputs.', 8, 'm_8_1', 8, NULL, NULL),
  ('mock_5_all_1774921043968', 'A government agency is developing an AI system to assist in resource allocation for public services. Due to the sensitive nature of these decisions, they need to establish clear policies and procedures for the development, deployment, and monitoring of the AI system to ensure accountability and ethical use.', '["Governance, focusing on establishing clear policies, procedures, and accountability for AI systems.","Explainability, ensuring the model''s decisions can be understood by stakeholders.","Bias mitigation, actively reducing unfairness in the model''s outputs.","Data privacy, protecting sensitive citizen information handled by the system."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) accurately describes governance, which is a crucial dimension of responsible AI. Governance involves establishing frameworks, policies, and processes to manage the AI lifecycle, ensuring accountability, ethical considerations, and compliance. This directly addresses the need for clear policies and procedures for development, deployment, and monitoring. Option B (incorrect) focuses on understanding model decisions. Option C (incorrect) addresses fairness. Option D (incorrect) is about protecting sensitive data. While all are important aspects of responsible AI, governance specifically encompasses the overarching management and accountability framework.', 8, 'm_8_1', 9, NULL, NULL),
  ('mock_5_all_1774921043968', 'A financial institution is required by regulators to demonstrate that their AI-powered credit scoring model adheres to strict compliance standards and internal governance policies. They need a way to continuously monitor and audit the model''s adherence to these rules and collect evidence automatically.', '["Use Amazon SageMaker Clarify to analyze the model for bias and explainability.","Leverage AWS Audit Manager to automate the collection of evidence for audit and compliance checks.","Implement Amazon Bedrock Guardrails to filter the model''s credit scoring outputs.","Deploy Amazon Macie to detect sensitive financial data in the model''s input features."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most suitable service for this requirement. AWS Audit Manager helps automate the collection of evidence from AWS services to simplify audit preparation and ongoing compliance checks. This directly supports the need to demonstrate adherence to compliance standards and governance policies. Option A (incorrect) is for detecting bias and explaining model predictions, which is a different aspect of responsible AI. Option C (incorrect) is for generative AI models to enforce content policies and is not applicable to traditional credit scoring models. Option D (incorrect) is for discovering and protecting sensitive data, which is related to privacy but not directly for auditing compliance against governance policies.', 8, 'm_8_1', 10, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_8_2
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_5_all_1774921043968', 'A bank uses a deep learning model to automate credit risk assessment. Due to new financial regulations, they are now required to provide clear explanations for any automated decision that denies a loan application. The current model is a black box, making its decisions difficult to interpret.', '["Replace the deep learning model with a simpler, transparent model like a decision tree.","Implement Amazon Bedrock Guardrails to generate explanations for the model''s decisions.","Utilize Amazon SageMaker Clarify to provide post-hoc explanations for the black-box model''s decisions.","Document the model''s training process thoroughly, assuming this satisfies explainability requirements."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the most practical and effective solution. Amazon SageMaker Clarify provides tools for model explainability, including post-hoc techniques like SHAP values and feature importance, which can generate explanations for black-box models without requiring a complete model overhaul. This addresses anti-pattern [ap-4.2-001] by providing explainability for regulated industries. Option A (incorrect) might be a long-term solution but involves significant re-development and potential loss of accuracy, which is not ideal for an existing, deployed model. Option B (incorrect) is designed for generative AI models to enforce content policies and is not suitable for explaining decisions of a traditional credit risk assessment model. Option D (incorrect) is insufficient; regulatory requirements often demand explanations for individual decisions, not just documentation of the training process.', 8, 'm_8_2', 11, NULL, NULL),
  ('mock_5_all_1774921043968', 'A company is developing an AI model to predict customer churn. They want to understand which specific features (e.g., subscription length, support interactions) contribute most to the model''s predictions for individual customers, to inform targeted retention strategies.', '["Monitor the model''s overall accuracy metrics to infer feature importance.","Apply post-hoc explainability techniques like SHAP values or feature importance to the model.","Retrain the model multiple times with different feature subsets to see performance changes.","Use Amazon Macie to identify sensitive customer data, which will reveal feature contributions."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) describes the direct approach to understanding feature contributions. Post-hoc explainability techniques such as SHAP (SHapley Additive exPlanations) values or feature importance calculations (often implemented via Amazon SageMaker Clarify) are specifically designed to quantify how much each input feature contributes to an individual prediction or the model''s overall behavior. Option A (incorrect) provides overall performance but no insight into individual feature contributions. Option C (incorrect) is an indirect and computationally expensive method to infer feature importance, not as precise as dedicated explainability techniques. Option D (incorrect) is for data privacy and PII detection, which is unrelated to understanding feature contributions to model predictions.', 8, 'm_8_2', 12, NULL, NULL),
  ('mock_5_all_1774921043968', 'A retail company uses an AI model to optimize pricing. Business analysts need to understand the reasoning behind the price recommendations to build trust and validate the model''s logic. They require a way to interpret the model''s behavior without deep ML expertise.', '["Utilize Amazon SageMaker Clarify to generate model explanations and bias reports.","Deploy Amazon Bedrock Guardrails to ensure the pricing model''s outputs are within acceptable ranges.","Conduct regular A/B tests with different pricing strategies to observe customer reactions.","Provide the business analysts with access to the raw training data for manual inspection."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most suitable solution. Amazon SageMaker Clarify provides model explainability features that can help non-technical stakeholders understand the reasoning behind a model''s predictions, such as feature importance for specific price recommendations. This builds trust and allows validation of the model''s logic. Option B (incorrect) is for generative AI models to enforce content policies and is not applicable to explaining traditional pricing optimization models. Option C (incorrect) is for evaluating business impact, not for interpreting the internal logic of an AI model. Option D (incorrect) would require significant ML expertise to derive insights from raw data and would not provide direct model explanations.', 8, 'm_8_2', 13, NULL, NULL),
  ('mock_5_all_1774921043968', 'An insurance company is using an AI model to automate claim processing. Regulators demand that the company be able to explain why a particular claim was approved or denied. The company initially chose a complex neural network model, which is inherently opaque.', '["Rebuild the entire model using a simpler, more transparent algorithm like linear regression.","Implement Amazon Macie to audit data access patterns for compliance with privacy regulations.","Leverage Amazon SageMaker Clarify to generate explanations for the neural network''s decisions.","Assume that the model''s high accuracy is sufficient to satisfy regulatory explainability requirements."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the most effective and practical solution. Amazon SageMaker Clarify provides tools for post-hoc explainability, allowing the generation of explanations for complex, black-box models like neural networks, which is crucial for meeting regulatory requirements without rebuilding the entire system. This directly addresses anti-pattern [ap-4.2-001]. Option A (incorrect) is a drastic and costly measure that may lead to reduced accuracy and is often unnecessary when explainability tools are available. Option B (incorrect) is for data privacy and PII detection, which is not directly related to explaining model decisions. Option D (incorrect) is a common misconception and represents anti-pattern [ap-4.2-001]; high accuracy does not equate to explainability, especially in regulated industries.', 8, 'm_8_2', 14, NULL, NULL),
  ('mock_5_all_1774921043968', 'A company is evaluating different machine learning models for a critical decision-making process. They need to choose a model that is inherently easy to understand and explain, even if it means sacrificing a small amount of predictive accuracy for greater transparency.', '["A deep neural network, due to its ability to learn complex patterns.","A random forest, as it often provides high accuracy across various datasets.","A decision tree, because its decision logic is directly interpretable by humans.","A support vector machine, known for its effectiveness in high-dimensional spaces."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the best choice for inherent transparency. Decision trees are considered ''white-box'' or transparent models because their decision logic can be easily visualized and understood by humans, making them inherently explainable. Option A (incorrect) refers to deep neural networks, which are typically ''black-box'' models and are difficult to interpret without specialized tools. Option B (incorrect) refers to random forests, which are ensemble methods and, while powerful, are less transparent than a single decision tree. Option D (incorrect) refers to support vector machines, which are also generally considered black-box models.', 8, 'm_8_2', 15, NULL, NULL),
  ('mock_5_all_1774921043968', 'A pharmaceutical company is developing an AI model to assist in drug discovery. Due to the critical nature of the domain, scientists need to verify the model''s reasoning and ensure its predictions align with known biological principles. They require a method to gain insights into the model''s internal workings and decision paths.', '["Focus solely on achieving the highest possible prediction accuracy for the model.","Implement a robust data pipeline to ensure data quality, which will inherently explain predictions.","Apply Explainable AI (XAI) techniques to interpret the model''s decision-making process.","Conduct extensive peer reviews of the model''s code, assuming this clarifies its reasoning."]'::jsonb, 'mcq', '{3}'::integer[], 'Option C (correct) is the most direct approach. Explainable AI (XAI) techniques are specifically designed to help interpret the internal workings and decision paths of complex models, allowing scientists to verify the model''s reasoning and align it with domain knowledge. This is crucial for building trust and ensuring safety in critical applications like drug discovery. Option A (incorrect) is insufficient; high accuracy alone does not provide insight into the model''s reasoning, which is critical for scientific validation. Option B (incorrect) ensures data quality but does not explain how the model uses that data to make predictions. Option D (incorrect) reviews the implementation but does not necessarily clarify the model''s emergent reasoning or decision process for specific predictions.', 8, 'm_8_2', 16, NULL, NULL),
  ('mock_5_all_1774921043968', 'A company has deployed a large language model (LLM) using Amazon Bedrock for generating marketing copy. They want to ensure that the generated content aligns with brand voice and avoids generating inappropriate or off-brand text. This requires controlling the output of the generative AI model.', '["Utilize Amazon Bedrock Guardrails to define and enforce content policies and safety guidelines.","Implement Amazon SageMaker Clarify to detect bias in the LLM''s training data.","Manually review all generated marketing copy before publication to ensure compliance.","Use AWS Audit Manager to track access to the LLM and ensure only authorized users generate content."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most effective solution. Amazon Bedrock Guardrails are specifically designed to help implement safeguards for generative AI applications, allowing users to define custom policies to filter harmful content, enforce brand guidelines, and control model behavior. Option B (incorrect) is for detecting bias and explaining predictions in traditional ML models and training data, not for controlling the real-time output of generative AI. Option C (incorrect) is a manual and unscalable approach for a production system. Option D (incorrect) focuses on access control and auditing, which is important for security, but does not directly control the content generated by the LLM.', 8, 'm_8_2', 17, NULL, NULL),
  ('mock_5_all_1774921043968', 'A data scientist has trained a complex deep learning model on Amazon SageMaker. Before deploying it to production, the data scientist needs to generate a comprehensive report detailing the model''s performance, fairness metrics, and explainability insights for internal review and regulatory compliance.', '["Manually compile a report by extracting metrics from various SageMaker logs and dashboards.","Use Amazon Bedrock Guardrails to generate a compliance report for the model.","Leverage Amazon SageMaker Clarify to analyze the model and generate a comprehensive report.","Deploy Amazon Macie to scan the model artifacts for sensitive information before reporting."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the most efficient and integrated solution. Amazon SageMaker Clarify can analyze a model for bias and explainability, and it provides capabilities to generate comprehensive reports that include fairness metrics, explainability insights, and performance evaluations, which are essential for internal review and regulatory compliance. Option A (incorrect) is a manual, time-consuming, and error-prone process, especially for complex reports. Option B (incorrect) is for generative AI models on Amazon Bedrock to enforce content policies and does not generate compliance reports for traditional ML models. Option D (incorrect) is for discovering and protecting sensitive data, not for generating model performance, fairness, and explainability reports.', 8, 'm_8_2', 18, NULL, NULL),
  ('mock_5_all_1774921043968', 'A company is using an AI model to automate hiring decisions. They are concerned about the model''s potential to perpetuate historical biases present in the training data, leading to unfair outcomes. They need to analyze the model''s behavior to identify and understand any inherent biases.', '["Focus on improving the model''s overall predictive accuracy to mask any underlying biases.","Implement Amazon Bedrock Guardrails to prevent the model from making biased hiring decisions.","Use AWS Audit Manager to ensure the model''s deployment adheres to internal security policies.","Utilize Amazon SageMaker Clarify to detect and quantify bias in the model and its training data."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is the most appropriate service. Amazon SageMaker Clarify is specifically designed to help detect and measure bias in machine learning models and their training data, and to provide explainability for model predictions. This directly addresses the need to identify and understand inherent biases in the hiring model. Option A (incorrect) is a harmful anti-pattern; improving accuracy does not eliminate bias and can even exacerbate it, leading to unfair outcomes. Option B (incorrect) is for generative AI models on Amazon Bedrock to enforce content policies, not for detecting bias in traditional ML hiring models. Option C (incorrect) is for auditing compliance and governance, which is important, but does not directly address the detection of algorithmic or data bias.', 8, 'm_8_2', 19, NULL, NULL);

