INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_5_all_1774921043968', 'A healthcare organization is deploying a new AI model on Amazon SageMaker for real-time inference to assist with patient diagnostics. Due to strict HIPAA compliance requirements, all inference traffic must remain private and never traverse the public internet. The solution must also minimize operational overhead for network configuration. Which approach best meets these requirements?', '["Deploy the Amazon SageMaker endpoint into a private Amazon VPC and configure client applications to access it via a VPC interface endpoint.","Configure the Amazon SageMaker endpoint to use a public internet endpoint, but apply strict AWS IAM policies to restrict access.","Deploy the Amazon SageMaker endpoint with a public endpoint and use AWS WAF to filter incoming traffic based on IP addresses.","Host the inference model on an Amazon EC2 instance within a private subnet and manage all networking and scaling manually."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) ensures that the Amazon SageMaker inference endpoint is only accessible within a private Amazon VPC, and client applications can securely connect using a VPC interface endpoint (AWS PrivateLink). This design keeps all traffic private, satisfying HIPAA compliance, and minimizes operational overhead as AWS manages the endpoint and PrivateLink. Option B (incorrect) uses a public internet endpoint, which directly violates the requirement for private traffic, even with strict IAM policies. This represents the anti-pattern [ap-5.1-001] by using public endpoints for compliance-sensitive environments. Option C (incorrect) also uses a public endpoint, which is not suitable for sensitive healthcare data, and AWS WAF primarily provides web application firewall capabilities, not private network access. Option D (incorrect) would meet the private network requirement but significantly increases operational overhead due to manual management of EC2 instances, scaling, and patching, which violates the ''minimize operational overhead'' constraint.', 9, 'm_9_1', 1, NULL, NULL),
  ('mock_5_all_1774921043968', 'A research institution trains sensitive AI models using proprietary datasets stored in Amazon S3. They need to ensure that both the training data at rest and the resulting model artifacts are encrypted with keys that they manage, and that access to these keys is strictly controlled. Which AWS services should be integrated to meet these security requirements with high assurance?', '["Use Amazon S3 default encryption with S3-managed keys (SSE-S3) for data at rest and rely on AWS IAM for access control.","Implement client-side encryption for all data before uploading to Amazon S3 and manage keys on-premises.","Configure Amazon S3 buckets to use server-side encryption with AWS Key Management Service (AWS KMS) customer managed keys (CMKs) and define granular access policies using AWS IAM.","Store all data in an Amazon RDS database with encryption at rest enabled and use database user roles for access control."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) directly addresses the requirements. Configuring Amazon S3 buckets with server-side encryption using AWS KMS Customer Managed Keys (CMKs) ensures that data at rest is encrypted with keys controlled by the organization. AWS IAM policies can then be used to define granular permissions for who can access the S3 data and who can use the associated KMS CMKs, providing strict access control over both the data and the encryption keys. Option A (incorrect) uses S3-managed keys (SSE-S3), which does not give the organization control over the encryption keys, failing the ''keys that they manage'' requirement. Option B (incorrect) would require significant operational overhead for client-side encryption and on-premises key management, which is generally more complex and less scalable than using AWS KMS. Option D (incorrect) involves storing data in an Amazon RDS database, which is not the primary storage for large-scale AI training datasets and model artifacts, and introduces unnecessary complexity for this use case.', 9, 'm_9_1', 2, NULL, NULL),
  ('mock_5_all_1774921043968', 'A media company is developing a public-facing generative AI application using Amazon Bedrock. To prevent users from manipulating the model to generate inappropriate content or bypass safety features, the company needs to implement robust controls against prompt injection and jailbreaking attempts. Which AWS service is specifically designed to mitigate these threats?', '["Amazon Bedrock Guardrails.","AWS IAM policies.","AWS WAF.","Amazon SageMaker Role Manager."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is specifically designed for this purpose. Amazon Bedrock Guardrails allow developers to implement safety policies and content filters for generative AI applications. They help detect and mitigate prompt injection, jailbreaking, and other attempts to misuse the model by defining denied topics, content filters, and custom word lists. Option B (incorrect) AWS IAM policies control access to AWS resources and services, but they do not directly mitigate prompt injection or jailbreaking attempts within the generative AI model''s interaction. Option C (incorrect) AWS WAF is a web application firewall that protects web applications from common web exploits, but it is not designed to understand and mitigate AI-specific prompt-based attacks. Option D (incorrect) Amazon SageMaker Role Manager helps manage IAM roles for SageMaker, which is related to access control for SageMaker resources, not prompt-level security for generative AI models.', 9, 'm_9_1', 3, NULL, NULL),
  ('mock_5_all_1774921043968', 'A manufacturing company has a proprietary quality control application running in its on-premises data center. This application needs to securely invoke a real-time inference endpoint hosted on Amazon SageMaker without exposing the endpoint to the public internet. The company requires a solution that provides private connectivity and is easy to manage. Which networking approach should be used?', '["Configure the Amazon SageMaker endpoint with a public internet endpoint and whitelist the on-premises IP addresses.","Deploy the Amazon SageMaker endpoint within a private Amazon VPC and establish an AWS Direct Connect connection to the VPC.","Deploy the Amazon SageMaker endpoint within a private Amazon VPC and use a VPC interface endpoint (AWS PrivateLink) to connect from the on-premises data center via AWS Direct Connect or a VPN connection.","Host the inference model on an Amazon EC2 instance in a public subnet and use a Network Access Control List (NACL) to restrict access."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) provides the most secure and manageable solution for private connectivity. Deploying the Amazon SageMaker endpoint within a private Amazon VPC ensures it''s not publicly accessible. Using a VPC interface endpoint (AWS PrivateLink) allows the on-premises application to connect to the SageMaker endpoint privately over AWS Direct Connect or a VPN connection, without traffic traversing the public internet. Option A (incorrect) exposes the endpoint to the public internet, which violates the security requirement, even with IP whitelisting. Option B (incorrect) establishes a Direct Connect to the VPC, but doesn''t explicitly mention using a VPC interface endpoint for SageMaker, which is the best practice for private access to managed services within a VPC. Simply connecting to the VPC doesn''t automatically make the SageMaker endpoint private if it''s not configured as such. Option D (incorrect) involves hosting on an EC2 instance in a public subnet, which exposes the model to the internet and increases operational overhead, failing the security and management requirements.', 9, 'm_9_1', 4, NULL, NULL),
  ('mock_5_all_1774921043968', 'A data science team uses Amazon SageMaker for developing and deploying machine learning models. The organization requires strict access control, ensuring that data scientists only have permissions to their own SageMaker notebooks and specific training jobs, while MLOps engineers have broader permissions for endpoint deployment and monitoring. Which AWS service is best suited to implement this granular access control?', '["AWS IAM with resource-level policies.","Amazon SageMaker Role Manager.","AWS Organizations for account-level separation.","Amazon Cognito for user authentication."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the fundamental service for granular access control in AWS. AWS IAM (Identity and Access Management) allows you to define roles and policies that grant specific permissions to users and resources. With resource-level policies, you can specify exactly which SageMaker notebooks, training jobs, or endpoints a user or role can access, fulfilling the requirement for granular control based on job function. Option B (incorrect) Amazon SageMaker Role Manager is a feature within SageMaker Studio that helps simplify IAM role creation and management for SageMaker users, but the underlying mechanism for granular access control is still AWS IAM. It''s a tool to manage IAM, not a replacement for it. Option C (incorrect) AWS Organizations is used for managing multiple AWS accounts, which is a broader organizational control and not designed for granular access control within a single account''s SageMaker resources. Option D (incorrect) Amazon Cognito provides user authentication and authorization for web and mobile applications, but it is not the primary service for defining granular resource-level permissions within AWS services like SageMaker.', 9, 'm_9_1', 5, NULL, NULL),
  ('mock_5_all_1774921043968', 'A financial institution is training a fraud detection model using sensitive customer transaction data on Amazon SageMaker. The data is stored in Amazon S3. The institution requires that all training data is encrypted at rest and in transit, and that the SageMaker training job environment itself is isolated and secure. Which approach provides the most comprehensive security for this scenario?', '["Use Amazon S3 default encryption (SSE-S3) for data at rest and ensure the SageMaker training job uses a public internet connection.","Configure Amazon S3 buckets with server-side encryption using AWS KMS, ensure SageMaker training jobs use a VPC-only mode, and enforce encryption in transit using TLS.","Encrypt the data client-side before uploading to Amazon S3 and run SageMaker training jobs in a default VPC without specific network configurations.","Store data in an Amazon DynamoDB table with encryption at rest and use AWS Lambda for data preprocessing before SageMaker training."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) provides the most comprehensive security. Configuring Amazon S3 with AWS KMS ensures data at rest is encrypted with customer-managed keys. Running SageMaker training jobs in a VPC-only mode isolates the training environment within a private network, preventing public internet access. Enforcing encryption in transit using TLS (which SageMaker does by default for internal communications and can be enforced for external connections) protects data during transfer. Option A (incorrect) uses S3-managed keys (SSE-S3), which doesn''t meet the ''customer-managed keys'' implicit requirement for high assurance, and using a public internet connection for the training job violates isolation best practices for sensitive data. Option C (incorrect) client-side encryption adds operational complexity, and running SageMaker in a default VPC without specific network configurations might not provide the required isolation or controlled access. Option D (incorrect) Amazon DynamoDB is not typically used for large-scale training data storage for SageMaker, and using AWS Lambda for preprocessing doesn''t address the core encryption and isolation requirements for the training job itself.', 9, 'm_9_1', 6, NULL, NULL),
  ('mock_5_all_1774921043968', 'A government agency is using Amazon SageMaker Studio for data scientists to develop AI models. To meet stringent security policies, all access to SageMaker Studio notebooks must originate from specific, approved IP ranges within the agency''s corporate network and must not be accessible from the public internet. Which AWS networking and security configuration should be implemented?', '["Configure Amazon SageMaker Studio to use a private Amazon VPC and restrict access using Amazon VPC security groups and network ACLs based on source IP ranges.","Enable public internet access for Amazon SageMaker Studio and use AWS IAM policies to restrict user access.","Deploy Amazon SageMaker Studio in a default Amazon VPC and rely on default AWS security settings.","Use AWS WAF to filter incoming traffic to Amazon SageMaker Studio based on IP addresses."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) provides the most secure and compliant solution. By configuring Amazon SageMaker Studio to use a private Amazon VPC, you ensure that network traffic to and from the notebooks remains within your private network. Amazon VPC security groups and network ACLs can then be used to precisely control inbound and outbound traffic, allowing access only from the specified corporate IP ranges and blocking all public internet access. Option B (incorrect) enabling public internet access violates the requirement for private access and exposes the notebooks to potential threats, even with IAM policies. Option C (incorrect) deploying in a default Amazon VPC without specific network configurations might not provide the necessary isolation or granular IP-based access control. Option D (incorrect) AWS WAF is a web application firewall that protects web applications from common web exploits, but it is not the primary service for controlling network access to SageMaker Studio notebooks based on private IP ranges within a VPC.', 9, 'm_9_1', 7, NULL, NULL),
  ('mock_5_all_1774921043968', 'An autonomous vehicle company uses Amazon SageMaker to train its perception models. To prevent data poisoning attacks, where malicious data could compromise model integrity, the company needs to ensure that the training datasets in Amazon S3 are protected from unauthorized or accidental modification. Which combination of AWS features provides the most effective protection against data tampering?', '["Rely solely on strong AWS IAM policies to restrict write access to the S3 buckets.","Implement Amazon S3 Versioning and enable S3 Object Lock in WORM (Write Once Read Many) mode on the training data buckets, combined with strict AWS IAM policies.","Use Amazon S3 default encryption (SSE-S3) and regularly audit S3 access logs.","Store training data on Amazon EBS volumes attached to EC2 instances and manage access through EC2 security groups."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) provides the most robust protection against data tampering for training datasets. Amazon S3 Versioning keeps multiple versions of an object, allowing recovery from accidental deletions or modifications. S3 Object Lock in WORM mode prevents objects from being overwritten or deleted for a fixed or indefinite period, making it highly effective against data poisoning by ensuring data immutability. Combined with strict AWS IAM policies to control who can access and configure these features, this approach offers strong protection. Option A (incorrect) relying solely on IAM policies is good for access control but doesn''t protect against accidental modifications by authorized users or sophisticated attacks that might bypass simple write restrictions. Option C (incorrect) S3 default encryption protects data confidentiality, not integrity against tampering. Auditing access logs helps detect issues but doesn''t prevent them. Option D (incorrect) storing data on Amazon EBS volumes attached to EC2 instances is not a scalable or cost-effective solution for large-scale training datasets and introduces more operational overhead for managing storage and access compared to Amazon S3.', 9, 'm_9_1', 8, NULL, NULL),
  ('mock_5_all_1774921043968', 'An internal business intelligence application running on Amazon EC2 instances in a private subnet needs to consume predictions from an Amazon SageMaker real-time inference endpoint. The organization''s security policy dictates that the SageMaker endpoint must not be publicly accessible and all communication must remain within the AWS private network. Which is the most secure and operationally efficient way to achieve this connectivity?', '["Configure the Amazon SageMaker endpoint to be VPC-only and access it via a VPC interface endpoint (AWS PrivateLink) from the EC2 instances.","Configure the Amazon SageMaker endpoint with a public internet endpoint and use AWS IAM policies to restrict access to specific EC2 instance roles.","Deploy the Amazon SageMaker endpoint in a public subnet and use Amazon VPC Security Groups to whitelist the EC2 instances'' private IP addresses.","Host the inference model directly on the EC2 instances and manage the API gateway and load balancing manually."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most secure and operationally efficient approach. By configuring the Amazon SageMaker endpoint as VPC-only, it becomes inaccessible from the public internet. Accessing it via a VPC interface endpoint (AWS PrivateLink) ensures that all traffic between the EC2 instances and the SageMaker endpoint remains entirely within the AWS private network, meeting the security policy. This approach also leverages AWS-managed services, minimizing operational overhead. Option B (incorrect) uses a public internet endpoint, which violates the requirement for private access, even with IAM policies. This represents the anti-pattern [ap-5.1-001]. Option C (incorrect) deploying in a public subnet still means the endpoint has a public IP, even if security groups are used, which does not fully meet the ''not publicly accessible'' requirement. Option D (incorrect) hosting the model directly on EC2 instances would increase operational overhead significantly, requiring manual management of scaling, patching, and endpoint exposure, which is less efficient than using Amazon SageMaker.', 9, 'm_9_1', 9, NULL, NULL),
  ('mock_5_all_1774921043968', 'A defense contractor is developing highly sensitive AI models using Amazon SageMaker. The resulting model artifacts, stored in Amazon S3, must be encrypted at rest using encryption keys that are fully managed and controlled by the contractor. This is a critical security and compliance requirement. Which AWS service combination should be used to achieve this?', '["Configure Amazon S3 buckets with default encryption using S3-managed keys (SSE-S3).","Implement client-side encryption for model artifacts before uploading them to Amazon S3.","Configure Amazon S3 buckets to use server-side encryption with AWS Key Management Service (AWS KMS) customer managed keys (CMKs).","Store model artifacts in an Amazon EBS volume attached to a dedicated Amazon EC2 instance."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) directly meets the requirement for customer-managed encryption keys. Configuring Amazon S3 buckets to use server-side encryption with AWS KMS Customer Managed Keys (CMKs) allows the defense contractor to create, own, and manage the encryption keys used to protect their model artifacts. This provides full control over the keys, which is a common requirement in highly regulated environments. Option A (incorrect) uses S3-managed keys (SSE-S3), where AWS manages the encryption keys, which does not meet the ''fully managed and controlled by the contractor'' requirement. Option B (incorrect) client-side encryption would require the contractor to develop and maintain their own encryption logic and key management system, significantly increasing operational overhead and complexity compared to using AWS KMS. Option D (incorrect) storing model artifacts on an Amazon EBS volume attached to an EC2 instance is not a scalable or cost-effective solution for storing and managing model artifacts, which are typically stored in object storage like Amazon S3.', 9, 'm_9_1', 10, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_9_2
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_5_all_1774921043968', 'A financial services company is developing an AI model for fraud detection. To comply with industry regulations, they need to ensure full auditability of all data access and model changes, as well as track the lineage of training data. The solution must provide a comprehensive record for compliance officers. Which combination of AWS services should be used?', '["Use Amazon S3 for data storage and AWS Lambda for logging model changes.","Utilize AWS CloudTrail for API activity logging, AWS Config for resource configuration changes, and Amazon SageMaker Model Cards for model documentation.","Implement AWS KMS for encryption and Amazon DynamoDB for storing audit logs.","Employ Amazon GuardDuty for threat detection and Amazon Macie for data discovery."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) provides a robust solution for auditability and data governance. AWS CloudTrail logs all API calls to AWS services, including data access and model operations, providing an audit trail. AWS Config continuously monitors and records configuration changes to AWS resources, ensuring compliance with defined rules. Amazon SageMaker Model Cards allow for comprehensive documentation of model details, including data lineage, training parameters, and evaluation metrics, which is crucial for governance and compliance in regulated industries. Option A (incorrect) uses AWS Lambda for logging, which would require custom development and maintenance, increasing operational overhead compared to managed services. Option C (incorrect) focuses on encryption (KMS) and a NoSQL database (DynamoDB) for logs, but doesn''t inherently provide the comprehensive audit and configuration tracking capabilities of CloudTrail and Config, nor the structured model documentation of Model Cards. Option D (incorrect) focuses on threat detection (GuardDuty) and sensitive data discovery (Macie), which are important security services but do not directly address the requirements for API activity logging, configuration change tracking, or model documentation for compliance.', 9, 'm_9_2', 11, NULL, NULL),
  ('mock_5_all_1774921043968', 'An internal HR department at a large enterprise is using an AI-powered tool for resume screening. The company''s internal governance framework mandates that all AI systems, regardless of whether they are customer-facing or internal, must have clear documentation regarding their purpose, data sources, and potential biases. Which AWS service can help the HR team meet this documentation requirement?', '["AWS CloudTrail to log all API calls to the AI service.","AWS Config to monitor the configuration of the underlying infrastructure.","Amazon SageMaker Model Cards to document the model''s details, including its intended use, training data, and fairness metrics.","Amazon Bedrock Guardrails to filter harmful content from model outputs."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the most appropriate service. Amazon SageMaker Model Cards provide a standardized way to document essential information about an AI model, such as its purpose, training data, evaluation metrics, fairness considerations, and potential biases. This directly addresses the requirement for clear documentation and transparency, even for internal tools, aligning with governance best practices. Option A (incorrect) AWS CloudTrail logs API calls, which is crucial for auditing and security, but it does not provide the structured documentation required for model governance. Option B (incorrect) AWS Config monitors resource configurations for compliance, but it doesn''t document the AI model''s intrinsic details like its purpose or biases. Option D (incorrect) Amazon Bedrock Guardrails are designed to filter harmful content and enforce responsible AI policies for generative AI models, which is a different aspect of governance and doesn''t fulfill the documentation requirement for the model itself.', 9, 'm_9_2', 12, NULL, NULL),
  ('mock_5_all_1774921043968', 'A pharmaceutical company is using various AWS AI/ML services, including Amazon SageMaker and Amazon Comprehend, to analyze research data. To meet strict regulatory compliance requirements, the company must maintain a detailed, immutable record of all API calls made to these services for auditing purposes. Which AWS service should be enabled to achieve this with minimal effort?', '["AWS Config to record resource configuration changes.","AWS CloudTrail to log all API activity for auditing and governance.","Amazon CloudWatch Logs to collect application logs from AI/ML services.","AWS Audit Manager to automate evidence collection for compliance assessments."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the primary service for logging API activity. AWS CloudTrail records all API calls made to AWS services, including AI/ML services like Amazon SageMaker and Amazon Comprehend. These logs provide a detailed, immutable history of actions taken, which is essential for security analysis, change tracking, and regulatory compliance. Option A (incorrect) AWS Config records configuration changes to AWS resources, which is important for compliance, but it does not log API calls made to services. Option C (incorrect) Amazon CloudWatch Logs collects various types of logs, including application logs, but it does not automatically capture all AWS API calls across services like CloudTrail does. Option D (incorrect) AWS Audit Manager helps automate evidence collection for compliance assessments, but it relies on services like CloudTrail and Config to gather the raw data; it doesn''t generate the API activity logs itself.', 9, 'm_9_2', 13, NULL, NULL),
  ('mock_5_all_1774921043968', 'A global e-commerce company is developing an AI-powered recommendation engine. To comply with various international data protection regulations and internal risk management policies, the company needs to establish clear documentation and governance for its AI models, including risk assessments, data sources, and impact analyses. Which AWS service is best suited to help manage and document this model risk?', '["AWS CloudTrail to log all API calls related to the model.","AWS Config to track changes to the underlying infrastructure.","Amazon Bedrock Guardrails to ensure responsible AI outputs.","Amazon SageMaker Model Cards to provide structured documentation for model governance and risk management."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is specifically designed for model governance and risk management. Amazon SageMaker Model Cards provide a structured framework to document critical aspects of an AI model, such as its purpose, training data, evaluation metrics, fairness, potential biases, and risk assessments. This comprehensive documentation is essential for compliance, transparency, and effective model risk management, especially in regulated environments. Option A (incorrect) AWS CloudTrail logs API calls, which is important for auditing, but it does not provide the structured documentation for model risk management. Option B (incorrect) AWS Config monitors infrastructure configuration changes, which is relevant for overall compliance but not for documenting the intrinsic details and risks of an AI model itself. Option C (incorrect) Amazon Bedrock Guardrails focus on filtering harmful content and enforcing responsible AI policies for generative models, which is a different aspect of AI governance than comprehensive model documentation and risk assessment.', 9, 'm_9_2', 14, NULL, NULL),
  ('mock_5_all_1774921043968', 'A compliance officer at a highly regulated company needs to continuously monitor AWS resources used for AI/ML workloads to ensure they adhere to internal security policies and external regulations. The officer requires automated assessments and reporting on configuration compliance for services like Amazon S3 buckets, AWS KMS keys, and Amazon SageMaker endpoints. Which AWS service combination best addresses this requirement?', '["AWS CloudTrail for API logging and Amazon CloudWatch for metrics.","AWS Config for continuous monitoring of resource configurations and AWS Audit Manager for automated evidence collection and reporting.","Amazon GuardDuty for threat detection and Amazon Macie for sensitive data discovery.","AWS IAM for access control and AWS Organizations for multi-account management."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most effective combination for continuous compliance monitoring and reporting. AWS Config continuously monitors and records the configuration changes of AWS resources, evaluating them against predefined or custom rules to assess compliance. AWS Audit Manager then helps automate the collection of evidence from services like AWS Config, CloudTrail, and others, to prepare for audits and generate reports against various compliance frameworks. Option A (incorrect) AWS CloudTrail logs API calls, and Amazon CloudWatch collects metrics and logs, which are essential for security and operations, but they don''t provide automated configuration compliance assessment and reporting in the way AWS Config and Audit Manager do. Option C (incorrect) Amazon GuardDuty and Amazon Macie are security services focused on threat detection and sensitive data discovery, respectively, not continuous configuration compliance monitoring. Option D (incorrect) AWS IAM and AWS Organizations are for access control and account management, which are foundational for security but do not directly provide automated compliance assessment and reporting.', 9, 'm_9_2', 15, NULL, NULL),
  ('mock_5_all_1774921043968', 'A healthcare provider is using AI models for diagnostic support and must adhere to strict compliance frameworks like HIPAA. The organization needs to generate regular audit reports demonstrating that their AI workloads and associated AWS resources comply with these regulations. Which AWS service is specifically designed to simplify and automate the process of collecting evidence and generating compliance reports?', '["AWS CloudTrail for logging API activity.","AWS Config for continuous monitoring of resource configurations.","Amazon CloudWatch for monitoring operational health.","AWS Audit Manager for automating evidence collection and report generation for audits."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is the service specifically designed for this purpose. AWS Audit Manager helps automate the collection of evidence from various AWS services (like CloudTrail, Config, etc.) to prepare for audits. It maps this evidence to controls in a specified framework (e.g., HIPAA, GDPR), making it easier to generate comprehensive audit reports and demonstrate compliance. Option A (incorrect) AWS CloudTrail logs API activity, which is a source of evidence, but it doesn''t automate the collection, mapping, or reporting process for compliance frameworks. Option B (incorrect) AWS Config continuously monitors resource configurations for compliance against rules, providing another source of evidence, but it doesn''t generate full audit reports across multiple services and controls. Option C (incorrect) Amazon CloudWatch is for monitoring operational health and performance, not for compliance evidence collection and reporting.', 9, 'm_9_2', 16, NULL, NULL),
  ('mock_5_all_1774921043968', 'A security team in a highly regulated industry needs to track all changes made to AWS IAM policies that grant permissions to AI/ML services like Amazon SageMaker and Amazon Bedrock. This is crucial for maintaining an audit trail and ensuring compliance. Which AWS service should the team primarily use to monitor and record these specific policy modifications?', '["Amazon CloudWatch for monitoring logs and metrics.","AWS CloudTrail for logging API calls, including IAM policy modifications.","AWS Config for tracking resource configuration changes.","Amazon GuardDuty for continuous threat detection."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the primary service for this requirement. AWS CloudTrail records all API calls made to AWS services, including actions related to AWS IAM. When an IAM policy is created, updated, or deleted, CloudTrail logs these events, providing a detailed audit trail of who made the change, when, and from where. Option A (incorrect) Amazon CloudWatch is used for collecting and monitoring logs, metrics, and events, but it doesn''t automatically capture all AWS API calls like CloudTrail does. Option C (incorrect) AWS Config tracks configuration changes to AWS resources, which can include IAM policies as resources, but CloudTrail provides the specific API call details for modifications. While Config can show the ''before'' and ''after'' state, CloudTrail shows the ''who'' and ''when'' of the action. Option D (incorrect) Amazon GuardDuty is a threat detection service that monitors for malicious activity and unauthorized behavior, but it does not specifically log IAM policy changes for auditing purposes.', 9, 'm_9_2', 17, NULL, NULL),
  ('mock_5_all_1774921043968', 'A pharmaceutical company is developing AI models for drug discovery and needs to ensure rigorous governance. This includes tracking model versions, documenting validation results, and maintaining an auditable record of model approvals and deployments. The goal is to establish a clear lifecycle for each model. Which AWS service is best suited for managing this model lifecycle and documentation?', '["AWS CloudTrail for API call logging.","AWS Config for resource configuration monitoring.","Amazon Bedrock Guardrails for content moderation.","Amazon SageMaker Model Cards and the Amazon SageMaker Model Registry for structured documentation and versioning."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is the most comprehensive solution for managing the model lifecycle and documentation. Amazon SageMaker Model Cards provide structured documentation for model details, including validation results, fairness metrics, and intended use. The Amazon SageMaker Model Registry allows for versioning, approval workflows, and centralized management of models throughout their lifecycle, making it ideal for tracking and governing models in a regulated industry. Option A (incorrect) AWS CloudTrail logs API calls, which is important for auditing, but it does not provide structured model documentation or lifecycle management. Option B (incorrect) AWS Config monitors resource configurations, which is relevant for infrastructure compliance but not for model-specific documentation and lifecycle. Option C (incorrect) Amazon Bedrock Guardrails are for content moderation and responsible AI output for generative models, which is a different aspect of governance.', 9, 'm_9_2', 18, NULL, NULL),
  ('mock_5_all_1774921043968', 'A social media analytics company trains AI models on vast amounts of user-generated content. To enhance user privacy and comply with data protection regulations, the company aims to implement data minimization practices for its training datasets stored in Amazon S3. This involves ensuring that only necessary data attributes are used and sensitive identifiers are removed or masked before model training. Which AWS service primarily helps enforce access control for this data minimization strategy?', '["AWS CloudTrail for auditing data access.","AWS IAM policies for Amazon S3 bucket access and object permissions.","Amazon Macie for discovering sensitive data.","Amazon Comprehend for identifying personally identifiable information (PII)."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is crucial for enforcing data minimization through access control. AWS IAM policies allow you to define granular permissions on Amazon S3 buckets and objects. By carefully crafting IAM policies, you can ensure that only authorized roles or users can access the raw, unminimized data, and that preprocessing jobs (which perform the minimization) have the necessary permissions to read raw data and write minimized data to separate, more restricted locations. This enforces the ''who'' and ''what'' of data access, supporting the data minimization strategy. Option A (incorrect) AWS CloudTrail logs API calls, which is essential for auditing and verifying compliance, but it doesn''t actively enforce data minimization. Option C (incorrect) Amazon Macie is excellent for discovering sensitive data within S3, which helps identify what needs to be minimized, but it doesn''t enforce the access control for the minimization process itself. Option D (incorrect) Amazon Comprehend can identify PII, which is a key step in data minimization, but it''s a processing service, not an access control enforcement mechanism.', 9, 'm_9_2', 19, NULL, NULL),
  ('mock_5_all_1774921043968', 'A government agency uses AI for public services and is subject to stringent audit requirements. They need to regularly produce comprehensive reports detailing the security and compliance posture of their AI infrastructure, including configurations of Amazon S3 buckets, AWS KMS keys, and Amazon SageMaker endpoints. The solution must automate evidence collection and simplify report generation. Which AWS service is best suited for this task?', '["AWS CloudTrail for logging API activity.","AWS Config for continuous monitoring of resource configurations.","Amazon CloudWatch for collecting metrics and logs.","AWS Audit Manager for automating evidence collection and generating audit-ready reports."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is specifically designed to automate evidence collection and simplify report generation for audits. AWS Audit Manager helps you continuously audit your AWS usage to simplify how you assess risk and compliance with regulations and industry standards. It collects evidence from various AWS services (like AWS Config, CloudTrail, etc.) and maps it to controls in a specified framework, allowing you to generate audit-ready reports. Option A (incorrect) AWS CloudTrail logs API calls, which is a source of evidence, but it doesn''t automate the collection, mapping, or reporting process for compliance frameworks. Option B (incorrect) AWS Config continuously monitors resource configurations for compliance against rules, providing another source of evidence, but it doesn''t generate full audit reports across multiple services and controls. Option C (incorrect) Amazon CloudWatch is for monitoring operational health and performance, not for compliance evidence collection and reporting.', 9, 'm_9_2', 20, NULL, NULL);

