INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_5_all_1774922262689', 'A marketing department wants to segment its customer base to tailor campaigns. They have a large dataset of customer demographics and purchase history, but no predefined customer groups or labels. They need to discover natural groupings within the data. Which machine learning paradigm and technique should they use?', '["Supervised learning, specifically regression.","Reinforcement learning, specifically Q-learning.","Unsupervised learning, specifically clustering.","Supervised learning, specifically classification."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) specifies unsupervised learning and clustering. Unsupervised learning is used when data does not have predefined labels, and the goal is to find hidden patterns or structures within the data. Clustering is a technique within unsupervised learning that groups similar data points together, which is ideal for customer segmentation without prior labels. Option A (incorrect) refers to supervised learning and regression, which are used for predicting continuous numerical values based on labeled data. Option B (incorrect) refers to reinforcement learning, which involves an agent learning through trial and error in an environment, not suitable for this data analysis task. Option D (incorrect) refers to supervised learning and classification, which are used for predicting discrete categories based on labeled data (anti-pattern: confusing supervised and unsupervised learning).', 5, 'm_5_1', 7, NULL, NULL),
  ('mock_5_all_1774922262689', 'A technology executive is explaining the company''s new "AI strategy" to investors. They need to clearly articulate the differences between Artificial Intelligence, Machine Learning, and Deep Learning to avoid confusion and demonstrate a nuanced understanding. Which statement accurately describes their relationship?', '["Artificial Intelligence, Machine Learning, and Deep Learning are interchangeable terms for the same technology.","AI is the broadest field, Machine Learning is a subset of AI, and Deep Learning is a subset of Machine Learning.","Deep Learning is the broadest field, followed by Machine Learning, with AI being a subset of Deep Learning.","Machine Learning is a subset of Deep Learning, and both are distinct from Artificial Intelligence."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) accurately describes the hierarchical relationship: Artificial Intelligence (AI) is the broadest concept, aiming to create machines that simulate human intelligence. Machine Learning (ML) is a subset of AI that enables systems to learn from data without explicit programming. Deep Learning is a further subset of ML that uses neural networks with many layers to learn complex patterns. Option A (incorrect) is a common misconception (anti-pattern: treating AI and machine learning as interchangeable terms) and incorrectly states that the terms are interchangeable. Option C (incorrect) reverses the correct hierarchy, placing Deep Learning as the broadest. Option D (incorrect) also misrepresents the relationship by stating ML is a subset of Deep Learning and incorrectly separating them from AI.', 5, 'm_5_1', 8, NULL, NULL),
  ('mock_5_all_1774922262689', 'A content creation company wants to automatically generate unique marketing slogans and short product descriptions based on a few input keywords. They are exploring advanced AI capabilities that can produce novel content rather than just classifying existing data. Which type of AI is best suited for this task?', '["Generative AI.","Discriminative AI.","Reinforcement learning.","Supervised learning."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) refers to Generative AI, which is designed to create new content, such as text, images, or code, by learning patterns from existing data. This aligns perfectly with the requirement to generate unique marketing slogans and product descriptions. Option B (incorrect) refers to Discriminative AI, which is used for tasks like classification or prediction (e.g., categorizing existing content), not for creating new content (anti-pattern: assuming generative AI and discriminative AI are the same). Option C (incorrect) refers to Reinforcement learning, which is about an agent learning to make decisions through trial and error in an environment, not content generation. Option D (incorrect) refers to Supervised learning, which is typically used for tasks like classification or regression based on labeled data, not for generating novel outputs.', 5, 'm_5_1', 9, NULL, NULL),
  ('mock_5_all_1774922262689', 'A team is building a supervised machine learning model to predict whether a loan applicant will default. They have historical data including applicant income, credit score, loan amount, and a column indicating if the previous loan was defaulted. In this context, what are the ''features'' and the ''label''?', '["The loan default status is a feature; applicant income, credit score, and loan amount are labels.","Applicant income, credit score, and loan amount are features; loan default status is the label.","All columns are considered features, and there is no specific label.","All columns are considered labels, and there are no specific features."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) correctly identifies the components. In supervised learning, features are the input variables (applicant income, credit score, loan amount) that the model uses to make predictions, while the label is the output variable (loan default status) that the model is trained to predict. Option A (incorrect) incorrectly swaps the definitions of features and labels. Option C (incorrect) is characteristic of unsupervised learning, where there are no predefined labels, but this scenario clearly describes a supervised task. Option D (incorrect) is fundamentally incorrect, as a model needs distinct inputs (features) to predict an output (label).', 5, 'm_5_1', 10, NULL, NULL),
  ('mock_5_all_1774922262689', 'A quality control department needs an automated system to inspect manufactured parts and categorize them as "defective" or "non-defective" based on images. They have a large dataset of labeled images for both categories. Which common machine learning use case does this scenario represent?', '["Regression.","Clustering.","Classification.","Recommendation."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) represents classification. Classification is an ML task where the model learns to assign input data (images of parts) to predefined categories or classes (defective or non-defective) based on labeled training data. Option A (incorrect) refers to regression, which is used for predicting continuous numerical values, not discrete categories. Option B (incorrect) refers to clustering, an unsupervised learning technique used to group similar data points without predefined labels. Option D (incorrect) refers to recommendation systems, which suggest items to users based on their preferences or behavior.', 5, 'm_5_1', 11, NULL, NULL),
  ('mock_5_all_1774922262689', 'A real estate agency wants to develop a model to estimate the selling price of houses based on various attributes like square footage, number of bedrooms, and location. They have a dataset of past house sales with their corresponding prices. Which common machine learning use case does this scenario represent?', '["Clustering.","Classification.","Regression.","Anomaly detection."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) represents regression. Regression is a machine learning task used to predict a continuous numerical value (the selling price of a house) based on input features (square footage, bedrooms, location). Option A (incorrect) refers to clustering, an unsupervised learning technique for grouping similar data points without predefined labels. Option B (incorrect) refers to classification, which is used for predicting discrete categories or classes. Option D (incorrect) refers to anomaly detection, which identifies unusual patterns or outliers in data.', 5, 'm_5_1', 12, NULL, NULL);

