INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_5_all_1774922262689', 'A legal firm receives thousands of scanned legal documents and contracts daily. They need to automatically extract specific information, such as client names, dates, and clause numbers, from these documents to streamline their workflow. Which AWS AI service is best suited for this task?', '["Amazon Textract.","Amazon Comprehend.","Amazon Rekognition.","Amazon Transcribe."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is Amazon Textract, which is a machine learning service that automatically extracts text, handwriting, and data from scanned documents. It can identify fields, tables, and other structured information, making it ideal for extracting specific data from legal documents. Option B (incorrect) is Amazon Comprehend, which is used for natural language processing (NLP) tasks like sentiment analysis, entity recognition, and key phrase extraction from raw text, but it does not extract data from scanned images or PDFs. Option C (incorrect) is Amazon Rekognition, which is a computer vision service for image and video analysis, such as object and scene detection, facial analysis, but not for extracting text or structured data from documents. Option D (incorrect) is Amazon Transcribe, which converts speech to text, not suitable for scanned documents.', 5, 'm_5_2', 13, NULL, NULL),
  ('mock_5_all_1774922262689', 'A large online retailer wants to reduce the load on its customer support agents by automating responses to common customer inquiries, such as "Where is my order?" or "What is your return policy?". They need an intelligent conversational interface. Which AWS AI service is designed for building conversational chatbots?', '["Amazon Polly.","Amazon Lex.","Amazon Translate.","Amazon Personalize."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is Amazon Lex, a service for building conversational interfaces into any application using voice and text. It powers chatbots and virtual assistants, making it ideal for automating responses to common customer inquiries. Option A (incorrect) is Amazon Polly, a text-to-speech service that turns text into lifelike speech, but it does not handle conversational logic. Option C (incorrect) is Amazon Translate, a neural machine translation service for translating text between languages. Option D (incorrect) is Amazon Personalize, a machine learning service for building recommendation systems, not conversational interfaces.', 5, 'm_5_2', 14, NULL, NULL),
  ('mock_5_all_1774922262689', 'A supply chain manager needs to accurately predict the demand for various products over the next six months to optimize inventory levels and prevent stockouts or overstocking. They have years of historical sales data. Which AWS AI service is specifically designed to address this business problem?', '["Amazon Rekognition.","Amazon Comprehend.","Amazon Forecast.","Amazon Personalize."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is Amazon Forecast, a fully managed service that uses machine learning to deliver highly accurate forecasts. It is specifically designed for time-series forecasting, making it perfect for predicting product demand based on historical sales data. Option A (incorrect) is Amazon Rekognition, a computer vision service for image and video analysis. Option B (incorrect) is Amazon Comprehend, an NLP service for text analysis. Option D (incorrect) is Amazon Personalize, a recommendation engine for delivering personalized product suggestions, not for general demand forecasting.', 5, 'm_5_2', 15, NULL, NULL),
  ('mock_5_all_1774922262689', 'A financial institution is developing an AI model to assess creditworthiness for loan applications. There is concern that the model might inadvertently discriminate against certain demographic groups due to biases present in the historical training data. What is a crucial responsible AI principle to address this concern?', '["Focus solely on achieving the highest possible model accuracy.","Evaluate the training data for representational bias and implement fairness metrics.","Deploy the model quickly to gather real-world performance data.","Use only publicly available datasets to avoid proprietary data bias."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) emphasizes evaluating training data for bias and implementing fairness metrics. This directly addresses the responsible AI principle of fairness, ensuring that the model does not produce discriminatory outcomes (anti-pattern: overlooking bias and fairness concerns when deploying AI models). Option A (incorrect) focusing solely on accuracy can exacerbate bias if the dataset itself is biased, as the model will learn and perpetuate those biases. Option C (incorrect) deploying a potentially biased model quickly without prior evaluation risks causing harm and violating ethical guidelines. Option D (incorrect) using only publicly available datasets does not guarantee freedom from bias, as public datasets can also contain historical or societal biases.', 5, 'm_5_2', 16, NULL, NULL),
  ('mock_5_all_1774922262689', 'A small business needs to implement a system that flags orders for review if the total order value exceeds $10,000. They are considering using a machine learning model for this task. Which approach is the MOST cost-effective and least complex for this specific requirement?', '["Implement a simple rule-based system using AWS Lambda and Amazon CloudWatch.","Train an Amazon SageMaker classification model to predict high-value orders.","Use Amazon Personalize to identify orders that might exceed the threshold.","Develop a deep learning model on an Amazon EC2 instance to detect anomalies."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) suggests implementing a simple rule-based system using AWS Lambda and Amazon CloudWatch. This is the most cost-effective and least complex solution because the requirement is a deterministic rule (''if order value > $10,000''). Machine learning adds unnecessary complexity, cost, and operational overhead when a simple rule can achieve the desired outcome reliably (anti-pattern: applying ML to problems solvable by simple rule-based logic). Option B (incorrect) training an Amazon SageMaker classification model is overkill for a simple threshold rule, introducing significant complexity and cost. Option C (incorrect) Amazon Personalize is for recommendation systems, not for applying simple business rules. Option D (incorrect) developing a deep learning model on an Amazon EC2 instance is highly complex, expensive, and completely unnecessary for this straightforward rule.', 5, 'm_5_2', 17, NULL, NULL),
  ('mock_5_all_1774922262689', 'A global e-commerce platform receives customer feedback and product reviews in over ten different languages. They need to quickly understand the sentiment and content of these reviews without hiring a large team of human translators. Which AWS AI service can efficiently translate text content from multiple languages?', '["Amazon Comprehend.","Amazon Translate.","Amazon Transcribe.","Amazon Polly."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is Amazon Translate, a neural machine translation service that delivers fast, high-quality, and affordable language translation. It is perfectly suited for translating customer feedback and product reviews from multiple languages into a common language for analysis. Option A (incorrect) is Amazon Comprehend, which is used for natural language processing tasks like sentiment analysis and entity recognition, but it does not perform translation itself. Option C (incorrect) is Amazon Transcribe, which converts speech to text, not text translation. Option D (incorrect) is Amazon Polly, a text-to-speech service that converts text into lifelike speech.', 5, 'm_5_2', 18, NULL, NULL);

-- Update mock test with question count
UPDATE public.mock_tests
SET total_questions = total_questions + 18
WHERE id = 'mock_5_all_1774922262689';

COMMIT;

