INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_5_all_1774922262689', 'A startup is building a new customer support chatbot that needs to answer questions based on its proprietary product documentation. The company wants to ensure the chatbot provides accurate, up-to-date information without requiring extensive model retraining for every documentation update. Which approach offers the MOST cost-effective and agile solution for grounding the chatbot''s responses?', '["Implement Retrieval-Augmented Generation (RAG) using Amazon Bedrock with a Knowledge Base and a vector database.","Continuously fine-tune a large language model (LLM) on the updated documentation using Amazon SageMaker.","Develop a custom LLM from scratch and pre-train it on the proprietary documentation using AWS Trainium instances.","Use a base foundation model directly from Amazon Bedrock and rely solely on prompt engineering to include documentation snippets."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) implements Retrieval-Augmented Generation (RAG) using Amazon Bedrock with a Knowledge Base. This approach allows the LLM to retrieve relevant information from proprietary documentation stored in a vector database (like Amazon OpenSearch Service or Amazon Aurora with pgvector) and then generate responses based on that retrieved context. This is highly cost-effective and agile as it avoids expensive and time-consuming model retraining for documentation updates, addressing the core requirement. Option B (incorrect) involves continuously fine-tuning an LLM. Fine-tuning is expensive and time-consuming, requiring curated training data and significant compute resources, which goes against the ''most cost-effective and agile'' constraint (anti-pattern ap-2.2-001). Option C (incorrect) suggests developing a custom LLM from scratch. This is an extremely resource-intensive and complex undertaking, far beyond the scope of a cost-effective and agile solution for grounding a chatbot. Option D (incorrect) proposes using a base foundation model directly and relying on prompt engineering with documentation snippets. While prompt engineering is valuable, relying solely on it for extensive documentation would quickly exceed context window limits, leading to incomplete or inaccurate responses (anti-pattern ap-2.1-003 and ap-2.2-002). It also doesn''t provide a structured way to manage and retrieve information effectively.', 6, 'm_6_3', 1, NULL, NULL),
  ('mock_5_all_1774922262689', 'A data science team needs to deploy a pre-trained large language model (LLM) for text summarization quickly, without managing underlying infrastructure. They require a solution that provides a managed endpoint and supports various popular foundation models. Which AWS service is BEST suited for this requirement?', '["Amazon SageMaker JumpStart.","Amazon EC2 instances with a custom Docker container running an LLM.","AWS Lambda functions invoking a self-hosted LLM on Amazon ECS.","Amazon OpenSearch Service with k-NN for semantic search."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is Amazon SageMaker JumpStart. It provides a hub for pre-trained models, including LLMs, and allows for one-click deployment of these models to SageMaker endpoints, abstracting away infrastructure management. This directly meets the requirement for quickly deploying a pre-trained LLM without managing infrastructure. Option B (incorrect) involves Amazon EC2 instances with custom Docker containers. This requires significant operational overhead for infrastructure management, scaling, and security, which contradicts the ''without managing underlying infrastructure'' requirement (anti-pattern ap-2.3-001). Option C (incorrect) suggests AWS Lambda functions invoking a self-hosted LLM on Amazon ECS. While Lambda and ECS can be serverless, integrating and managing a self-hosted LLM still involves considerable operational overhead for model deployment, scaling, and maintenance, again failing the ''without managing underlying infrastructure'' constraint (anti-pattern ap-2.3-001). Option D (incorrect) is Amazon OpenSearch Service with k-NN. While OpenSearch with k-NN is excellent for vector search and RAG knowledge bases, it is not a service for deploying and serving pre-trained LLMs for summarization directly.', 6, 'm_6_3', 2, NULL, NULL),
  ('mock_5_all_1774922262689', 'A software development team wants to leverage generative AI to assist with code generation and debugging. They need a service that can understand natural language queries and provide relevant code snippets, suggest improvements, and explain complex code sections. Which AWS service is specifically designed to meet these developer productivity needs?', '["Amazon Q Developer.","Amazon Bedrock.","Amazon SageMaker JumpStart.","AWS Inferentia."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is Amazon Q Developer. Amazon Q Developer is an AI-powered assistant specifically designed to help developers with tasks like code generation, debugging, explaining code, and answering technical questions. It integrates with IDEs and developer tools, directly addressing the team''s requirements. Option B (incorrect) is Amazon Bedrock. While Amazon Bedrock provides access to foundation models that can be used for code generation, it is a broader service for building generative AI applications and does not offer the specialized developer assistance features (like IDE integration for debugging and code explanations) that Amazon Q Developer provides out-of-the-box. Option C (incorrect) is Amazon SageMaker JumpStart. SageMaker JumpStart allows for deploying pre-trained models, including code generation models, but it''s a model deployment platform, not an interactive AI assistant for developer productivity. Option D (incorrect) is AWS Inferentia. AWS Inferentia is a machine learning inference accelerator designed to provide high-performance, cost-effective inference for deep learning models. It is infrastructure, not an application-level service for developer assistance.', 6, 'm_6_3', 3, NULL, NULL),
  ('mock_5_all_1774922262689', 'A company is planning to train a custom large language model (LLM) from scratch, requiring massive computational power for the training phase. They are looking for purpose-built hardware that can accelerate deep learning training workloads efficiently and cost-effectively on AWS. Which AWS technology should they consider?', '["AWS Trainium.","AWS Inferentia.","Amazon EC2 instances with NVIDIA GPUs.","Amazon SageMaker Studio."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is AWS Trainium. AWS Trainium is a machine learning accelerator specifically designed by AWS to provide high-performance, cost-effective training for deep learning models, including large language models. It is purpose-built for accelerating training workloads. Option B (incorrect) is AWS Inferentia. AWS Inferentia is also a machine learning accelerator, but it is optimized for deep learning *inference* workloads, not training. While inference is part of the LLM lifecycle, the question specifically asks about the training phase. Option C (incorrect) refers to Amazon EC2 instances with NVIDIA GPUs. While NVIDIA GPUs are widely used for deep learning training, AWS Trainium is a purpose-built, often more cost-effective and efficient alternative for large-scale training workloads on AWS, especially for LLMs. Option D (incorrect) is Amazon SageMaker Studio. Amazon SageMaker Studio is an integrated development environment (IDE) for machine learning, providing tools for data preparation, model building, training, and deployment. While it can orchestrate training jobs, it is a service, not the underlying hardware accelerator itself.', 6, 'm_6_3', 4, NULL, NULL),
  ('mock_5_all_1774922262689', 'A company wants to build a chatbot that can engage in open-ended conversations with customers, answer general knowledge questions, and assist with creative writing tasks. They need a managed service that offers access to a variety of pre-trained foundation models without the overhead of managing infrastructure. Which AWS service is the MOST suitable choice?', '["Amazon Bedrock.","Amazon SageMaker.","AWS Lambda.","Amazon EC2."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is Amazon Bedrock. Amazon Bedrock is a fully managed service that provides access to a choice of high-performing foundation models (FMs) from leading AI companies and Amazon, via a single API. It allows users to build and scale generative AI applications without managing any underlying infrastructure, directly meeting the requirement for a managed service with various FMs and no infrastructure overhead. Option B (incorrect) is Amazon SageMaker. While Amazon SageMaker is a comprehensive machine learning service, it is primarily for building, training, and deploying custom ML models. While SageMaker JumpStart offers pre-trained models, Bedrock is specifically designed for serverless access to a wider range of FMs for generative AI applications, requiring less ML expertise for basic usage. Option C (incorrect) is AWS Lambda. AWS Lambda is a serverless compute service that runs code in response to events. While it could be used to invoke an LLM, it doesn''t provide the LLM itself or the managed access to multiple FMs. It would still require integrating with an LLM service or self-hosting, which adds overhead. Option D (incorrect) is Amazon EC2. Amazon EC2 provides virtual servers, which would require significant effort to set up, manage, and scale the underlying infrastructure for hosting LLMs, directly contradicting the ''without the overhead of managing infrastructure'' requirement (anti-pattern ap-2.3-001).', 6, 'm_6_3', 5, NULL, NULL),
  ('mock_5_all_1774922262689', 'A small business wants to use generative AI to create unique product descriptions for its online catalog. They have limited machine learning expertise and want to avoid complex model training or infrastructure management. Which AWS service allows them to access pre-trained foundation models with the LEAST operational overhead?', '["Amazon Bedrock.","Amazon SageMaker Studio.","AWS DeepComposer.","Amazon EC2 with a custom LLM deployment."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is Amazon Bedrock. Amazon Bedrock is a fully managed service that provides access to a variety of foundation models (FMs) through an API, allowing users to build generative AI applications without managing any infrastructure. This directly addresses the need for accessing pre-trained models with the least operational overhead and limited ML expertise. Option B (incorrect) is Amazon SageMaker Studio. While SageMaker Studio is an integrated development environment for ML, it is more comprehensive and requires more ML expertise for model building, training, and deployment than simply using a managed FM API. It introduces more operational overhead than Bedrock for this specific use case. Option C (incorrect) is AWS DeepComposer. AWS DeepComposer is a developer tool for creating music using generative AI and is not suitable for generating product descriptions. Option D (incorrect) is Amazon EC2 with a custom LLM deployment. Self-hosting and managing LLMs on Amazon EC2 requires significant compute, security, and operational overhead, which directly contradicts the ''least operational overhead'' requirement and the limited ML expertise of the small business (anti-pattern ap-2.3-001).', 6, 'm_6_3', 6, NULL, NULL);

