INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_5_all_1774922262689', 'A media company wants to generate short promotional video clips from text descriptions. They need to leverage generative AI models that can produce new visual content based on textual input. Which generative AI modality is MOST relevant for this use case?', '["Video generation.","Text generation.","Audio generation.","Code generation."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is Video generation. The scenario explicitly states the need to generate ''promotional video clips from text descriptions,'' which directly aligns with the capabilities of generative AI models in the video modality. These models can synthesize new video content based on various inputs, including text. Option B (incorrect) is Text generation. While text generation is a core capability of many generative AI models (like LLMs), it focuses on producing textual output, not visual content like video clips. Option C (incorrect) is Audio generation. Audio generation models create new audio content (e.g., music, speech) from inputs, but they do not produce video. Option D (incorrect) is Code generation. Code generation models produce programming code based on natural language descriptions or other code, which is unrelated to generating video clips.', 6, 'm_6_1', 7, NULL, NULL),
  ('mock_5_all_1774922262689', 'A marketing team is using a large language model (LLM) to brainstorm creative slogans for a new product. They want the LLM to produce a wide range of diverse and imaginative suggestions, even if some are unconventional. Which inference parameter should they adjust to encourage more varied and less deterministic outputs?', '["Temperature.","Max tokens.","Top-P.","Top-K."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is Temperature. The ''temperature'' parameter controls the randomness and creativity of the LLM''s output. A higher temperature (e.g., 0.7-1.0) leads to more diverse, creative, and less deterministic responses, which is ideal for brainstorming and generating imaginative suggestions. A lower temperature (e.g., 0.0-0.2) makes the output more focused and deterministic, suitable for factual Q&A or code generation. Option B (incorrect) is Max tokens. ''Max tokens'' sets the maximum length of the generated response. While important for controlling output size, it does not directly influence the creativity or diversity of the content itself. Option C (incorrect) is Top-P. ''Top-P'' (or nucleus sampling) controls the diversity by selecting from the smallest set of tokens whose cumulative probability exceeds a certain threshold ''P''. While it influences diversity, ''temperature'' is the primary and most direct parameter for controlling the overall randomness and creativity. Option D (incorrect) is Top-K. ''Top-K'' limits the model''s token selection to the ''K'' most probable tokens at each step. Similar to Top-P, it influences diversity, but ''temperature'' is the more fundamental parameter for adjusting the overall creative output (anti-pattern ap-2.1-001).', 6, 'm_6_1', 8, NULL, NULL),
  ('mock_5_all_1774922262689', 'A legal firm is using an LLM to summarize lengthy legal documents. The documents often exceed 10,000 words, and the LLM''s context window is limited to 4,000 tokens. When processing these documents, the LLM frequently misses critical information from the latter parts of the text. What is the most likely reason for this issue?', '["The LLM''s context window limit is being exceeded, causing truncation of the input.","The LLM is hallucinating due to insufficient training data on legal terminology.","The temperature parameter is set too high, making the summary overly creative and inaccurate.","The tokenization process is inefficient, leading to an incorrect token count."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) states that the LLM''s context window limit is being exceeded. LLMs have a finite context window, which defines the maximum number of tokens they can process in a single input. If the input document (10,000 words, which translates to significantly more tokens) exceeds the 4,000-token limit, the latter parts of the document will be truncated or ignored, leading to missed information. This is a common limitation of LLMs (anti-pattern ap-2.1-003). Option B (incorrect) suggests the LLM is hallucinating. While hallucinations are a known LLM limitation, missing specific information from the latter part of a long document is more indicative of a context window issue rather than a hallucination, which typically involves generating plausible but incorrect information. Option C (incorrect) claims the temperature parameter is too high. A high temperature would make the output more creative, but it wouldn''t cause specific sections of the input to be ignored due to length. Option D (incorrect) mentions inefficient tokenization. While tokenization efficiency can vary, it wouldn''t inherently cause an LLM to miss the latter parts of a document unless the token count was miscalculated and led to an unexpected context window overflow, which is a less direct cause than simply exceeding the known limit.', 6, 'm_6_1', 9, NULL, NULL),
  ('mock_5_all_1774922262689', 'A content creation agency wants to use generative AI to produce diverse marketing copy variations for social media campaigns. They need the model to generate multiple unique options for a given prompt, exploring different styles and tones. Which prompt engineering technique is most suitable for this goal?', '["Few-shot prompting.","Zero-shot prompting.","Chain-of-thought prompting.","Deterministic prompting with temperature 0."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is Few-shot prompting. Few-shot prompting involves providing the model with a few examples of input-output pairs to guide its generation. For generating diverse marketing copy, providing examples of different styles or tones can help the model understand the desired variations and produce more creative and varied outputs tailored to the specific campaign needs. Option B (incorrect) is Zero-shot prompting. Zero-shot prompting involves giving the model a prompt without any examples. While it can generate content, it might not consistently produce the desired diversity or specific stylistic variations without guidance. Option C (incorrect) is Chain-of-thought prompting. Chain-of-thought prompting is used to encourage the model to show its reasoning steps, which is beneficial for complex problem-solving or multi-step tasks, but not directly for generating diverse creative variations. Option D (incorrect) is Deterministic prompting with temperature 0. Setting temperature to 0 produces highly focused and deterministic output, which is the opposite of what is needed for generating diverse and imaginative marketing copy (anti-pattern ap-2.1-001).', 6, 'm_6_1', 10, NULL, NULL),
  ('mock_5_all_1774922262689', 'A research team is analyzing historical news articles and needs to identify the main topics and sentiment expressed in each article. They plan to use a generative AI model for summarization and sentiment analysis. Which generative AI modality is primarily involved in processing and understanding these textual inputs?', '["Text generation.","Image generation.","Audio generation.","Video generation."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is Text generation. The scenario describes processing ''historical news articles'' for ''summarization and sentiment analysis,'' which are tasks performed on textual data. Generative AI models that handle text generation (and understanding) are primarily involved in these tasks. While the output might be a summary (new text), the core modality for processing the input is text. Option B (incorrect) is Image generation. Image generation models create visual content and are not used for analyzing or summarizing text. Option C (incorrect) is Audio generation. Audio generation models create sound and are not relevant for processing text documents. Option D (incorrect) is Video generation. Video generation models create moving visual content and are not used for text analysis.', 6, 'm_6_1', 11, NULL, NULL),
  ('mock_5_all_1774922262689', 'An e-commerce company wants to implement a product recommendation system that generates personalized descriptions for customers based on their browsing history and preferences. The system needs to create novel, engaging text. Which type of generative AI model is best suited for this task?', '["Large Language Model (LLM).","Discriminative model.","Traditional rule-based system.","Simple classification model."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is a Large Language Model (LLM). LLMs are a type of foundation model specifically designed for understanding and generating human-like text. They excel at tasks like content generation, summarization, and personalized descriptions, making them ideal for creating novel and engaging product descriptions based on customer data. Option B (incorrect) is a Discriminative model. Discriminative models are used for tasks like classification or regression, where they learn to distinguish between different categories or predict values. They are not designed to generate new content. Option C (incorrect) is a Traditional rule-based system. While rule-based systems can provide recommendations, they lack the creativity and adaptability to generate novel, personalized, and engaging descriptions dynamically. They are limited by predefined rules. Option D (incorrect) is a Simple classification model. Classification models categorize inputs into predefined classes (e.g., ''like'' or ''dislike''). They cannot generate new text content.', 6, 'm_6_1', 12, NULL, NULL);

