INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_5_all_1774922262689', 'A healthcare provider is exploring generative AI for patient-facing applications, such as answering common medical questions. Given the high-stakes nature of medical information, what is a critical limitation of generative AI that the provider MUST address to ensure patient safety and accuracy?', '["Hallucinations, requiring validation of LLM outputs for factual accuracy.","The model''s knowledge cutoff, which prevents it from accessing real-time medical updates.","High operational cost, making it impractical for widespread use.","Limited context window, restricting the length of patient queries."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) highlights Hallucinations. Hallucinations are a critical limitation of LLMs where they generate plausible-sounding but incorrect or fabricated information. In a high-stakes domain like healthcare, trusting LLM outputs without validation for factual accuracy is an anti-pattern (ap-2.1-002) and could lead to severe consequences for patient safety. Therefore, validation is mandatory. Option B (incorrect) mentions the model''s knowledge cutoff. While a knowledge cutoff is a limitation, it primarily means the model won''t have information beyond its training data. This can be mitigated with RAG. Hallucinations, however, are about the model generating incorrect information even within its knowledge domain, which is a more direct and severe risk for factual accuracy in medical applications. Option C (incorrect) refers to high operational cost. While cost is a factor, it is a business constraint rather than a direct limitation on the factual accuracy and safety of the information provided, which is paramount in healthcare. Option D (incorrect) points to a limited context window. A limited context window restricts the length of input the model can process, but it doesn''t directly cause the model to generate factually incorrect information in the way hallucinations do.', 6, 'm_6_2', 13, NULL, NULL),
  ('mock_5_all_1774922262689', 'A large enterprise wants to deploy an internal chatbot for employees to ask questions about company policies and benefits. The company has a vast amount of proprietary, constantly updated internal documentation. Which approach is MOST effective for grounding the chatbot''s responses in this specific, up-to-date company knowledge?', '["Implementing Retrieval-Augmented Generation (RAG) to query a knowledge base of company documents.","Fine-tuning a foundation model with all company documentation every time it''s updated.","Using a base foundation model directly and relying on its pre-trained knowledge.","Manually curating responses for every possible employee question."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is implementing Retrieval-Augmented Generation (RAG). RAG allows the chatbot to retrieve relevant information from a dedicated knowledge base (containing proprietary company documents) and use that information to ground its responses. This ensures accuracy, keeps the information up-to-date without retraining the model, and addresses the ''company-specific knowledge'' requirement effectively. Option B (incorrect) suggests fine-tuning a foundation model with all company documentation every time it''s updated. Fine-tuning is expensive, time-consuming, and requires significant data and compute resources. For frequently updated documentation, this approach is not cost-effective or agile (anti-pattern ap-2.2-001). Option C (incorrect) proposes using a base foundation model directly. Base models have a knowledge cutoff and no access to proprietary company data. Without grounding, responses would be generic, potentially incorrect, and lack internal context (anti-pattern ap-2.2-002). Option D (incorrect) involves manually curating responses. This is not scalable, highly inefficient, and defeats the purpose of using generative AI for dynamic question-answering.', 6, 'm_6_2', 14, NULL, NULL),
  ('mock_5_all_1774922262689', 'A marketing department wants to generate personalized email campaigns for different customer segments. They need to create unique and engaging content for each segment based on specific product features and customer demographics. Which generative AI use case is this scenario an example of?', '["Content generation.","Summarization.","Sentiment analysis.","Code generation."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is Content generation. The scenario describes creating ''unique and engaging content'' for ''personalized email campaigns,'' which is a direct application of generative AI for content generation. This involves producing new, original text tailored to specific inputs and requirements. Option B (incorrect) is Summarization. Summarization involves condensing existing text into a shorter form, not generating new, creative content for marketing campaigns. Option C (incorrect) is Sentiment analysis. Sentiment analysis determines the emotional tone of existing text (e.g., positive, negative, neutral) and does not involve generating new content. Option D (incorrect) is Code generation. Code generation involves producing programming code, which is unrelated to creating marketing email content.', 6, 'm_6_2', 15, NULL, NULL),
  ('mock_5_all_1774922262689', 'A manufacturing company wants to automate its quality control process by analyzing images of products on an assembly line to detect defects. They are considering using generative AI to identify anomalies. What is a key limitation of generative AI models that might make them challenging for this specific, highly precise defect detection task?', '["Lack of interpretability, making it difficult to understand why a specific defect was identified.","High cost of inference, making real-time detection economically unfeasible.","Limited context window, preventing analysis of large image datasets.","Inability to process visual data, requiring conversion to text."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is Lack of interpretability. Generative AI models, especially complex ones used for anomaly detection in images, can be ''black boxes.'' It can be difficult to understand the exact features or reasons why the model identified a specific product as defective. In quality control, understanding the root cause of a defect is crucial for process improvement, making the lack of interpretability a significant limitation. Option B (incorrect) refers to high cost of inference. While inference costs are a consideration, purpose-built hardware like AWS Inferentia can make real-time inference cost-effective. This is a business constraint, not an inherent technical limitation of the model''s ability to perform the task. Option C (incorrect) mentions limited context window. The concept of a ''context window'' primarily applies to text-based models (LLMs) and their token limits, not directly to image processing models in the same way. Image models process visual data differently. Option D (incorrect) states an inability to process visual data. This is incorrect; generative AI includes modalities like image generation and analysis, so models are perfectly capable of processing visual data.', 6, 'm_6_2', 16, NULL, NULL),
  ('mock_5_all_1774922262689', 'A customer service department wants to use an AI agent to handle routine inquiries, such as resetting passwords or checking order statuses. The agent needs to interact with existing internal systems (e.g., CRM, order management). Which generative AI capability is essential for enabling the AI agent to perform these actions?', '["Agents and tool use.","Summarization.","Translation.","Sentiment analysis."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is Agents and tool use. For an AI agent to handle routine inquiries and interact with internal systems, it needs the capability to use ''tools'' (e.g., APIs, functions) to perform specific actions like resetting passwords or checking order statuses. This is the core concept behind agentic AI workflows, where the LLM acts as a controller to decide which tools to use and when. Option B (incorrect) is Summarization. Summarization involves condensing information, which might be part of an agent''s workflow (e.g., summarizing a customer interaction) but is not the capability that enables it to interact with external systems. Option C (incorrect) is Translation. Translation converts text from one language to another, which is not relevant to interacting with internal systems for task execution. Option D (incorrect) is Sentiment analysis. Sentiment analysis determines the emotional tone of text, which can be useful for understanding customer mood but does not enable the agent to perform actions within other systems.', 6, 'm_6_2', 17, NULL, NULL),
  ('mock_5_all_1774922262689', 'A content moderation team needs to quickly identify and filter out inappropriate content from user-generated text. They are considering a generative AI solution to classify text as ''appropriate'' or ''inappropriate'' and provide a brief explanation for the classification. What is a primary benefit of using generative AI for this task compared to traditional rule-based systems?', '["Adaptability and responsiveness to new forms of inappropriate content.","Deterministic and 100% accurate classification every time.","Lower operational cost due to zero human oversight.","Elimination of hallucinations in content classification."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is Adaptability and responsiveness to new forms of inappropriate content. Generative AI models, particularly LLMs, are highly adaptable. They can learn from vast amounts of data and generalize to new, unseen patterns of inappropriate content (e.g., new slang, nuanced expressions) much more effectively than rigid, traditional rule-based systems, which require constant manual updates for every new pattern. Option B (incorrect) states deterministic and 100% accurate classification. Generative AI models are not always deterministic and are prone to errors or inconsistencies, especially in nuanced tasks. Achieving 100% accuracy is unrealistic, and their outputs are often probabilistic. Option C (incorrect) claims lower operational cost due to zero human oversight. While generative AI can reduce manual effort, it typically requires human oversight for high-stakes tasks like content moderation to review edge cases, correct errors, and ensure ethical guidelines are met. It does not eliminate human involvement. Option D (incorrect) suggests the elimination of hallucinations. Generative AI models are known to hallucinate, meaning they can generate plausible but incorrect explanations or classifications. This is a limitation, not a benefit, in terms of accuracy for content moderation.', 6, 'm_6_2', 18, NULL, NULL);

