-- Module: m_7_4
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_5_all_1774922262689', 'A healthcare provider is developing an AI assistant using Amazon Bedrock to help doctors quickly access patient information. Due to the sensitive nature of medical data, the assistant must strictly avoid generating any harmful, biased, or off-topic content. Additionally, it needs to redact Protected Health Information (PHI) from outputs. Which Amazon Bedrock feature should be implemented to enforce these content policies and data privacy requirements?', '["Implement Amazon Bedrock Guardrails to define content policies, filter harmful outputs, and redact sensitive information like PHI.","Rely on the foundation model''s inherent safety mechanisms and fine-tune it with a dataset of safe medical conversations.","Develop a custom AWS Lambda function to scan and filter all model outputs for harmful content and PHI before display.","Use Amazon SageMaker Clarify to detect bias in the model''s training data, which will prevent harmful outputs during inference."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most appropriate solution. Amazon Bedrock Guardrails are specifically designed to enforce content policies, filter harmful or off-topic outputs, and perform PII (including PHI) redaction, ensuring safe and responsible use of foundation models in sensitive domains like healthcare. Option B (incorrect) is an anti-pattern (ap-3.4-001). Relying solely on a model''s inherent safety or fine-tuning is insufficient to guarantee content moderation and PII redaction, as models can still generate undesirable content. Option C (incorrect) developing a custom Lambda function for content filtering and redaction would involve significant development effort, maintenance, and is less robust than the specialized capabilities offered by Amazon Bedrock Guardrails. Option D (incorrect) Amazon SageMaker Clarify is used for detecting bias in training data and model explanations, which is important for responsible AI but does not directly provide real-time content filtering or PII redaction during inference.', 7, 'm_7_4', 13, NULL, NULL),
  ('mock_5_all_1774922262689', 'A content generation company uses an Amazon Bedrock foundation model to create marketing copy. They need to evaluate the quality of the generated text, focusing on creativity, tone, and factual accuracy. While automated metrics like ROUGE are considered, the team observes that these metrics don''t fully capture the subjective aspects of good marketing copy. Which evaluation method should be prioritized to comprehensively assess the generative model''s performance for this use case?', '["Solely rely on automated metrics such as ROUGE and BLEU scores to measure n-gram overlap with reference texts.","Implement a human evaluation process where expert marketers review and score the generated content for creativity, tone, and accuracy.","Increase the model''s output length and temperature parameters to generate more diverse content, then pick the best ones.","Conduct A/B testing with different foundation models, measuring only conversion rates without qualitative feedback."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most comprehensive approach. For generative tasks like marketing copy, subjective qualities like creativity, tone, and factual accuracy are best assessed through human evaluation. Automated metrics like ROUGE and BLEU (Option A, incorrect) are an anti-pattern (ap-3.1-002) because they primarily measure n-gram overlap and do not reliably capture semantic quality, coherence, or factual accuracy in generative outputs. Option C (incorrect) increasing output length and temperature might produce more diverse content but does not provide a systematic evaluation method for quality. Option D (incorrect) A/B testing conversion rates is valuable for business impact but doesn''t provide granular qualitative feedback on the generated content itself, which is crucial for understanding and improving the model''s creative and tonal aspects.', 7, 'm_7_4', 14, NULL, NULL),
  ('mock_5_all_1774922262689', 'A software company has developed a new feature powered by an Amazon Bedrock foundation model that generates code snippets. Before fully rolling out this feature to all users, the engineering team wants to compare its performance against the existing, manual code generation process in a controlled environment. They need to gather real-world feedback and metrics without impacting the entire user base. Which deployment and evaluation strategy is MOST suitable for this scenario?', '["Perform a full rollout of the new feature to all users immediately and monitor user feedback through support tickets.","Implement a shadow deployment where the new model processes requests in parallel with the existing system, but only the existing system''s output is returned to users.","Conduct extensive offline testing using a static dataset, and once satisfactory, deploy the model to all users.","Use Amazon Bedrock Model Evaluation to run a one-time benchmark against a predefined dataset, then deploy if scores are high."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) describes a shadow deployment, which is ideal for evaluating new models in a production environment without directly impacting users. It allows for gathering real-world performance metrics and identifying potential issues by comparing the model''s output against the existing system. Option A (incorrect) a full rollout without prior testing carries significant risk, especially for a new feature, and could negatively impact user experience. Option C (incorrect) while extensive offline testing is crucial, it may not fully capture real-world performance or edge cases, and it doesn''t provide a mechanism for controlled live comparison. Option D (incorrect) Amazon Bedrock Model Evaluation is useful for initial benchmarking and comparison but is typically a one-time assessment and does not provide continuous, real-time comparison in a live environment like a shadow deployment.', 7, 'm_7_4', 15, NULL, NULL),
  ('mock_5_all_1774922262689', 'A non-profit organization is building a public-facing chatbot to provide information about social services. They are concerned that the foundation model might inadvertently generate biased or discriminatory responses, particularly when discussing sensitive topics related to diverse communities. The organization needs a method to proactively identify and mitigate these potential issues before deployment. Which evaluation dimension should be a primary focus during the model''s development and testing phase?', '["Focus primarily on the model''s latency and throughput to ensure rapid response times for users.","Evaluate the model for potential bias and toxicity, specifically testing its responses across different demographic queries and sensitive topics.","Measure the model''s coherence and fluency by assessing how grammatically correct and natural-sounding its responses are.","Prioritize the model''s accuracy in retrieving factual information from its training data, regardless of the content''s sensitivity."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) directly addresses the organization''s concern about biased or discriminatory responses. Evaluating for bias and toxicity is crucial for public-facing applications, especially when dealing with sensitive topics and diverse communities, to ensure fair and equitable outputs. Option A (incorrect) while latency and throughput are important for user experience, they do not address the critical ethical concern of bias and toxicity. Option C (incorrect) coherence and fluency are important for readability, but they do not guarantee that the content itself is unbiased or non-discriminatory. Option D (incorrect) prioritizing factual accuracy alone is insufficient; a factually accurate statement can still be biased or toxic if presented in a discriminatory manner or context.', 7, 'm_7_4', 16, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_7_3
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_5_all_1774922262689', 'A manufacturing company wants to create an internal AI assistant for its engineers. The assistant needs to answer highly specific questions about proprietary machinery manuals and internal troubleshooting guides. These documents are frequently updated. The company wants to ensure the AI assistant provides accurate, up-to-date information without hallucinating, while minimizing the effort to keep the knowledge base current. Which strategy is MOST appropriate?', '["Implement a Retrieval Augmented Generation (RAG) pattern with Amazon Bedrock Knowledge Bases, connected to the document repository.","Fine-tune a foundation model on the entire set of proprietary manuals and guides using Amazon Bedrock''s fine-tuning capabilities.","Use advanced prompt engineering techniques with a general-purpose foundation model, providing relevant document snippets in the prompt.","Develop a custom search engine that allows engineers to query the documents directly, without involving a foundation model."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most appropriate strategy. A RAG pattern with Amazon Bedrock Knowledge Bases allows the foundation model to retrieve information directly from the proprietary documents, ensuring answers are grounded and up-to-date as the documents are updated. This minimizes hallucinations and the effort to keep the knowledge current without retraining the model. Option B (incorrect) fine-tuning a foundation model (ap-3.3-001) would require retraining the model every time the documents are updated, which is resource-intensive and not ideal for frequently changing information. Option C (incorrect) while prompt engineering can help, manually providing relevant document snippets in the prompt is not scalable or efficient for an AI assistant that needs to answer ''highly specific questions'' from a large, dynamic knowledge base. Option D (incorrect) a custom search engine would provide document links but not natural language answers or summaries, failing to meet the requirement of an ''AI assistant'' that leverages foundation models.', 7, 'm_7_3', 17, NULL, NULL),
  ('mock_5_all_1774922262689', 'A startup is fine-tuning a foundation model on Amazon Bedrock to generate product descriptions in a very specific brand voice. They have collected a small dataset of existing product descriptions, but the data quality is inconsistent, with some descriptions being too short, containing typos, or not fully adhering to the brand guidelines. The team expects significant improvements in model output after fine-tuning. What is a critical consideration for this fine-tuning effort?', '["The quality and diversity of the fine-tuning dataset are paramount; a small, low-quality dataset will likely lead to suboptimal results.","The size of the foundation model is the most important factor; a larger model will overcome any data quality issues during fine-tuning.","The number of fine-tuning epochs is the key; increasing epochs will compensate for a small or inconsistent dataset.","Parameter-Efficient Fine-Tuning (PEFT) techniques like LoRA will automatically correct data quality issues and improve performance."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) highlights a critical consideration for fine-tuning. The quality and diversity of the fine-tuning dataset directly impact the model''s performance. A small, low-quality, or inconsistent dataset is an anti-pattern (ap-3.3-001) that will likely lead to overfitting, amplify existing biases, or result in suboptimal improvements rather than significant gains. Option B (incorrect) the size of the foundation model does not negate the impact of poor-quality fine-tuning data; it might even exacerbate issues like overfitting. Option C (incorrect) increasing the number of fine-tuning epochs with a small, low-quality dataset can lead to overfitting, where the model memorizes the training data but performs poorly on new, unseen data. Option D (incorrect) PEFT techniques like LoRA are designed to make fine-tuning more efficient by reducing the number of parameters updated, but they do not magically correct underlying data quality issues.', 7, 'm_7_3', 18, NULL, NULL),
  ('mock_5_all_1774922262689', 'A media company wants to adapt a general-purpose foundation model on Amazon Bedrock to generate news headlines in its unique journalistic style. They have a large corpus of historical news articles and headlines. The goal is to achieve this customization with minimal operational overhead and without managing complex infrastructure. Which Amazon Bedrock capability should the company leverage?', '["Utilize Amazon Bedrock''s fine-tuning capabilities to adapt a base model with the company''s specific news headline dataset.","Set up an Amazon SageMaker notebook instance to manually pre-train a new foundation model from scratch using the company''s data.","Implement a Retrieval Augmented Generation (RAG) system with Amazon Bedrock Knowledge Bases to retrieve relevant headlines.","Employ a complex prompt engineering strategy that includes numerous examples of the desired headline style within each inference request."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most suitable approach. Amazon Bedrock''s fine-tuning capabilities allow companies to adapt a base foundation model to a specific domain or style (like journalistic style) using their own data, with minimal operational overhead as Amazon Bedrock manages the underlying infrastructure. Option B (incorrect) manually pre-training a new foundation model from scratch is an extremely resource-intensive and complex task, requiring deep ML expertise and significant infrastructure, which goes against the ''minimal operational overhead'' constraint. Option C (incorrect) a RAG system is primarily for grounding answers in external knowledge bases, not for adapting the model''s generative style or tone. Option D (incorrect) while prompt engineering can help, including numerous examples in every inference request can quickly hit context window limits, increase latency, and is less efficient than fine-tuning for embedding a consistent style into the model itself.', 7, 'm_7_3', 19, NULL, NULL),
  ('mock_5_all_1774922262689', 'A data science team is experimenting with fine-tuning a large foundation model for a specialized text classification task. They are looking for methods to adapt the model to their specific dataset efficiently, minimizing computational resources and storage requirements, especially for models with billions of parameters. Which technique is designed to achieve this parameter-efficient fine-tuning?', '["Full fine-tuning, where all parameters of the foundation model are updated during the training process.","Parameter-Efficient Fine-Tuning (PEFT) techniques, such as LoRA (Low-Rank Adaptation of Large Language Models).","Increasing the size of the pre-training dataset to include more domain-specific examples.","Using a zero-shot prompting approach, which does not involve any model training or fine-tuning."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) describes Parameter-Efficient Fine-Tuning (PEFT) techniques, such as LoRA. PEFT methods are specifically designed to adapt large foundation models to new tasks by updating only a small fraction of the model''s parameters, significantly reducing computational resources, storage, and training time compared to full fine-tuning. Option A (incorrect) full fine-tuning updates all parameters, which is computationally expensive and resource-intensive for large models, going against the goal of efficiency. Option C (incorrect) increasing the size of the pre-training dataset is part of the initial model development, not a fine-tuning technique, and it would require immense resources. Option D (incorrect) zero-shot prompting is an inference technique that uses a pre-trained model without any fine-tuning or training, which does not address the requirement of adapting the model to a specialized dataset.', 7, 'm_7_3', 20, NULL, NULL);

-- Update mock test with question count
UPDATE public.mock_tests
SET total_questions = total_questions + 20
WHERE id = 'mock_5_all_1774922262689';

COMMIT;


