INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_5_all_1774922262689', 'A financial institution is developing an AI model for loan approvals. They are concerned about potential bias in the training data leading to unfair outcomes for certain demographic groups. They need to proactively identify and mitigate bias before deploying the model to ensure fairness and compliance. Which approach offers the LEAST operational overhead for bias detection?', '["Manually inspect a sample of the training data for statistical disparities and then manually adjust weights.","Deploy the model to production immediately and rely on customer feedback to identify any biased outcomes.","Utilize Amazon SageMaker Clarify to analyze the training data for bias and generate reports before model deployment.","Implement a custom machine learning algorithm to detect bias, requiring extensive coding and validation."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) utilizes Amazon SageMaker Clarify, a managed service designed for detecting bias in machine learning models and data. It provides comprehensive reports and analysis with minimal operational overhead, integrating seamlessly into the ML workflow. Option A (incorrect) involves significant manual effort and is prone to human error, increasing operational overhead. Option B (incorrect) treats responsible AI as an afterthought, which is an anti-pattern ([ap-4.1-001]), and is reactive rather than proactive, potentially causing harm before detection. Option D (incorrect) requires developing and maintaining custom code, which significantly increases operational overhead compared to using a managed service.', 8, 'm_8_1', 1, NULL, NULL),
  ('mock_5_all_1774922262689', 'A healthcare provider is building an AI system to analyze patient records for disease prediction. The dataset contains sensitive Personally Identifiable Information (PII). They must ensure data privacy and compliance with regulations like HIPAA while processing this data for model training. Which AWS service can securely identify and protect PII in the training data with minimal manual effort?', '["Encrypt all Amazon S3 buckets storing patient data using AWS Key Management Service (AWS KMS) customer-managed keys.","Manually review and redact every patient record to remove all PII before uploading to Amazon S3 for training.","Use Amazon Macie to discover, classify, and report on sensitive data, including PII, stored in Amazon S3 buckets.","Implement Amazon Bedrock Guardrails to filter out PII from the model''s output during inference."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) leverages Amazon Macie, a data security and data privacy service that uses machine learning and pattern matching to discover and protect sensitive data, including PII, in Amazon S3. This approach offers automated identification with minimal manual effort. Option A (incorrect) is a good security practice for data at rest but does not specifically identify or classify PII within the data itself. Option B (incorrect) requires extensive manual effort, which is inefficient and prone to errors, increasing operational overhead. Option D (incorrect) is designed to apply safeguards to large language model (LLM) inputs and outputs, not for discovering and classifying PII in raw training data stored in Amazon S3.', 8, 'm_8_1', 2, NULL, NULL),
  ('mock_5_all_1774922262689', 'An insurance company is developing an AI model to automate claims processing. While the model shows high accuracy, the company recognizes that fully automated decisions in high-stakes scenarios could lead to significant customer dissatisfaction or legal issues if errors occur. Which approach implements a mechanism to ensure human oversight for critical decisions made by the AI model?', '["Design a human-in-the-loop workflow where high-risk claims flagged by the AI model are reviewed and approved by human experts.","Continuously monitor the model''s overall accuracy in production and retrain it if performance drops below a threshold.","Train a more complex and accurate AI model to minimize the chance of errors, thereby eliminating the need for human intervention.","Implement Amazon Bedrock Guardrails to prevent the model from generating inappropriate or harmful content in its responses."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) implements a human-in-the-loop pattern, which is crucial for high-stakes decisions to ensure accountability and allow for error correction. This directly addresses the anti-pattern of deploying AI in high-stakes decisions without human oversight ([ap-4.1-002]). Option B (incorrect) is a reactive measure that monitors overall performance but does not provide human oversight for individual critical decisions. Option C (incorrect) assumes that higher accuracy eliminates the need for human oversight, which is a dangerous anti-pattern ([ap-4.1-002]) in high-stakes domains. Option D (incorrect) is designed for content moderation of LLM outputs, not for providing human oversight on general AI model decisions like claims processing.', 8, 'm_8_1', 3, NULL, NULL),
  ('mock_5_all_1774922262689', 'A financial institution uses an AI model for loan approvals. Due to strict regulatory requirements and ethical guidelines, the institution must ensure the model''s decisions are fair across different demographic groups and proactively mitigate any biases. Which AWS service should they use to detect and quantify potential biases in the training data and model predictions?', '["Amazon SageMaker Clarify","Amazon Bedrock Guardrails","AWS Audit Manager","Amazon Macie"]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is Amazon SageMaker Clarify, which provides capabilities to detect and quantify bias in machine learning models and their training data. It helps analyze fairness metrics and feature attribution, which is crucial for meeting regulatory and ethical guidelines for loan approval models. Option B (incorrect) is Amazon Bedrock Guardrails, which is designed to implement safety policies for generative AI applications, preventing harmful content generation, not for detecting bias in traditional ML models. Option C (incorrect) is AWS Audit Manager, which helps automate auditing and compliance, but does not directly perform bias detection or mitigation for AI models. Option D (incorrect) is Amazon Macie, which is a data security service that uses machine learning to discover and protect sensitive data, but it does not analyze model bias.', 8, 'm_8_1', 4, NULL, NULL),
  ('mock_5_all_1774922262689', 'A company is developing a generative AI application for customer support. To prevent the model from generating harmful, biased, or off-topic responses that could damage brand reputation or violate company policies, they need to implement real-time content moderation. Which AWS service is designed to enforce safety policies and filter undesirable outputs from generative AI models?', '["Amazon Macie","Amazon Bedrock Guardrails","Amazon SageMaker Clarify","AWS Audit Manager"]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is Amazon Bedrock Guardrails, which allows customers to implement safety policies and filter undesirable content from generative AI applications, ensuring responsible AI usage. This directly addresses the need for real-time content moderation for harmful, biased, or off-topic responses. Option A (incorrect) is Amazon Macie, which is used for discovering and protecting sensitive data, not for content moderation of AI outputs. Option C (incorrect) is Amazon SageMaker Clarify, which is used for detecting bias and explaining predictions in traditional machine learning models, not for real-time generative AI content filtering. Option D (incorrect) is AWS Audit Manager, which helps automate auditing and compliance, but does not perform real-time content moderation.', 8, 'm_8_1', 5, NULL, NULL),
  ('mock_5_all_1774922262689', 'An e-commerce company uses an AI model to recommend products to customers. They have received feedback that the recommendations sometimes perpetuate stereotypes across different demographic groups. The data science team needs a solution to identify and address potential biases in the model''s training data and its prediction outcomes. Which AWS service should they use?', '["AWS Audit Manager","Amazon Macie","Amazon SageMaker Clarify","Amazon Bedrock Guardrails"]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is Amazon SageMaker Clarify, which provides tools to detect and quantify bias in machine learning models and their training data. It can help the data science team analyze fairness metrics and feature attribution to identify and mitigate the observed stereotypes in product recommendations. Option A (incorrect) is AWS Audit Manager, which automates auditing and compliance reporting, not bias detection. Option B (incorrect) is Amazon Macie, which is a data security service for sensitive data discovery, not for analyzing model bias. Option D (incorrect) is Amazon Bedrock Guardrails, which is for implementing safety policies in generative AI applications, not for bias detection in traditional recommendation models.', 8, 'm_8_1', 6, NULL, NULL),
  ('mock_5_all_1774922262689', 'A financial services company processes vast amounts of customer data, including Personally Identifiable Information (PII), to train an AI model for fraud detection. To comply with data privacy regulations and internal policies, the company must ensure that sensitive customer data used in AI training is automatically identified and protected. Which AWS service can help achieve this requirement?', '["Amazon SageMaker Clarify","AWS Audit Manager","Amazon Bedrock Guardrails","Amazon Macie"]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is Amazon Macie, a data security service that uses machine learning to discover, classify, and protect sensitive data, including PII, in Amazon S3. It can automatically identify sensitive data in the datasets used for AI training, helping ensure compliance with privacy regulations. Option A (incorrect) is Amazon SageMaker Clarify, which focuses on bias detection and model explainability, not sensitive data discovery. Option B (incorrect) is AWS Audit Manager, which helps automate auditing and compliance reporting, but does not perform sensitive data discovery. Option C (incorrect) is Amazon Bedrock Guardrails, which is for content moderation in generative AI applications, not for PII detection in training data.', 8, 'm_8_1', 7, NULL, NULL),
  ('mock_5_all_1774922262689', 'A public sector organization uses an AI model to allocate resources for critical services. To maintain public trust and comply with governance standards, they need to demonstrate that the AI system''s development and operation adhere to internal responsible AI policies and external regulations. Which AWS service can help establish a framework for auditing and demonstrating compliance?', '["AWS Audit Manager","Amazon Macie","Amazon SageMaker Clarify","Amazon Bedrock Guardrails"]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is AWS Audit Manager, which helps automate the collection of evidence to simplify auditing and compliance with regulations and industry standards. It can be used to track and demonstrate adherence to responsible AI policies throughout the AI system''s lifecycle. Option B (incorrect) is Amazon Macie, which focuses on discovering and protecting sensitive data. Option C (incorrect) is Amazon SageMaker Clarify, which is used for bias detection and model explainability. Option D (incorrect) is Amazon Bedrock Guardrails, which is for implementing safety policies in generative AI applications. None of these directly provide a framework for auditing and demonstrating compliance with responsible AI policies.', 8, 'm_8_1', 8, NULL, NULL),
  ('mock_5_all_1774922262689', 'A media company uses a generative AI model to assist with content creation. They need to ensure that the AI-generated content aligns with brand guidelines and avoids generating inappropriate or harmful material, even as ethical guidelines evolve. The company seeks a service to continuously evaluate and adapt the model''s safety policies in real-time. Which AWS service should they use?', '["Amazon SageMaker Clarify","Amazon Bedrock Guardrails","AWS Audit Manager","Amazon Macie"]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is Amazon Bedrock Guardrails, which is specifically designed to implement safety policies for generative AI applications. It allows for the definition of custom policies to filter out harmful, biased, or off-topic content, and these policies can be continuously updated and adapted to evolving ethical guidelines. Option A (incorrect) is Amazon SageMaker Clarify, which focuses on bias detection and explainability for traditional ML models. Option C (incorrect) is AWS Audit Manager, which automates compliance reporting, not real-time content moderation. Option D (incorrect) is Amazon Macie, which discovers and protects sensitive data, not for moderating generative AI outputs.', 8, 'm_8_1', 9, NULL, NULL),
  ('mock_5_all_1774922262689', 'A company is developing an AI model to assist with hiring recommendations. They are concerned that historical hiring data, which will be used for training, might contain inherent biases that could lead to unfair or discriminatory outcomes. The team needs to proactively analyze the training dataset for such biases before the model is trained and deployed. Which AWS service is best suited for this task?', '["Amazon Macie","AWS Audit Manager","Amazon SageMaker Clarify","Amazon Bedrock Guardrails"]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is Amazon SageMaker Clarify, which is designed to help detect and quantify potential biases in machine learning training data and models. It provides tools to analyze fairness metrics and identify bias before a model is trained or deployed, which is critical for sensitive applications like hiring recommendations. Option A (incorrect) is Amazon Macie, which focuses on discovering and protecting sensitive data. Option B (incorrect) is AWS Audit Manager, which automates compliance reporting. Option D (incorrect) is Amazon Bedrock Guardrails, which is for implementing safety policies in generative AI applications, not for bias detection in traditional ML training data.', 8, 'm_8_1', 10, NULL, NULL),
  ('mock_5_all_1774922262689', 'An insurance company uses an AI model to process claims, which involves sensitive customer information. To ensure data privacy and prevent accidental exposure or misuse, the company needs to automatically scan the data used for training and inference for PII and other sensitive data types across various data stores. Which AWS service should they utilize?', '["Amazon Bedrock Guardrails","Amazon SageMaker Clarify","AWS Audit Manager","Amazon Macie"]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is Amazon Macie, a data security service that uses machine learning to discover, classify, and protect sensitive data, including PII, stored in Amazon S3. It can automate the discovery of sensitive data across various data stores feeding the AI model, ensuring data privacy and compliance. Option A (incorrect) is Amazon Bedrock Guardrails, which is for content moderation in generative AI applications. Option B (incorrect) is Amazon SageMaker Clarify, which focuses on bias detection and model explainability. Option C (incorrect) is AWS Audit Manager, which helps automate auditing and compliance reporting. None of these services are designed for automated sensitive data discovery across data stores.', 8, 'm_8_1', 11, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_8_2
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_5_all_1774922262689', 'A bank uses a deep learning model for credit scoring, a highly regulated domain where every automated decision must be clearly explained to customers and regulators. The bank needs a solution to generate post-hoc explanations for individual model predictions to satisfy these stringent requirements. Which AWS service can provide this capability?', '["Amazon SageMaker Clarify","Amazon Macie","AWS Audit Manager","Amazon Bedrock Guardrails"]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is Amazon SageMaker Clarify, which provides model explainability features, including post-hoc explanations for individual predictions. It can generate SHAP values and feature importance scores, crucial for understanding black-box models and satisfying regulatory requirements like those in financial services. Option B (incorrect) is Amazon Macie, which focuses on sensitive data discovery. Option C (incorrect) is AWS Audit Manager, which automates compliance reporting. Option D (incorrect) is Amazon Bedrock Guardrails, which is for content moderation in generative AI applications. None of these other services provide direct model explainability for traditional ML models.', 8, 'm_8_2', 12, NULL, NULL),
  ('mock_5_all_1774922262689', 'A healthcare provider has deployed a complex neural network for medical image diagnosis. Clinicians need to understand the reasoning behind the model''s specific diagnoses to build trust and ensure patient safety, especially given the black-box nature of deep learning models. Which AWS service can help provide insights into the model''s decision-making process?', '["AWS Audit Manager","Amazon SageMaker Clarify","Amazon Macie","Amazon Bedrock Guardrails"]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is Amazon SageMaker Clarify, which offers model explainability features to provide insights into how complex, black-box models like neural networks make predictions. This helps clinicians understand the factors influencing a diagnosis, fostering trust and aiding in critical decision-making. Option A (incorrect) is AWS Audit Manager, which is for compliance auditing. Option C (incorrect) is Amazon Macie, which is for sensitive data discovery. Option D (incorrect) is Amazon Bedrock Guardrails, which is for content moderation in generative AI applications. Only SageMaker Clarify directly addresses model interpretability for traditional ML models.', 8, 'm_8_2', 13, NULL, NULL),
  ('mock_5_all_1774922262689', 'A retail company uses an AI model for dynamic pricing, which adjusts product prices based on various factors. While the model is highly accurate, stakeholders are skeptical about its fairness and want to understand the primary features influencing price adjustments. Which AWS service can help identify the most important features driving the model''s predictions to increase stakeholder trust?', '["Amazon Macie","Amazon Bedrock Guardrails","Amazon SageMaker Clarify","AWS Audit Manager"]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is Amazon SageMaker Clarify, which provides model explainability features, including the ability to identify feature importance. This helps stakeholders understand which input features (e.g., demand, inventory, competitor prices) have the most significant impact on the model''s dynamic pricing decisions, thereby increasing trust and transparency. Option A (incorrect) is Amazon Macie, which focuses on sensitive data discovery. Option B (incorrect) is Amazon Bedrock Guardrails, which is for content moderation in generative AI applications. Option D (incorrect) is AWS Audit Manager, which automates compliance reporting. None of these other services offer feature importance analysis for ML models.', 8, 'm_8_2', 14, NULL, NULL),
  ('mock_5_all_1774922262689', 'A government agency uses an AI model to determine eligibility for public services. Due to legal requirements and the need for accountability, the agency must provide a clear rationale for any automated decision that affects citizens. Which AWS service can ensure the AI model''s decisions are explainable and auditable to meet these legal and ethical obligations?', '["Amazon Bedrock Guardrails","Amazon Macie","AWS Audit Manager","Amazon SageMaker Clarify"]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is Amazon SageMaker Clarify, which provides tools for model explainability, allowing the generation of explanations for individual predictions. This capability is essential for meeting legal and ethical obligations to provide rationales for automated decisions, making the model''s behavior transparent and auditable. Option A (incorrect) is Amazon Bedrock Guardrails, which is for content moderation in generative AI. Option B (incorrect) is Amazon Macie, which focuses on sensitive data discovery. Option C (incorrect) is AWS Audit Manager, which automates compliance reporting but doesn''t generate model explanations itself.', 8, 'm_8_2', 15, NULL, NULL),
  ('mock_5_all_1774922262689', 'A pharmaceutical company uses an AI model to predict drug efficacy based on complex molecular structures. Scientists need to not only validate the model''s accuracy but also interpret its predictions to understand the underlying biological reasoning for specific drug interactions. Which AWS service can generate local explanations for individual predictions to support this scientific validation?', '["Amazon SageMaker Clarify","AWS Audit Manager","Amazon Macie","Amazon Bedrock Guardrails"]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is Amazon SageMaker Clarify, which provides explainability features, including the generation of local explanations (e.g., SHAP values) for individual predictions. This allows scientists to understand how specific features of a molecular structure contribute to a drug efficacy prediction, crucial for scientific validation. Option B (incorrect) is AWS Audit Manager, which automates compliance reporting. Option C (incorrect) is Amazon Macie, which focuses on sensitive data discovery. Option D (incorrect) is Amazon Bedrock Guardrails, which is for content moderation in generative AI applications. Only SageMaker Clarify directly offers the required model interpretability.', 8, 'm_8_2', 16, NULL, NULL),
  ('mock_5_all_1774922262689', 'An AI model is used in a critical infrastructure system to predict potential equipment failures. Operators need to understand the model''s behavior and its decision-making process to effectively intervene and prevent outages, especially since the model is a black-box deep learning algorithm. Which AWS service provides the necessary transparency into the model''s operations?', '["Amazon Macie","Amazon SageMaker Clarify","AWS Audit Manager","Amazon Bedrock Guardrails"]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is Amazon SageMaker Clarify, which offers model explainability features. It can provide insights into the decision-making process of black-box models, helping operators understand why a particular prediction was made, which is vital for enhancing operational safety and trust in critical infrastructure systems. Option A (incorrect) is Amazon Macie, which discovers and protects sensitive data. Option C (incorrect) is AWS Audit Manager, which automates compliance reporting. Option D (incorrect) is Amazon Bedrock Guardrails, which is for content moderation in generative AI applications. None of these other services provide model transparency for traditional ML models.', 8, 'm_8_2', 17, NULL, NULL),
  ('mock_5_all_1774922262689', 'A company is developing an AI-powered chatbot for customer support. To build user trust and comply with internal fairness guidelines, they need to evaluate the model''s fairness and explainability during the development phase. Specifically, they want to understand if the chatbot''s responses are influenced by sensitive attributes in the input. Which AWS service should they use?', '["AWS Audit Manager","Amazon Macie","Amazon SageMaker Clarify","Amazon Bedrock Guardrails"]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is Amazon SageMaker Clarify, which provides capabilities to detect bias and explain predictions in machine learning models. It can be used during development to evaluate fairness metrics and understand feature attributions, ensuring the chatbot''s responses are not unfairly influenced by sensitive attributes and building user trust. Option A (incorrect) is AWS Audit Manager, which automates compliance reporting. Option B (incorrect) is Amazon Macie, which focuses on sensitive data discovery. Option D (incorrect) is Amazon Bedrock Guardrails, which is for implementing safety policies in generative AI applications, not for bias detection and explainability in traditional ML models during development.', 8, 'm_8_2', 18, NULL, NULL),
  ('mock_5_all_1774922262689', 'An organization is subject to strict data governance policies and needs to maintain detailed records of how their AI models are developed, trained, and evaluated, including any fairness or explainability assessments. This documentation is crucial for internal auditing and demonstrating compliance with external regulations. Which AWS service helps manage and track these compliance records?', '["Amazon Macie","Amazon Bedrock Guardrails","Amazon SageMaker Clarify","AWS Audit Manager"]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is AWS Audit Manager, which helps automate the collection of evidence to simplify auditing and compliance. It is the appropriate service for maintaining detailed records of responsible AI practices, including fairness and explainability assessments, to demonstrate adherence to governance policies and regulations. Option A (incorrect) is Amazon Macie, which focuses on sensitive data discovery. Option B (incorrect) is Amazon Bedrock Guardrails, which is for content moderation in generative AI applications. Option C (incorrect) is Amazon SageMaker Clarify, which performs bias detection and model explainability, but does not manage the compliance records themselves.', 8, 'm_8_2', 19, NULL, NULL);

