INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_5_all_1774922262689', 'A healthcare startup is developing an AI model using Amazon SageMaker to analyze patient data for diagnostic assistance. Due to strict HIPAA compliance requirements, all data, model artifacts, and inference traffic must remain private and encrypted. The solution needs to ensure access control and data protection with the LEAST network exposure.', '["Deploy the SageMaker inference endpoint with a public internet gateway and secure access using AWS WAF.","Configure the SageMaker endpoint to use a public endpoint and restrict access with an IAM policy.","Deploy the SageMaker inference endpoint within a private Amazon VPC, using a VPC endpoint for private access.","Use Amazon S3 bucket policies to restrict access to model artifacts, allowing public inference endpoints."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) ensures the LEAST network exposure by deploying the Amazon SageMaker inference endpoint within a private Amazon VPC and configuring a VPC endpoint. This keeps all inference traffic within the AWS network, never traversing the public internet, which is critical for HIPAA compliance and data privacy. Option A (incorrect) and Option B (incorrect) both involve using public endpoints, which directly violates the requirement for minimal network exposure and is an anti-pattern for compliance-sensitive environments (ap-5.1-001). Option D (incorrect) only addresses S3 access, but still relies on a public inference endpoint, leaving the model API exposed.', 9, 'm_9_1', 1, NULL, NULL),
  ('mock_5_all_1774922262689', 'A financial institution is training a fraud detection model using sensitive customer transaction data on Amazon SageMaker. They need to ensure that the training data and the resulting model artifacts are encrypted at rest using customer-managed keys to meet regulatory compliance requirements.', '["Use Amazon S3 server-side encryption with S3-managed keys (SSE-S3) for all data and artifacts.","Configure Amazon SageMaker to use AWS KMS customer managed keys (CMKs) for S3 storage and EBS volumes.","Implement application-level encryption within the SageMaker notebook instances for all data before storage.","Rely on default encryption provided by Amazon SageMaker for all data at rest, as it meets compliance."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most appropriate solution. By configuring Amazon SageMaker to use AWS KMS customer managed keys (CMKs), the financial institution gains full control over the encryption keys used for training data stored in Amazon S3 and any Amazon EBS volumes attached to SageMaker instances, meeting the ''customer-managed keys'' requirement for regulatory compliance. Option A (incorrect) uses S3-managed keys, which are not customer-managed. Option C (incorrect) would significantly increase operational overhead and complexity by requiring manual implementation of encryption within the application, which is less efficient and secure than using AWS KMS. Option D (incorrect) relies on default encryption, which typically uses AWS-managed keys, not customer-managed keys, and may not satisfy specific regulatory requirements.', 9, 'm_9_1', 2, NULL, NULL),
  ('mock_5_all_1774922262689', 'A company uses Amazon Bedrock for generating marketing content. They are concerned about potential prompt injection attacks where users might try to manipulate the model to generate inappropriate or off-topic responses. They need a solution to filter and mitigate these risks effectively.', '["Implement strict IAM policies to restrict who can submit prompts to Amazon Bedrock.","Manually review all generated content for inappropriate responses before publishing.","Develop custom input validation logic within their application to filter out malicious prompts.","Utilize Amazon Bedrock Guardrails to define and enforce safety policies and content filters."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is the most effective and AWS-native solution for mitigating prompt injection attacks and ensuring responsible AI usage with Amazon Bedrock. Amazon Bedrock Guardrails allow organizations to define custom safety policies, content filters, and topic restrictions directly within Bedrock, preventing the generation of unwanted content. Option A (incorrect) addresses access control but does not prevent authorized users from submitting malicious prompts. Option B (incorrect) is a manual, reactive, and highly inefficient process that does not scale. Option C (incorrect) requires significant development effort and ongoing maintenance to build and update custom filtering logic, whereas Bedrock Guardrails provide a managed service for this purpose.', 9, 'm_9_1', 3, NULL, NULL),
  ('mock_5_all_1774922262689', 'A research institution is collaborating on a sensitive genomics project using Amazon SageMaker. They need to ensure that the SageMaker training jobs and inference endpoints can only communicate with specific resources within their private network and cannot access the public internet.', '["Configure SageMaker to use a public endpoint and rely on security groups to block outbound internet access.","Deploy SageMaker resources in a public subnet and use Network Access Control Lists (NACLs) to restrict traffic.","Launch SageMaker training jobs and deploy inference endpoints within a private Amazon VPC with no internet gateway.","Use AWS Direct Connect to establish a private connection from on-premises to SageMaker public endpoints."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the most secure and effective approach. Launching Amazon SageMaker training jobs and deploying inference endpoints within a private Amazon VPC with no internet gateway ensures that all communication remains within the private network, preventing any access to the public internet. This directly addresses the requirement for private network communication. Option A (incorrect) and Option B (incorrect) both involve public endpoints or subnets, which inherently allow public internet access, even if attempts are made to block it with security groups or NACLs, making them unsuitable for sensitive data (ap-5.1-001). Option D (incorrect) provides a private connection from on-premises but still relies on SageMaker public endpoints, which doesn''t meet the ''no public internet access'' requirement for the SageMaker resources themselves.', 9, 'm_9_1', 4, NULL, NULL),
  ('mock_5_all_1774922262689', 'A company in a highly regulated industry is deploying a machine learning model for credit scoring. They need to ensure that all data used for training, model artifacts, and inference requests are encrypted both at rest and in transit. The solution should be integrated with AWS services.', '["Implement application-level encryption for all data and use HTTP for inference requests.","Use AWS KMS for encryption at rest for Amazon S3 and Amazon EBS, and SSL/TLS for data in transit.","Rely solely on Amazon S3 default encryption for data at rest and use unencrypted HTTP for inference.","Encrypt data at rest using client-side encryption and use a VPN for all data in transit."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) provides comprehensive encryption for both data at rest and in transit using native AWS services. AWS KMS can be used to encrypt data stored in Amazon S3 (for training data and model artifacts) and Amazon EBS volumes (for SageMaker instances) at rest. SSL/TLS (HTTPS) is standard for encrypting data in transit for inference requests to Amazon SageMaker endpoints. Option A (incorrect) uses HTTP, which does not encrypt data in transit, and application-level encryption adds unnecessary complexity. Option C (incorrect) relies on unencrypted HTTP, which is a significant security vulnerability. Option D (incorrect) client-side encryption adds operational overhead, and while a VPN encrypts transit, SSL/TLS is typically used for API endpoints like SageMaker for simplicity and integration.', 9, 'm_9_1', 5, NULL, NULL),
  ('mock_5_all_1774922262689', 'A data science team is developing an AI model for a government agency. They need to manage permissions for various team members, granting specific access to Amazon SageMaker notebooks, training jobs, and model endpoints based on their roles (e.g., data scientist, ML engineer, auditor) with granular control.', '["Utilize AWS IAM roles and policies in conjunction with Amazon SageMaker Role Manager for fine-grained access control.","Grant all team members full administrator access to the AWS account to simplify permission management.","Implement a custom identity management system on an Amazon EC2 instance to manage SageMaker access.","Use Amazon S3 bucket policies to control access to data, assuming this also controls SageMaker resource access."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the best practice for managing granular permissions in Amazon SageMaker. AWS IAM roles and policies provide the foundational mechanism for defining permissions, and Amazon SageMaker Role Manager simplifies the creation and management of these roles for common SageMaker personas, ensuring fine-grained access control. Option B (incorrect) is a severe security anti-pattern, granting excessive permissions and violating the principle of least privilege. Option C (incorrect) introduces significant operational overhead and complexity by requiring a custom solution instead of leveraging native AWS security services. Option D (incorrect) only controls access to data in S3 and does not manage access to SageMaker notebooks, training jobs, or model endpoints directly.', 9, 'm_9_1', 6, NULL, NULL),
  ('mock_5_all_1774922262689', 'A company is concerned about adversarial attacks on their image classification model deployed on Amazon SageMaker. They want to ensure that access to the model''s training data and parameters is strictly controlled to prevent unauthorized manipulation, which could lead to such attacks.', '["Implement a public-facing API Gateway in front of the SageMaker endpoint to filter malicious requests.","Regularly retrain the model with augmented datasets to improve its robustness against all attack types.","Deploy the SageMaker endpoint in a public subnet and rely on security groups for network isolation.","Enforce strict AWS IAM policies and Amazon S3 bucket policies to control access to training data and model artifacts."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) directly addresses the root cause of many adversarial attacks by preventing unauthorized manipulation of the model''s core components. Enforcing strict AWS IAM policies ensures that only authorized personnel and services can access Amazon SageMaker training jobs and model artifacts, while Amazon S3 bucket policies protect the integrity of the training data. This reduces the risk of data poisoning or model parameter tampering that could facilitate adversarial attacks. Option A (incorrect) might help with inference input filtering but doesn''t protect the model''s underlying data or parameters. Option B (incorrect) is a good practice for model robustness but doesn''t directly prevent unauthorized access to the model''s components. Option C (incorrect) exposes the endpoint to the public internet, which is an anti-pattern (ap-5.1-001) for sensitive models and increases the attack surface, even with security groups.', 9, 'm_9_1', 7, NULL, NULL),
  ('mock_5_all_1774922262689', 'A pharmaceutical company is developing an AI model to predict drug efficacy. They need to ensure that all interactions with the Amazon SageMaker environment, including data access, model training, and deployment, are logged for auditing and compliance purposes.', '["Enable Amazon CloudWatch Logs for SageMaker notebook instances to capture code execution.","Integrate AWS CloudTrail with Amazon SageMaker to log all API calls and management events.","Manually record all user activities and changes in a spreadsheet for compliance tracking.","Use Amazon S3 access logs to track data access, assuming this covers all SageMaker interactions."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most comprehensive solution for auditing and compliance. AWS CloudTrail records all API calls and management events made to Amazon SageMaker and other AWS services, providing a detailed log of who did what, when, and from where. This is essential for auditing and demonstrating compliance. Option A (incorrect) captures logs from notebook instances but does not provide a complete audit trail of all SageMaker API calls and management events across the entire environment. Option C (incorrect) is a manual, error-prone, and non-scalable approach that is unsuitable for enterprise-level compliance. Option D (incorrect) only tracks access to S3 buckets and does not cover the full range of interactions with the SageMaker service itself.', 9, 'm_9_1', 8, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_9_2
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_5_all_1774922262689', 'A financial services company is developing an AI model for credit risk assessment. To comply with industry regulations and internal governance policies, they need to document the model''s purpose, data sources, training methodology, and performance metrics.', '["Store all documentation in a version-controlled system like AWS CodeCommit.","Use AWS Audit Manager to generate compliance reports for the model''s documentation.","Implement Amazon SageMaker Model Cards to standardize model documentation and governance.","Create a custom wiki page to manually record all model details and updates."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the most effective and AWS-native solution for documenting AI models to meet governance and compliance requirements. Amazon SageMaker Model Cards provide a standardized framework to capture essential information about a model, including its purpose, data sources, training details, and performance metrics, promoting transparency and accountability. Option A (incorrect) is a general code repository and not specifically designed for AI model documentation and governance frameworks. Option B (incorrect) is for assessing compliance of AWS resources against standards, not for documenting individual AI models. Option D (incorrect) is a manual, unstructured, and potentially inconsistent approach that does not scale well for robust governance.', 9, 'm_9_2', 9, NULL, NULL),
  ('mock_5_all_1774922262689', 'A public sector organization is using an AI system for resource allocation. They need to demonstrate compliance with various government regulations and internal policies regarding data privacy and algorithmic fairness. They require a service that can continuously audit their AWS resources for compliance.', '["Utilize AWS Config to continuously monitor and record AWS resource configurations and compliance.","Implement AWS CloudTrail to log API activity and manually review logs for compliance violations.","Use Amazon S3 for storing compliance documents and manually checking against policies.","Deploy Amazon EC2 instances to run custom scripts that periodically check resource compliance."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the ideal service for continuously auditing AWS resources for compliance. AWS Config continuously monitors and records the configuration changes of AWS resources and evaluates them against desired configurations using configurable rules, providing a compliance timeline and reporting. Option B (incorrect) logs API activity but requires manual review and interpretation for compliance, which is not continuous or automated. Option C (incorrect) is a storage solution and does not provide automated auditing capabilities. Option D (incorrect) introduces significant operational overhead and maintenance for custom scripts, which is less efficient and reliable than a managed service like AWS Config.', 9, 'm_9_2', 10, NULL, NULL),
  ('mock_5_all_1774922262689', 'A healthcare provider is implementing an AI system to assist with patient diagnosis. Due to strict data privacy laws like HIPAA, they must ensure that all data used by the AI system has clear lineage, consent management, and is subject to data minimization principles.', '["Store all patient data in a single Amazon S3 bucket with public access for easy AI model training.","Implement encryption for all data at rest and in transit using AWS KMS, and rely on network ACLs for access.","Use AWS CloudTrail to log all API calls to the AI services, assuming this covers data governance.","Establish a comprehensive data governance framework including data classification, access controls, and retention policies."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is the most comprehensive approach to meet the requirements for data lineage, consent management, and data minimization. Establishing a comprehensive data governance framework involves defining policies and procedures for data classification, implementing strict access controls (e.g., using AWS IAM), tracking data lineage, managing consent, and enforcing data minimization principles across the AI system''s lifecycle. Option A (incorrect) is a severe security and privacy violation, making data publicly accessible. Option B (incorrect) covers encryption and network security but does not directly address data lineage, consent management, or data minimization principles. Option C (incorrect) provides audit logs but doesn''t inherently implement data governance principles like consent or minimization.', 9, 'm_9_2', 11, NULL, NULL),
  ('mock_5_all_1774922262689', 'A company is developing an internal AI tool for HR to assist with resume screening. While not customer-facing, they recognize the potential for bias and the need for accountability. They want to establish a framework to document the model''s design, risks, and performance for internal review.', '["Treat the internal AI tool as low-risk and defer documentation until it becomes customer-facing.","Utilize Amazon SageMaker Model Cards and datasheets to document the model''s characteristics, risks, and performance.","Implement AWS CloudTrail to log all API calls to the AI service, as this provides sufficient governance.","Conduct an annual manual review of the AI tool''s output for bias, without formal documentation."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the best approach for establishing a robust governance framework for internal AI tools. Amazon SageMaker Model Cards and datasheets are designed to document critical aspects of an AI model, including its purpose, data, training details, intended use, and potential biases, which is essential for accountability and internal review, even for internal tools. Option A (incorrect) represents the anti-pattern (ap-5.2-001) of treating AI governance as optional for internal-only tools, which is a misconception as internal tools can still have significant impacts. Option C (incorrect) provides audit logs but does not capture the model''s design, risks, or performance metrics. Option D (incorrect) is a reactive and unstructured approach that lacks the formal documentation and continuous oversight required for effective governance.', 9, 'm_9_2', 12, NULL, NULL),
  ('mock_5_all_1774922262689', 'A global enterprise operates AI systems across multiple AWS accounts and regions. They need a centralized way to aggregate and manage audit logs from all AI/ML services to ensure comprehensive oversight and compliance reporting.', '["Configure AWS CloudTrail to aggregate logs from all accounts and regions into a central Amazon S3 bucket.","Implement Amazon CloudWatch Logs for each individual AI/ML service and manually consolidate them.","Use AWS Config to monitor resource changes, assuming it also centralizes audit logs.","Develop custom logging agents on Amazon EC2 instances to collect and centralize logs."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the standard and most efficient AWS solution for centralizing audit logs. AWS CloudTrail can be configured to aggregate logs from multiple AWS accounts and regions into a single, central Amazon S3 bucket, providing a unified view of all API activity for comprehensive oversight and compliance reporting. Option B (incorrect) would require significant manual effort to consolidate logs from disparate CloudWatch Logs groups. Option C (incorrect) monitors resource configurations and changes, but it does not centralize API activity logs. Option D (incorrect) introduces significant operational overhead for developing, deploying, and maintaining custom logging infrastructure, which is unnecessary given CloudTrail''s capabilities.', 9, 'm_9_2', 13, NULL, NULL),
  ('mock_5_all_1774922262689', 'A company in the financial sector is deploying an AI model for fraud detection. They are required to regularly assess their AWS environment for compliance against industry benchmarks and regulatory standards. They need a service that can automate this assessment process with minimal manual effort.', '["Manually review AWS security best practices documents and compare them against their environment.","Use AWS CloudTrail to log all API calls and then manually analyze these logs for compliance.","Utilize AWS Audit Manager to automate evidence collection and generate compliance reports against predefined frameworks.","Implement AWS Config rules to monitor resource changes, but not for comprehensive compliance assessment."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the most suitable service for automating compliance assessments. AWS Audit Manager helps continuously audit your AWS usage to simplify how you assess risk and compliance with regulations and industry standards. It automates evidence collection, making it easier to prepare for audits. Option A (incorrect) is a manual and time-consuming process that does not scale. Option B (incorrect) provides API logs but requires significant manual effort for analysis and reporting against compliance frameworks. Option D (incorrect) monitors resource configurations for compliance with specific rules but is not designed for comprehensive, framework-based compliance assessments and reporting like AWS Audit Manager.', 9, 'm_9_2', 14, NULL, NULL),
  ('mock_5_all_1774922262689', 'An organization is using Amazon Bedrock for generative AI applications. They need to define and enforce safety policies, such as filtering out harmful content or preventing specific topics, to ensure responsible AI usage and compliance with internal guidelines.', '["Implement custom post-processing scripts on Amazon EC2 instances to filter generated content.","Use AWS IAM policies to restrict which users can invoke the Amazon Bedrock models.","Rely on the default safety filters provided by the foundational models in Amazon Bedrock.","Configure Amazon Bedrock Guardrails to establish and enforce content and safety policies."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is the purpose-built solution for this requirement. Amazon Bedrock Guardrails allow organizations to define custom policies to detect and prevent generation of harmful, off-topic, or inappropriate content, ensuring responsible AI usage and compliance with internal guidelines. Option A (incorrect) introduces significant operational overhead and latency by requiring custom post-processing infrastructure. Option B (incorrect) controls access to the models but does not enforce content safety policies on the generated output itself. Option C (incorrect) relies on default filters, which may not be sufficient or customizable enough to meet specific internal guidelines or compliance requirements.', 9, 'm_9_2', 15, NULL, NULL),
  ('mock_5_all_1774922262689', 'A data science team is building a predictive maintenance model. They need to ensure that the data used for training is traceable back to its origin, and any transformations applied are recorded. This is crucial for debugging, auditing, and ensuring data quality over time.', '["Store all raw data in a single Amazon S3 bucket without any metadata or versioning.","Implement robust data governance practices, including data cataloging, lineage tracking, and metadata management.","Use AWS CloudTrail to log API calls to Amazon S3, assuming this provides full data lineage.","Manually document data sources and transformations in text files, updated periodically."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most effective approach for ensuring data traceability and quality. Robust data governance practices, which include data cataloging, lineage tracking, and metadata management, provide a clear record of data origin, transformations, and usage throughout its lifecycle. This is crucial for debugging, auditing, and maintaining data quality. Option A (incorrect) is an anti-pattern for data management, as it lacks versioning and metadata, making traceability impossible. Option C (incorrect) logs API calls to S3 but does not provide the detailed data lineage or transformation history needed for comprehensive data governance. Option D (incorrect) is a manual, error-prone, and non-scalable solution that is unsuitable for complex AI projects.', 9, 'm_9_2', 16, NULL, NULL),
  ('mock_5_all_1774922262689', 'A company is developing an AI-powered chatbot for customer support. They need to ensure that the chatbot adheres to strict data privacy rules and that all user interactions are logged and retained according to regulatory requirements for a specific period.', '["Encrypt all user interaction data using AWS KMS and log all API calls with AWS CloudTrail, implementing retention policies.","Store all chatbot interactions in an unencrypted Amazon S3 bucket with indefinite retention.","Rely on the chatbot application''s internal logging mechanisms without integrating with AWS services.","Use AWS Config to monitor resource changes, assuming this covers data privacy and interaction logging."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) provides a comprehensive solution for data privacy, logging, and retention. Encrypting user interaction data using AWS KMS ensures data at rest is protected, adhering to privacy rules. Logging all API calls with AWS CloudTrail provides an immutable audit trail of interactions, and implementing retention policies (e.g., via S3 lifecycle rules for CloudTrail logs) ensures compliance with regulatory retention requirements. Option B (incorrect) violates data privacy rules by storing data unencrypted and may not meet specific retention periods. Option C (incorrect) relies on unmanaged internal logging, which may lack the security, durability, and compliance features of AWS services. Option D (incorrect) monitors resource configurations but does not directly address logging user interactions or enforcing data privacy and retention for the data itself.', 9, 'm_9_2', 17, NULL, NULL);

