INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_18_all_1774924049788', 'A development team is deploying an application on Amazon EC2 instances that needs to securely access Amazon S3 buckets. The team wants to ensure that the application can retrieve temporary, frequently rotated credentials without embedding long-term access keys in the code, thereby minimizing security risks and operational overhead. Which approach should a Solutions Architect recommend?', '["Option A: Generate an IAM user with programmatic access, store its access keys in AWS Systems Manager Parameter Store SecureString, and retrieve them in the application.","Option B: Create an IAM role with specific permissions for Amazon S3, attach it to the Amazon EC2 instances, and allow the application to retrieve temporary credentials automatically.","Option C: Embed the IAM user''s access keys directly into the application code, encrypt them, and store the code in a private Git repository.","Option D: Store the IAM user''s access keys in AWS Secrets Manager, configure automatic rotation, and integrate the application to retrieve them at runtime."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most secure and operationally efficient method. By attaching an IAM role to the Amazon EC2 instances, the application can automatically receive temporary credentials from the instance metadata service, eliminating the need to store or manage long-term access keys. These credentials are automatically rotated by AWS, enhancing security and reducing operational overhead. Option A (incorrect) involves managing access keys, even if stored securely in Parameter Store. While better than embedding, it still requires the application to explicitly retrieve and manage these keys, which is less ideal than the automatic credential provision by an IAM role for EC2. Option C (incorrect) represents an anti-pattern (ap-1.1-002) as embedding long-term access keys in application code is highly insecure, risks exposure, and makes key rotation difficult. Option D (incorrect) uses AWS Secrets Manager, which is excellent for managing and rotating general application secrets like database credentials. However, for an application running on an EC2 instance needing AWS service access, an IAM role is the native, more secure, and lower-overhead solution for obtaining AWS credentials directly.', 18, 'm_18_1', 1, NULL, NULL),
  ('mock_18_all_1774924049788', 'A company''s security team needs to audit Amazon S3 bucket configurations and object access logs across multiple AWS accounts within an AWS Organization. The auditing account must have read-only access to these resources in all member accounts. The Solutions Architect needs to design a secure and scalable solution for this cross-account access. Which approach is MOST appropriate?', '["Option A: Create an IAM user in the auditing account, and then manually create the same IAM user with read-only permissions in each member account.","Option B: Configure an IAM role in each member account that grants read-only access to S3, and establish a trust policy allowing the auditing account to assume this role.","Option C: Share the root user credentials of each member account with the auditing team for read-only access.","Option D: Use AWS IAM Identity Center to provision individual users in the auditing account and grant them direct read-only access to S3 in all member accounts."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most secure and scalable approach for cross-account auditing. By creating an IAM role in each member account with specific read-only permissions for S3 and a trust policy that allows the auditing account to assume it, you centralize the auditing process without distributing long-term credentials. This aligns with the principle of least privilege and simplifies management. Option A (incorrect) would involve creating and managing multiple IAM users and their credentials across many accounts, leading to high operational overhead and potential security risks. Option C (incorrect) is a severe anti-pattern (ap-1.1-001) as sharing root user credentials grants unrestricted access and is a major security vulnerability. Option D (incorrect) describes a partial solution. While AWS IAM Identity Center can manage users, it still requires the underlying permission model, which is typically handled by IAM roles for cross-account access, not direct user provisioning into member accounts for this specific auditing scenario. The core mechanism for secure cross-account access for services like S3 is through IAM roles.', 18, 'm_18_1', 2, NULL, NULL),
  ('mock_18_all_1774924049788', 'A company needs to provide shell access to its Amazon EC2 instances for administrative tasks. The security team requires a solution that eliminates the need to open SSH port 22 to the internet, minimizes the attack surface, and provides auditability of all sessions. Which AWS service or feature should the Solutions Architect recommend?', '["Option A: Configure a bastion host in a public subnet with a security group allowing SSH from specific IP addresses.","Option B: Open port 22 (SSH) to 0.0.0.0/0 in the security group of the EC2 instances and rely on strong passwords.","Option C: Use AWS Systems Manager Session Manager to connect to the EC2 instances.","Option D: Implement Network ACLs to restrict SSH access to only corporate IP ranges."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the most secure and operationally efficient method. AWS Systems Manager Session Manager provides secure, auditable shell access to EC2 instances without opening inbound ports like SSH (port 22) on the instances or requiring bastion hosts. It leverages IAM for access control and integrates with AWS CloudTrail for auditing. Option A (incorrect) is a valid pattern for SSH access but still involves managing a bastion host and opening port 22, even if restricted. It adds operational overhead compared to Session Manager. Option B (incorrect) is a severe anti-pattern (ap-1.2-001) as opening port 22 to 0.0.0.0/0 exposes instances to brute-force attacks from the entire internet, regardless of password strength. Option D (incorrect) restricts access at the subnet level, which is a good practice, but it still requires port 22 to be open to the specified IP ranges on the instances themselves, which Session Manager avoids entirely.', 18, 'm_18_1', 3, NULL, NULL),
  ('mock_18_all_1774924049788', 'A public-facing web application hosted on AWS is experiencing frequent attacks, including SQL injection and cross-site scripting (XSS). The Solutions Architect needs to implement a solution that protects the application from these common web exploits without requiring changes to the application code. Which AWS service should be implemented?', '["Option A: Amazon GuardDuty to detect unusual activity and potential threats.","Option B: AWS WAF (Web Application Firewall) to filter malicious web traffic.","Option C: AWS Shield Advanced to provide enhanced DDoS protection.","Option D: Configure Security Groups to block suspicious IP addresses."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is specifically designed to protect web applications from common web exploits like SQL injection and XSS. AWS WAF allows you to create custom rules to block or allow traffic based on various criteria, including patterns indicative of these attacks, without modifying application code. Option A (incorrect) is a threat detection service that monitors for malicious activity and unauthorized behavior, but it does not actively prevent web exploits like SQL injection or XSS from reaching the application. Option C (incorrect) provides enhanced DDoS protection but does not specifically protect against application-layer attacks like SQL injection or XSS. Option D (incorrect) can block traffic from specific IP addresses but is not effective against dynamic web exploits that might originate from legitimate-looking sources or use varied attack vectors; it''s a network-level control, not an application-layer firewall.', 18, 'm_18_1', 4, NULL, NULL),
  ('mock_18_all_1774924049788', 'A healthcare company stores patient health information (PHI) in Amazon S3. Due to strict regulatory compliance, all data must be encrypted at rest using customer-managed encryption keys, and all key usage must be auditable. Which encryption option for Amazon S3 should the Solutions Architect recommend to meet these requirements?', '["Option A: Server-Side Encryption with AWS KMS (SSE-KMS) using a customer-managed key (CMK).","Option B: Server-Side Encryption with Amazon S3-managed keys (SSE-S3).","Option C: Server-Side Encryption with Customer-Provided Keys (SSE-C).","Option D: Client-Side Encryption, where the application encrypts data before uploading to S3."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most suitable choice. SSE-KMS with a customer-managed key (CMK) allows the customer to have control over the encryption key, including key rotation and access policies. Importantly, all API calls to AWS KMS involving the CMK are logged in AWS CloudTrail, providing the necessary audit trail for compliance. Option B (incorrect) is an anti-pattern (ap-1.3-001) for this scenario. SSE-S3 uses AWS-managed keys, meaning the customer has no control over the key or its rotation, and there is no direct audit trail of key usage in CloudTrail, failing the ''customer-managed'' and ''auditable'' requirements. Option C (incorrect) involves the customer providing the encryption key for each object. While the customer manages the key, it doesn''t integrate with AWS KMS for key management or provide the same level of auditability through CloudTrail for key usage as SSE-KMS CMKs. Option D (incorrect) involves the application handling encryption, which puts the burden of key management, rotation, and auditing entirely on the customer''s application, increasing operational complexity and potentially failing to meet specific compliance audit requirements for key management.', 18, 'm_18_1', 5, NULL, NULL),
  ('mock_18_all_1774924049788', 'A government agency needs to store highly sensitive classified data in AWS. The agency''s compliance requirements mandate that cryptographic keys must be generated and stored within a dedicated hardware security module (HSM) that meets FIPS 140-2 Level 3 validation. Which AWS service is specifically designed to meet this stringent requirement?', '["Option A: AWS KMS (Key Management Service) with a customer-managed key (CMK).","Option B: AWS CloudHSM.","Option C: AWS Secrets Manager for storing cryptographic keys.","Option D: Encrypt data client-side using open-source cryptographic libraries."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the only AWS service that provides dedicated hardware security modules (HSMs) that meet FIPS 140-2 Level 3 validation. AWS CloudHSM gives customers exclusive control over their encryption keys within a single-tenant HSM appliance. Option A (incorrect) is an anti-pattern (ap-1.3-004) in this context. While AWS KMS provides FIPS 140-2 Level 2 validated HSMs, it does not offer the dedicated, single-tenant FIPS 140-2 Level 3 compliance that AWS CloudHSM does. Option C (incorrect) is for storing and rotating secrets, not for generating and storing cryptographic keys in FIPS 140-2 Level 3 validated hardware. Option D (incorrect) places the entire burden of key management, hardware security, and compliance on the customer, which is extremely complex and unlikely to meet the FIPS 140-2 Level 3 requirement without significant investment.', 18, 'm_18_1', 6, NULL, NULL);

