INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_18_all_1774924049788', 'A media company is developing a new microservices-based video processing platform. The application experiences highly variable traffic patterns, with demand spiking significantly during peak hours. The engineering team requires a compute solution that automatically scales to meet demand, minimizes infrastructure management, and is cost-effective. Which architecture meets these requirements with the LEAST operational overhead?', '["Deploy the microservices as containers on Amazon ECS with AWS Fargate.","Provision Amazon EC2 instances with EC2 Auto Scaling groups and a Load Balancer.","Implement AWS Lambda functions for each microservice, triggered by API Gateway.","Utilize Amazon EMR clusters to run the video processing jobs on a scheduled basis."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) provides a serverless compute engine for Amazon ECS, allowing the team to run containers without provisioning, managing, or scaling underlying EC2 instances. This offers automatic scaling and the least operational overhead. Option B (incorrect) requires managing EC2 instances, including patching, security, and capacity planning, which increases operational overhead compared to Fargate. Option C (incorrect) might be suitable for some microservices, but AWS Lambda has a 15-minute execution limit, which might not be suitable for all video processing tasks, and managing many individual Lambda functions can become complex. Option D (incorrect) is designed for big data processing and analytics, not typically for general-purpose microservices with variable web traffic, and it involves managing clusters, increasing operational overhead.', 20, 'm_20_2', 1, NULL, NULL),
  ('mock_18_all_1774924049788', 'A research institution needs to process large datasets for scientific simulations. These simulations are fault-tolerant and can be interrupted and resumed without significant loss of progress. The institution''s primary concern is minimizing compute costs while ensuring sufficient capacity for these batch jobs. Which solution offers the MOST cost-effective approach for running these workloads?', '["Provision a fleet of Amazon EC2 On-Demand Instances using an Auto Scaling group.","Utilize AWS Batch to orchestrate jobs on Amazon EC2 Spot Instances.","Run the simulations as long-running processes on dedicated Amazon EC2 Reserved Instances.","Develop AWS Lambda functions to execute segments of the simulations in parallel."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) leverages AWS Batch to manage the execution of batch jobs, and by configuring it to use Amazon EC2 Spot Instances, the institution can achieve significant cost savings (up to 90% compared to On-Demand pricing). Spot Instances are ideal for fault-tolerant workloads that can handle interruptions. Option A (incorrect) uses On-Demand Instances, which are significantly more expensive than Spot Instances for fault-tolerant batch workloads, violating the ''MOST cost-effective'' constraint. Option C (incorrect) uses Reserved Instances, which are suitable for steady-state, long-running workloads, but they do not offer the same cost savings as Spot Instances for interruptible batch jobs. Option D (incorrect) is unsuitable because AWS Lambda functions have a maximum execution time of 15 minutes, which is typically too short for complex scientific simulations, violating the ''long-running processes'' implication.', 20, 'm_20_2', 2, NULL, NULL),
  ('mock_18_all_1774924049788', 'A development team is building a new application using containers and requires a platform that eliminates the need to manage the underlying server infrastructure. The application needs to scale quickly based on demand and integrate seamlessly with other AWS services. The team wants to focus solely on container images and application code. Which compute solution best meets these requirements?', '["Deploy containers on Amazon ECS with EC2 instances managed by Auto Scaling.","Run containers on Amazon EKS, managing the Kubernetes control plane and worker nodes.","Utilize Amazon ECS on AWS Fargate to run the containerized application.","Package the application as a monolithic service on a single, large Amazon EC2 instance."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) uses Amazon ECS on AWS Fargate, which is a serverless compute engine for containers. This eliminates the need for the development team to provision, manage, or scale the underlying EC2 instances, allowing them to focus entirely on their application code and container images, thus meeting the ''eliminates the need to manage the underlying server infrastructure'' requirement. Option A (incorrect) requires the team to manage the EC2 instances that serve as container hosts, including patching, scaling, and capacity planning, which goes against the ''eliminates the need to manage the underlying server infrastructure'' constraint. Option B (incorrect) involves managing the Kubernetes worker nodes, even though Amazon EKS manages the control plane, which still requires infrastructure management. Option D (incorrect) is a monolithic approach that does not leverage containers effectively, nor does it provide the desired scalability or minimal infrastructure management.', 20, 'm_20_2', 3, NULL, NULL),
  ('mock_18_all_1774924049788', 'A company operates a customer-facing web application with highly unpredictable traffic patterns, experiencing significant spikes during promotional events. The current architecture involves manually scaling Amazon EC2 instances, leading to either over-provisioning and wasted resources or under-provisioning and poor customer experience. The company needs an automated solution to match compute capacity to demand, ensuring OPTIMAL resource utilization.', '["Maintain a fixed number of Amazon EC2 On-Demand Instances to handle peak load.","Migrate the application to AWS Lambda functions for event-driven scaling.","Implement Amazon EC2 Auto Scaling with dynamic scaling policies based on CPU utilization.","Schedule Amazon EC2 instances to start and stop based on anticipated traffic patterns."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is a plausible distractor. Option C (correct) is the most appropriate solution. Amazon EC2 Auto Scaling with dynamic scaling policies, such as target tracking based on CPU utilization, automatically adjusts the number of EC2 instances to match actual demand. This prevents over-provisioning during low demand and ensures sufficient capacity during spikes, leading to optimal resource utilization. Option A (incorrect) represents static over-provisioning, which wastes resources during low demand and fails to meet the ''optimal resource utilization'' constraint. Option B (incorrect) might be a valid solution for some applications, but migrating an existing web application to a fully serverless Lambda architecture can be a significant re-architecture effort and might not be suitable for all types of web applications, especially those with long-running processes or specific runtime requirements. Option D (incorrect) involves scheduled scaling, which is better than manual scaling but still relies on anticipated patterns, which can be inaccurate for ''highly unpredictable traffic patterns,'' potentially leading to over or under-provisioning.', 20, 'm_20_2', 4, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_20_4
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_18_all_1774924049788', 'An e-commerce company hosts its website on Amazon EC2 instances behind an Application Load Balancer in a single AWS Region. Customers worldwide report inconsistent latency, especially for dynamic content like product recommendations and personalized user interfaces. The company wants to improve the user experience globally by delivering both static and dynamic content with the LOWEST possible latency. Which service combination should be implemented?', '["Integrate Amazon CloudFront with the Application Load Balancer as an origin.","Deploy AWS Global Accelerator in front of the Application Load Balancer.","Set up Amazon Route 53 with latency-based routing to multiple regional deployments.","Increase the instance size of the Amazon EC2 instances and the Application Load Balancer capacity."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) utilizes Amazon CloudFront, a global content delivery network (CDN), to cache static content at edge locations closer to users and optimize dynamic content delivery through persistent connections and network optimizations to the origin (the Application Load Balancer). This significantly reduces latency for users worldwide. Option B (incorrect) is primarily designed to improve performance for non-HTTP/S traffic or for applications where a static IP address is beneficial, but for dynamic web content, CloudFront''s edge caching and origin optimizations are generally more effective. Option C (incorrect) provides global DNS routing but does not directly address content delivery optimization or caching at the edge, which is crucial for reducing latency for both static and dynamic content. Option D (incorrect) would increase capacity within the existing region but would not address the fundamental issue of network latency for geographically dispersed users accessing content from a single region.', 20, 'm_20_4', 5, NULL, NULL),
  ('mock_18_all_1774924049788', 'A large enterprise needs to establish a secure and reliable network connection between its on-premises data center and its AWS VPC. The connection must support consistent high bandwidth for large data transfers and low latency for real-time applications, with a strict requirement for network performance predictability. Which AWS networking service should be used?', '["Configure an AWS Site-to-Site VPN connection over the public internet.","Establish an AWS Direct Connect connection between the data center and AWS.","Utilize a Virtual Private Gateway with a public IP address for inbound traffic.","Implement VPC peering between the on-premises network and the AWS VPC."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) establishes a dedicated, private network connection from the on-premises data center to AWS. This provides consistent high bandwidth and low latency, meeting the requirements for predictable network performance, which is crucial for large data transfers and real-time applications. Option A (incorrect) uses the public internet, which introduces variability in latency and bandwidth, failing to meet the ''consistent high bandwidth'' and ''low latency'' requirements for predictability. Option C (incorrect) describes a component of a VPN or Direct Connect setup but does not, by itself, provide the dedicated, high-performance connectivity required. Option D (incorrect) is used for connecting two AWS VPCs, not for connecting an on-premises data center to an AWS VPC.', 20, 'm_20_4', 6, NULL, NULL),
  ('mock_18_all_1774924049788', 'A rapidly growing company has deployed over 12 VPCs across several AWS accounts for different departments and environments. They need to establish a hub-and-spoke network topology to enable communication between all VPCs and a central shared services VPC, while simplifying routing and reducing management overhead. Which AWS networking service should be implemented?', '["Create individual VPC peering connections between each VPC and the central shared services VPC.","Utilize AWS Transit Gateway to connect all VPCs in a hub-and-spoke model.","Set up multiple AWS Site-to-Site VPN connections between each VPC.","Configure a complex routing scheme using Amazon Route 53 Private Hosted Zones."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the most appropriate solution. AWS Transit Gateway enables a hub-and-spoke network topology, allowing a single gateway to connect all VPCs and on-premises networks. This simplifies routing and significantly reduces the operational overhead of managing numerous individual connections, especially with 12+ VPCs. Option A (incorrect) would result in a large number of non-transitive VPC peering connections (O(n^2) complexity), making the network difficult to manage and scale, which is an anti-pattern for this scenario. Option B (incorrect) would involve setting up many individual VPN connections, which is not designed for scalable inter-VPC communication and would be complex to manage. Option D (incorrect) is a DNS service and does not provide network connectivity or routing capabilities between VPCs.', 20, 'm_20_4', 7, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_20_1
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_18_all_1774924049788', 'A software development team uses several Amazon EC2 instances to run build and test environments. They require a shared file system that allows multiple instances to concurrently access and modify files, supporting standard Linux file system permissions and semantics. The solution must be scalable and highly available. Which AWS storage service should the team choose?', '["Amazon EFS (Elastic File System).","Amazon S3 (Simple Storage Service).","Amazon EBS (Elastic Block Store).","AWS Storage Gateway configured as a file gateway."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is a scalable, elastic, cloud-native NFS file system that can be mounted by multiple EC2 instances concurrently. It supports POSIX file system semantics, including file locking and permissions, making it ideal for shared build and test environments. Option B (incorrect) is object storage and does not provide a POSIX-compliant file system interface, nor does it support concurrent file access and modification in the same way a shared file system does. Option C (incorrect) provides block storage that can only be attached to a single EC2 instance at a time (with some exceptions for multi-attach, but not for shared file system semantics across multiple instances easily). Option D (incorrect) is a hybrid cloud storage service that connects on-premises applications to cloud storage; it''s not designed for direct shared file system access between multiple EC2 instances within AWS.', 20, 'm_20_1', 8, NULL, NULL),
  ('mock_18_all_1774924049788', 'A data analytics application running on a single Amazon EC2 instance requires extremely low-latency block storage for its primary data store. The application performs frequent, small, random I/O operations and is highly sensitive to storage performance. The solution must provide consistent, high-performance storage directly attached to the EC2 instance. Which AWS storage option is MOST appropriate?', '["Mount an Amazon EFS file system to the EC2 instance.","Attach an Amazon EBS gp3 volume to the EC2 instance.","Store data in an Amazon S3 bucket and access it via the S3 API.","Use AWS Storage Gateway to connect to an on-premises file server."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) provides high-performance, low-latency block storage that is directly attached to a single EC2 instance. EBS gp3 volumes offer a consistent baseline performance of 3,000 IOPS and 125 MiB/s, which can be provisioned independently of storage size, making them ideal for latency-sensitive, I/O-intensive workloads. Option A (incorrect) is a network file system, which introduces network latency compared to direct-attached block storage and is primarily designed for shared access, not for single-instance, latency-sensitive workloads. Option C (incorrect) is object storage, which is not suitable for block-level access required by many applications and introduces higher latency than EBS for frequent, small I/O operations. Option D (incorrect) is a hybrid cloud solution for connecting on-premises environments to AWS storage and is not relevant for providing direct-attached, low-latency storage to an EC2 instance within AWS.', 20, 'm_20_1', 9, NULL, NULL),
  ('mock_18_all_1774924049788', 'A financial institution needs to store petabytes of historical transaction data for regulatory compliance. This data is accessed very rarely, perhaps once a year, but must be retained for at least 10 years. The primary requirement is to minimize storage costs while ensuring data durability and availability for retrieval within a few hours when needed. Which Amazon S3 storage class is the MOST cost-effective for this scenario?', '["Amazon S3 Standard.","Amazon S3 Standard-IA.","Amazon S3 Glacier Deep Archive.","Amazon S3 One Zone-IA."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is designed for long-term archives that are accessed very rarely, offering the lowest storage cost among all S3 storage classes. It provides retrieval options ranging from minutes to hours, which aligns with the requirement for retrieval within a few hours. Option A (incorrect) is for frequently accessed data and would be significantly more expensive for rarely accessed archival data. Option B (incorrect) is for infrequently accessed data but is still more expensive than Glacier Deep Archive for long-term, very rarely accessed archives. Option D (incorrect) is also for infrequently accessed data but stores data in a single Availability Zone, which might not meet the durability requirements for critical regulatory data, and it''s still more expensive than Glacier Deep Archive for this use case.', 20, 'm_20_1', 10, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_20_3
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_18_all_1774924049788', 'A popular social media application experiences frequent read spikes, with many users accessing the same trending content simultaneously. The underlying Amazon Aurora MySQL-Compatible Edition database is becoming a bottleneck, leading to increased latency for users and high CPU utilization on the database instances. The company needs to improve read performance and reduce the load on the database for frequently accessed data. Which solution should be implemented?', '["Implement Amazon ElastiCache for Redis to cache frequently accessed data.","Add more Amazon Aurora Read Replicas to distribute the read load.","Migrate the database to Amazon DynamoDB for higher read throughput.","Increase the instance size of the Amazon Aurora primary database instance."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is designed for caching frequently accessed data in-memory, significantly reducing the load on the primary database and improving read response times for trending content. This directly addresses the bottleneck caused by frequent read spikes. Option B (incorrect) helps distribute read load across multiple database instances, but it doesn''t solve the problem of repeated queries hitting the database for the exact same data. Caching at the application or dedicated caching layer (like ElastiCache) is more effective for this use case. Option C (incorrect) is a NoSQL database and migrating a relational database to DynamoDB would be a significant re-architecture and might not be suitable if complex relational queries are still required. Option D (incorrect) might provide some temporary relief by increasing the database''s capacity, but it''s a vertical scaling solution that doesn''t fundamentally address the efficiency of serving frequently accessed, identical data, and it''s generally less cost-effective than caching for read-heavy workloads.', 20, 'm_20_3', 11, NULL, NULL),
  ('mock_18_all_1774924049788', 'A company is migrating a legacy on-premises application to AWS. The application relies heavily on complex SQL queries with multi-table joins and requires strong transactional consistency (ACID properties). The database schema is highly normalized. The development team needs a fully managed database solution that supports these relational features and can scale to meet future growth. Which AWS database service is MOST suitable?', '["Use Amazon DynamoDB for its high performance and scalability.","Deploy Amazon Aurora MySQL-Compatible Edition.","Implement Amazon Redshift for data warehousing capabilities.","Utilize Amazon ElastiCache for Redis to store application data."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is a fully managed, high-performance relational database service that is compatible with MySQL. It fully supports complex SQL queries, multi-table joins, and ACID transactions, making it ideal for applications with highly normalized schemas and strong relational integrity requirements. Option A (incorrect) is a NoSQL key-value and document database, which is optimized for single-table access patterns and does not efficiently handle complex relational joins or multi-table transactions, making it unsuitable for this scenario. Option C (incorrect) is a data warehousing service optimized for analytical queries on large datasets, not for transactional online applications requiring complex joins and ACID properties. Option D (incorrect) is an in-memory caching service and is not a primary persistent database solution for transactional data.', 20, 'm_20_3', 12, NULL, NULL),
  ('mock_18_all_1774924049788', 'A serverless application uses AWS Lambda functions to interact with an Amazon RDS for PostgreSQL database. During peak load, the application experiences intermittent database connection errors, and CloudWatch metrics show that the RDS instance is reaching its maximum connection limit. The development team wants to resolve these connection issues with the LEAST amount of code change and operational overhead. Which AWS service should be implemented?', '["Increase the maximum connections parameter in the Amazon RDS parameter group.","Deploy an Amazon ElastiCache cluster to cache database queries.","Configure Amazon RDS Proxy between AWS Lambda and the Amazon RDS database.","Provision additional Amazon RDS Read Replicas to offload read traffic."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is specifically designed to manage and pool database connections for Amazon RDS, making it ideal for serverless applications like AWS Lambda that can rapidly open and close many connections. RDS Proxy reuses existing connections, preventing connection exhaustion on the database instance with minimal code changes. Option A (incorrect) might provide a temporary fix but increasing the maximum connections can consume more database memory and CPU, potentially leading to performance issues, and it doesn''t solve the underlying problem of Lambda''s ephemeral connections. Option B (incorrect) is a caching solution that improves read performance and reduces database load, but it does not address the issue of connection exhaustion from Lambda functions. Option D (incorrect) helps scale read traffic but does not solve the problem of connection limits for write operations or the connection pooling issue caused by Lambda''s architecture.', 20, 'm_20_3', 13, NULL, NULL),
  ('mock_18_all_1774924049788', 'A global online gaming platform needs a database solution to store player profiles, game scores, and inventory data. This data requires consistent single-digit millisecond latency at any scale, high availability, and the ability to handle millions of requests per second. The data model is primarily key-value, with simple lookups and updates. Which AWS database service is the MOST appropriate?', '["Amazon Aurora PostgreSQL-Compatible Edition.","Amazon RDS for MySQL.","Amazon Redshift.","Amazon DynamoDB."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is a fully managed NoSQL database service that provides consistent single-digit millisecond latency at any scale, making it ideal for high-performance, high-throughput key-value workloads like player profiles and game scores. It offers built-in high availability and automatic scaling. Option A (incorrect) and Option B (incorrect) are relational databases, which are not typically designed for the extreme scale and consistent low-latency requirements of a global gaming platform''s key-value data, and they would require more operational management for such scale. Option C (incorrect) is a data warehousing service optimized for analytical queries on large datasets, not for transactional, low-latency operational data.', 20, 'm_20_3', 14, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_20_5
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_18_all_1774924049788', 'A marketing company collects real-time clickstream data from its website, which includes user interactions, page views, and conversion events. This data needs to be ingested continuously, in chronological order, and processed immediately for real-time analytics dashboards and anomaly detection. Which AWS service is best suited for ingesting this high-volume, time-ordered streaming data?', '["Amazon Kinesis Data Streams.","AWS Glue Data Catalog.","Amazon S3 with S3 Event Notifications.","AWS DataSync for continuous data transfer."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is a highly scalable and durable real-time data streaming service that can continuously capture gigabytes of data per second from hundreds of thousands of sources. It maintains the order of records and is ideal for processing time-ordered clickstream data for real-time analytics. Option B (incorrect) is a metadata repository for data lakes and ETL jobs; it does not handle real-time data ingestion. Option C (incorrect) can trigger actions when new objects are uploaded to S3, but S3 is object storage and not designed for continuous, time-ordered streaming ingestion and immediate processing. Option D (incorrect) is a data transfer service used for migrating large amounts of data between on-premises storage and AWS, not for real-time streaming ingestion.', 20, 'm_20_5', 15, NULL, NULL),
  ('mock_18_all_1774924049788', 'A large manufacturing company needs to migrate 150 TB of historical sensor data from its on-premises data center to Amazon S3 for long-term archival and future analytics. The company has limited internet bandwidth, making a direct network transfer impractical within the required timeframe. They need a secure and efficient method to transfer this massive dataset. Which AWS service should they use?', '["Utilize AWS DataSync to transfer data over the existing network connection.","Establish an AWS Direct Connect link for high-speed network transfer.","Ship the data using an AWS Snowball device.","Configure AWS Transfer Family for SFTP access to Amazon S3."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is part of the AWS Snow Family, which provides physical devices for securely transferring large amounts of data (petabytes) into and out of AWS. For 150 TB with limited internet bandwidth, physically shipping a Snowball device is significantly faster and more cost-effective than network transfer. Option A (incorrect) is designed for online data transfer over a network, but for 150 TB with limited bandwidth, it would take an unacceptably long time and might be more expensive than Snowball. Option B (incorrect) provides a dedicated network connection, but even with high bandwidth, transferring 150 TB could still take weeks or months and would incur significant ongoing costs, making Snowball more efficient for a one-time large migration. Option D (incorrect) provides fully managed SFTP, FTPS, and FTP services to access S3, but it''s for network-based file transfers and not suitable for offline transfer of such a massive dataset.', 20, 'm_20_5', 16, NULL, NULL),
  ('mock_18_all_1774924049788', 'A retail company stores raw customer order data in Amazon S3. Before this data can be used for business intelligence and reporting, it needs to be transformed, cleaned, and converted into a columnar format (e.g., Parquet). The data processing workload is intermittent and varies in size. The company requires a fully managed, serverless, and scalable solution for these ETL (Extract, Transform, Load) operations. Which AWS service should be used?', '["Provision and manage an Amazon EMR cluster for data processing.","Develop custom Python scripts on Amazon EC2 instances for ETL.","Utilize AWS Glue for serverless ETL jobs.","Query the raw data directly in Amazon S3 using Amazon Athena."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is a fully managed, serverless ETL service that automatically scales to process large datasets. It integrates with the AWS Glue Data Catalog and can transform data in Amazon S3 into desired formats like Parquet, making it ideal for intermittent and varying ETL workloads without managing infrastructure. Option A (incorrect) requires provisioning, configuring, and managing an EMR cluster, which goes against the ''serverless'' and ''fully managed'' requirements. Option B (incorrect) involves self-managing EC2 instances for ETL, which requires significant operational overhead for provisioning, scaling, and maintenance, violating the ''serverless'' and ''fully managed'' constraints. Option D (incorrect) is a query service that allows running SQL queries directly on data in S3; it''s not primarily an ETL service for transforming and cleaning data into new formats.', 20, 'm_20_5', 17, NULL, NULL),
  ('mock_18_all_1774924049788', 'A data science team needs to perform ad-hoc analytical queries on petabytes of historical sales data stored in various formats (CSV, JSON, Parquet) within an Amazon S3 data lake. The team wants to use standard SQL for querying without needing to provision or manage any servers or clusters. The solution must be cost-effective, paying only for the data scanned. Which AWS service should they use?', '["Load all data into an Amazon Redshift data warehouse.","Set up and manage an Amazon EMR cluster for interactive querying.","Use AWS Glue to transform and query the data.","Query the data directly in Amazon S3 using Amazon Athena."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is a serverless query service that allows running standard SQL queries directly on data stored in Amazon S3. It supports various data formats and charges based on the amount of data scanned, making it highly cost-effective for ad-hoc analytics without managing any infrastructure. Option A (incorrect) is a data warehousing service that requires provisioning and managing clusters, which goes against the ''without provisioning or managing any servers'' requirement and incurs ongoing costs even when not actively querying. Option B (incorrect) is a big data processing service that also requires provisioning and managing clusters, making it less suitable for ad-hoc serverless querying. Option C (incorrect) is primarily an ETL service for data transformation and cataloging; while it can prepare data for querying, it is not the primary service for interactive SQL querying of data in S3.', 20, 'm_20_5', 18, NULL, NULL);

