INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_18_all_1774924049788', 'A media company processes large volumes of video files using a fleet of Amazon EC2 instances. The processing jobs are fault-tolerant, can be interrupted, and have flexible start and end times. The company needs to minimize compute costs for these jobs while maintaining high throughput. Which EC2 purchasing option should a Solutions Architect recommend?', '["Utilize Amazon EC2 Spot Instances for the entire fleet.","Purchase Amazon EC2 Reserved Instances for the expected baseline usage.","Implement AWS Savings Plans for EC2 compute usage across the account.","Use On-Demand Amazon EC2 instances and scale down during off-peak hours."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most cost-effective solution for fault-tolerant, flexible workloads. Amazon EC2 Spot Instances allow customers to bid on unused EC2 capacity, offering significant discounts (up to 90% off On-Demand prices) in exchange for the possibility of interruption. Since the video processing jobs are fault-tolerant and flexible, they are ideal for Spot Instances. Option B (incorrect) is suitable for steady-state, predictable workloads over a 1-3 year term, which doesn''t align with the flexible and interruptible nature of these jobs. Option C (incorrect) offers flexible pricing discounts over a 1-3 year term across various compute services but does not provide the deep discounts of Spot Instances for interruptible workloads. Option D (incorrect) provides the highest cost flexibility but is the most expensive option and does not leverage the cost savings opportunities for interruptible workloads.', 21, 'm_21_2', 1, NULL, NULL),
  ('mock_18_all_1774924049788', 'A development team frequently provisions Amazon EC2 instances for testing new features. These instances are typically used for 8-10 hours during weekdays and are idle otherwise. The team wants to reduce compute costs without manually starting and stopping instances daily. What is the MOST cost-effective approach?', '["Purchase Amazon EC2 Reserved Instances for the development environment.","Implement a scheduled AWS Lambda function to start and stop the EC2 instances based on a workday schedule.","Use AWS Savings Plans to cover the EC2 instance usage.","Migrate all development workloads to AWS Fargate to leverage serverless compute."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most cost-effective and automated solution for this scenario. Using a scheduled AWS Lambda function to automatically start instances at the beginning of the workday and stop them at the end ensures that compute resources are only running when needed, eliminating idle costs. Option A (incorrect) is an anti-pattern for variable or unpredictable workloads like development environments, as Reserved Instances assume steady-state usage and would incur costs even when instances are idle. Option C (incorrect) provides a discount over On-Demand pricing but still incurs costs for idle time, making it less effective than stopping instances. Option D (incorrect) is a valid serverless compute option but may require significant re-architecture and might not be the most cost-effective or immediate solution for existing EC2-based development environments, potentially introducing new operational overhead for migration.', 21, 'm_21_2', 2, NULL, NULL),
  ('mock_18_all_1774924049788', 'A company runs a web application on Amazon EC2 instances behind an Application Load Balancer. The application experiences unpredictable traffic spikes throughout the day, requiring rapid scaling. The Solutions Architect needs to design a compute solution that is highly available, cost-optimized, and can handle variable loads efficiently. Which approach should be chosen?', '["Provision a single large Amazon EC2 instance to handle peak load and manually scale up when needed.","Use Amazon EC2 Reserved Instances for the maximum expected capacity to ensure cost predictability.","Deploy multiple smaller Amazon EC2 instances within an Auto Scaling group across multiple Availability Zones, configured with a scaling policy based on CPU utilization.","Migrate the application to AWS Outposts to maintain existing on-premises licensing models while leveraging AWS compute."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the most cost-effective and resilient approach for variable workloads. Deploying multiple smaller Amazon EC2 instances within an Auto Scaling group across multiple Availability Zones allows the application to automatically scale out during peak demand and scale in during low demand, optimizing costs by only paying for necessary capacity. This also enhances availability. Option A (incorrect) is an anti-pattern because choosing a single large instance creates a single point of failure and leads to over-provisioning and higher costs during off-peak hours. Option B (incorrect) is not ideal for unpredictable workloads, as Reserved Instances are for steady-state usage and would lead to unused capacity costs during low traffic. Option D (incorrect) is for hybrid cloud scenarios requiring on-premises compute and is not primarily a cost-optimization strategy for a cloud-native web application with unpredictable traffic.', 21, 'm_21_2', 3, NULL, NULL),
  ('mock_18_all_1774924049788', 'A startup is deploying a new containerized microservices application on AWS. The application primarily runs on Linux and performs CPU-intensive data processing. The team is focused on achieving the best price/performance ratio for their compute resources. Which Amazon EC2 instance family should a Solutions Architect recommend?', '["C5 instances (Compute Optimized) for high-performance computing.","M5 instances (General Purpose) for balanced compute, memory, and networking.","R5 instances (Memory Optimized) for memory-intensive workloads requiring large RAM.","C6g instances (Graviton2-based) for superior price/performance for compatible Linux workloads."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is the most appropriate choice for achieving the best price/performance ratio for compatible Linux-based, CPU-intensive containerized workloads. C6g instances are powered by AWS Graviton2 processors (ARM-based) and offer up to 40% better price/performance over comparable x86 instances. Most Linux-based containerized applications are compatible with Graviton with minimal or no code changes. Option A (incorrect) offers compute optimization but uses x86 processors, which are generally less cost-effective than Graviton for compatible workloads. Option B (incorrect) provides general-purpose instances, not specifically optimized for CPU-intensive tasks or price/performance as much as Graviton. Option C (incorrect) is designed for memory-intensive workloads, which is not the primary requirement for this CPU-intensive data processing application.', 21, 'm_21_2', 4, NULL, NULL),
  ('mock_18_all_1774924049788', 'A company is migrating an on-premises batch processing system to AWS. The system runs nightly for 4 hours, processing a large dataset, and then remains idle until the next run. The Solutions Architect needs to design a compute solution that minimizes costs for this intermittent, predictable workload. Which approach is MOST cost-effective?', '["Use Amazon EC2 Spot Instances within an Auto Scaling group, configured to launch instances only during the 4-hour processing window.","Provision Amazon EC2 Reserved Instances for the expected instance types and quantities.","Utilize AWS Savings Plans to cover the compute usage for the batch processing system.","Run the batch processing on On-Demand Amazon EC2 instances and manually terminate them after each run."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most cost-effective solution for this intermittent, predictable, and fault-tolerant batch workload. By using Amazon EC2 Spot Instances, the company can leverage significantly lower prices for the 4-hour processing window. An Auto Scaling group can be configured with scheduled scaling actions to launch and terminate instances, ensuring resources are only active when needed and leveraging the Spot market''s cost savings. Option B (incorrect) is designed for steady-state, 24/7 workloads, and would be an anti-pattern for an intermittent system, leading to significant idle costs. Option C (incorrect) provides discounts but still incurs costs for the entire duration of instance uptime, and does not offer the deep discounts of Spot Instances for interruptible workloads. Option D (incorrect) would be more expensive than Spot Instances and relies on manual intervention, increasing operational overhead.', 21, 'm_21_2', 5, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_21_3
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_18_all_1774924049788', 'A financial application uses an Amazon RDS for PostgreSQL database that experiences highly variable and unpredictable traffic patterns, with periods of intense activity followed by long idle times. The Solutions Architect needs to optimize database costs while ensuring the database can scale rapidly to meet demand. Which database solution is MOST cost-effective?', '["Provision an Amazon RDS for PostgreSQL instance with a fixed capacity and enable Multi-AZ for high availability.","Migrate the database to Amazon Aurora Serverless v2 for PostgreSQL.","Use Amazon DynamoDB with on-demand capacity mode for the application data.","Implement an Amazon ElastiCache for Redis cluster to offload read traffic from the RDS instance."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most cost-effective solution for an Amazon RDS for PostgreSQL database with highly variable and unpredictable traffic patterns. Amazon Aurora Serverless v2 scales capacity in fine-grained increments and can scale down to minimal ACUs (Aurora Capacity Units) during idle periods, avoiding paying for unused provisioned capacity. This perfectly matches the requirement for cost optimization with variable workloads. Option A (incorrect) would lead to over-provisioning and significant idle costs during low traffic periods, as provisioned capacity is paid for regardless of usage. Option C (incorrect) is a NoSQL database and would require a significant re-architecture of the application, which is not implied by the scenario that mentions an existing PostgreSQL database. Option D (incorrect) can reduce read load but does not address the core issue of cost-optimizing the primary database''s compute capacity for variable workloads.', 21, 'm_21_3', 6, NULL, NULL),
  ('mock_18_all_1774924049788', 'A development team uses an Amazon RDS for MySQL database for a non-critical staging environment. The database is only accessed during business hours for testing purposes and does not require high availability. The Solutions Architect needs to minimize the database costs for this environment. Which configuration change should be implemented?', '["Enable Amazon RDS Multi-AZ deployment for enhanced fault tolerance.","Switch the Amazon RDS instance to a Single-AZ deployment.","Migrate the database to Amazon DynamoDB with provisioned capacity.","Implement Amazon RDS Proxy to manage database connections and reduce overhead."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most cost-effective configuration for a non-critical development database that does not require high availability. Running Amazon RDS in a Single-AZ deployment avoids the additional cost of maintaining a synchronous standby replica, which is incurred with Multi-AZ. Option A (incorrect) is an anti-pattern for non-critical development databases, as Multi-AZ doubles the cost by maintaining a synchronous standby, which is unnecessary for this scenario. Option C (incorrect) would involve migrating to a different database type, which is a significant architectural change and not necessarily more cost-effective for a staging relational database, especially with provisioned capacity for unpredictable usage. Option D (incorrect) is used to manage database connections and connection pooling, which helps with application scalability and resilience but does not directly reduce the underlying database instance costs for an idle or intermittently used development environment.', 21, 'm_21_3', 7, NULL, NULL),
  ('mock_18_all_1774924049788', 'A new analytics application uses Amazon DynamoDB to store real-time clickstream data. The traffic to the DynamoDB table is highly spiky and unpredictable, with bursts of millions of requests followed by periods of low activity. The Solutions Architect needs to ensure the database can handle these fluctuations without throttling while minimizing costs. Which DynamoDB capacity mode should be configured?', '["Utilize DynamoDB with provisioned capacity, setting read and write capacity units to handle peak loads.","Implement DynamoDB Global Tables to distribute traffic across multiple Regions and reduce throttling.","Configure DynamoDB with on-demand capacity mode.","Use Amazon ElastiCache for Memcached to cache frequently accessed items and reduce DynamoDB read requests."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the most suitable and cost-effective capacity mode for Amazon DynamoDB tables with highly spiky and unpredictable traffic. On-demand capacity mode automatically scales read and write throughput to accommodate actual traffic, and you only pay for the read and write requests your application performs. This eliminates the need for capacity planning and prevents throttling during unexpected spikes while minimizing costs during low activity. Option A (incorrect) is an anti-pattern for unpredictable traffic, as provisioned capacity requires upfront planning and risks over-provisioning (leading to unnecessary costs) or under-provisioning (leading to throttling). Option B (incorrect) is for multi-Region replication and high availability, not for managing unpredictable capacity within a single Region. Option D (incorrect) can reduce read requests but does not address the core issue of handling unpredictable write capacity and its associated costs.', 21, 'm_21_3', 8, NULL, NULL),
  ('mock_18_all_1774924049788', 'A company operates a global e-commerce platform that uses an Amazon RDS for MySQL database. During peak shopping seasons, read traffic significantly increases, leading to performance bottlenecks and higher costs due to scaling up the primary instance. The Solutions Architect needs to improve read performance and reduce costs during these periods. Which strategy should be implemented?', '["Deploy Amazon RDS Read Replicas in the same AWS Region.","Migrate the entire database to Amazon DynamoDB to handle high read volumes.","Increase the instance size of the primary Amazon RDS database during peak seasons.","Implement Amazon ElastiCache for Redis to cache all product catalog data."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most effective and cost-optimized strategy to handle increased read traffic for an Amazon RDS for MySQL database. Amazon RDS Read Replicas allow you to offload read queries from the primary database instance, distributing the load and improving read performance. This helps avoid scaling up the primary instance, which can be more expensive, and allows for horizontal scaling of reads. Option B (incorrect) would require a complete re-architecture of the application and database, which is a significant undertaking and not the most direct solution for read scaling on an existing relational database. Option C (incorrect) addresses performance but can be more expensive than read replicas for scaling reads, as you''re vertically scaling a single instance rather than horizontally distributing the load. Option D (incorrect) can certainly help with read performance by caching frequently accessed data, but it''s a complementary solution. Read replicas are a direct way to scale the database''s read capacity itself, which is often a more fundamental solution for read-heavy workloads.', 21, 'm_21_3', 9, NULL, NULL),
  ('mock_18_all_1774924049788', 'A data analytics team uses an Amazon RDS for PostgreSQL instance for ad-hoc queries and reporting. The database is primarily used during business hours, with occasional bursts of activity, and is mostly idle overnight and on weekends. The team wants to reduce costs associated with the database''s idle periods. Which solution offers the BEST cost optimization?', '["Configure Amazon RDS Multi-AZ deployment to ensure high availability during business hours.","Migrate the database to Amazon Aurora Serverless v2 for PostgreSQL.","Provision a larger Amazon RDS instance to handle peak query loads more efficiently.","Implement an AWS Lambda function to stop and start the RDS instance on a schedule."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most effective solution for cost optimization for an Amazon RDS for PostgreSQL instance with intermittent and bursty usage. Amazon Aurora Serverless v2 automatically scales capacity up and down based on demand, including scaling down to a minimal amount during idle periods, significantly reducing costs compared to a continuously running provisioned instance. Option A (incorrect) would increase costs by deploying a standby instance, which is unnecessary for a non-critical ad-hoc reporting database that is often idle. Option C (incorrect) would lead to over-provisioning and higher costs during idle periods. Option D (incorrect) is a viable option for cost savings but requires custom automation and management. Aurora Serverless v2 provides this ''stop and start'' functionality automatically and more granularly, making it a more ''serverless'' and often more cost-effective solution for this specific pattern.', 21, 'm_21_3', 10, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_21_4
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_18_all_1774924049788', 'A company hosts a static website in an Amazon S3 bucket. Users from around the world access this website. The Solutions Architect needs to ensure low latency for users globally and minimize data transfer costs for content delivery. Which AWS service should be integrated with Amazon S3?', '["Configure Amazon VPC peering between the S3 bucket''s Region and other Regions.","Use an AWS Transit Gateway to route traffic efficiently to the S3 bucket.","Integrate Amazon CloudFront with the Amazon S3 bucket.","Deploy an Amazon EC2 instance in each Region to serve content from S3."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the most effective solution for delivering static content globally with low latency and minimized data transfer costs. Amazon CloudFront is a content delivery network (CDN) that caches content at edge locations worldwide. When users request content, it is served from the nearest edge location, reducing latency and offloading requests from the origin S3 bucket, which also reduces S3 data transfer costs. Option A (incorrect) is used for private network connectivity between VPCs and is not relevant for public content delivery from S3. Option B (incorrect) is used for connecting multiple VPCs and on-premises networks, not for optimizing global public content delivery. Option D (incorrect) would significantly increase operational overhead and cost, as it requires managing EC2 instances in multiple regions, which is an inefficient way to serve static content compared to CloudFront.', 21, 'm_21_4', 11, NULL, NULL),
  ('mock_18_all_1774924049788', 'A company has two Amazon VPCs in the same AWS Region that need to communicate privately. VPC A hosts a web application, and VPC B hosts a backend database. The Solutions Architect needs to establish secure and cost-effective network connectivity between these VPCs. Which solution should be implemented?', '["Establish a VPC peering connection between VPC A and VPC B.","Configure an AWS Transit Gateway to connect VPC A and VPC B.","Route traffic over the public internet with appropriate security groups.","Deploy a NAT Gateway in each VPC to facilitate communication."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most straightforward and cost-effective solution for connecting two VPCs in the same AWS Region. A VPC peering connection allows instances in both VPCs to communicate with each other as if they were in the same network, using private IP addresses. Data transfer within the same Availability Zone over a peering connection is free. Option B (incorrect) is a more advanced service typically used for connecting a larger number of VPCs (many-to-many connectivity) or hybrid cloud scenarios, and while it would work, it''s an overkill and more expensive for just two VPCs. Option C (incorrect) is insecure and would incur public data transfer costs, violating the requirement for private and cost-effective communication. Option D (incorrect) is used to allow instances in private subnets to initiate outbound connections to the internet, not for inter-VPC communication.', 21, 'm_21_4', 12, NULL, NULL),
  ('mock_18_all_1774924049788', 'A global company has users in various geographical locations who frequently upload large files to an Amazon S3 bucket in a single AWS Region. Users often report slow upload speeds due to long distances to the S3 bucket. The Solutions Architect needs to improve upload performance and ensure data integrity while minimizing additional infrastructure costs. Which service should be used?', '["Implement Amazon S3 Transfer Acceleration.","Create an Amazon S3 bucket in each geographical Region closer to the users.","Use AWS Direct Connect to establish a private connection from user locations to AWS.","Deploy Amazon EC2 instances with high-bandwidth network interfaces in each user''s Region to act as upload proxies."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most effective solution for improving upload performance for users geographically distant from an Amazon S3 bucket. Amazon S3 Transfer Acceleration utilizes Amazon CloudFront''s globally distributed edge locations to route data over the optimized AWS backbone network, significantly speeding up uploads from distant clients. This is a cost-effective solution that requires minimal configuration. Option B (incorrect) would require managing multiple S3 buckets and potentially complex cross-Region replication, increasing management overhead and costs. Option C (incorrect) provides a dedicated network connection but is typically for on-premises data centers to AWS, not for individual users uploading files over the internet. Option D (incorrect) would introduce significant operational overhead and cost for managing EC2 instances globally, which is an inefficient solution compared to S3 Transfer Acceleration.', 21, 'm_21_4', 13, NULL, NULL),
  ('mock_18_all_1774924049788', 'A company''s internal application runs on Amazon EC2 instances in a private subnet and needs to access external APIs on the public internet. The Solutions Architect must ensure secure outbound internet connectivity for these instances while minimizing operational overhead and costs. Which networking component should be deployed?', '["Configure an Internet Gateway and assign public IP addresses to the EC2 instances.","Deploy an AWS Transit Gateway to route traffic to the public internet.","Deploy a NAT Gateway in a public subnet and configure route tables for private subnets.","Set up a VPN connection from the private subnet to an on-premises data center with internet access."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the standard and most cost-effective solution for enabling instances in a private subnet to initiate outbound connections to the internet without exposing them to inbound internet traffic. A NAT Gateway is a managed service that provides network address translation, allowing private instances to access the internet securely. Option A (incorrect) would expose the EC2 instances directly to the internet, violating the security requirement of being in a private subnet. Option B (incorrect) is used for connecting multiple VPCs and on-premises networks, not primarily for providing internet access to instances within a single VPC''s private subnet. Option D (incorrect) is for hybrid cloud connectivity and would route traffic through an on-premises network, which is unnecessarily complex and potentially slower for direct internet access from AWS.', 21, 'm_21_4', 14, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_21_1
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_18_all_1774924049788', 'A research team stores large datasets (several petabytes) in Amazon S3. The data is frequently accessed for the first 30 days, then access patterns become unpredictable, and after 90 days, the data is rarely accessed but must be retained for compliance for 7 years. The Solutions Architect needs to design a cost-optimized storage solution. Which S3 configuration should be implemented?', '["Store all data in Amazon S3 Standard and manually move older data to Amazon S3 Glacier after 90 days.","Store all data in Amazon S3 Standard-IA and set a lifecycle policy to transition to Amazon S3 Glacier Deep Archive after 90 days.","Store all data in Amazon S3 One Zone-IA and use a lifecycle policy to transition to Amazon S3 Glacier after 90 days.","Use Amazon S3 Intelligent-Tiering, with a lifecycle policy to transition to Amazon S3 Glacier Deep Archive after 90 days."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is the most cost-effective and operationally efficient solution for this scenario. Amazon S3 Intelligent-Tiering automatically moves objects between frequent and infrequent access tiers based on access patterns, which is ideal for the unpredictable access after 30 days. After 90 days, a lifecycle policy can transition the data to Amazon S3 Glacier Deep Archive, which is the lowest-cost storage class for long-term retention of rarely accessed data. Option A (incorrect) is an anti-pattern because keeping all data in S3 Standard without lifecycle policies is expensive, and manual movement adds operational overhead. Option B (incorrect) is less optimal because S3 Standard-IA has retrieval fees and is not ideal for unpredictable access patterns; Intelligent-Tiering is better. Option C (incorrect) is not suitable for data that requires high durability across multiple Availability Zones, as One Zone-IA stores data in a single AZ, and it also has retrieval fees.', 21, 'm_21_1', 15, NULL, NULL),
  ('mock_18_all_1774924049788', 'A company stores application logs in an Amazon S3 bucket. These logs are frequently accessed for the first 7 days for troubleshooting, then infrequently accessed for 60 days for auditing, and finally, must be archived for 5 years for compliance. The Solutions Architect needs to design a cost-optimized storage solution with minimal operational overhead. Which S3 lifecycle policy should be applied?', '["Transition objects to Amazon S3 Standard-IA after 7 days, then to Amazon S3 Glacier Instant Retrieval after 60 days, and finally to Amazon S3 Glacier Deep Archive after 5 years.","Transition objects to Amazon S3 One Zone-IA after 7 days, then to Amazon S3 Glacier Flexible Retrieval after 60 days.","Keep all objects in Amazon S3 Standard for 5 years, then delete them.","Use Amazon S3 Intelligent-Tiering for all logs, with a rule to delete after 5 years."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) provides the most cost-effective and appropriate lifecycle for the described access patterns. Transitioning to Amazon S3 Standard-IA after 7 days is cost-effective for infrequently accessed data. Moving to Amazon S3 Glacier Instant Retrieval after 60 days (which is 53 days after the Standard-IA transition, making it 60 days total from creation) is suitable for data that needs to be retrieved quickly but is rarely accessed. Finally, transitioning to Amazon S3 Glacier Deep Archive after 5 years (which is 4 years and 11 months after the Instant Retrieval transition, making it 5 years total from creation) is ideal for long-term, lowest-cost archiving. Option B (incorrect) uses S3 One Zone-IA, which is not recommended for logs that might be critical for auditing and compliance due to its lower durability. Option C (incorrect) is an anti-pattern for cost optimization as keeping all logs in S3 Standard for 5 years would be significantly more expensive. Option D (incorrect) is good for unpredictable access, but for clearly defined access patterns and long-term archiving, explicit lifecycle rules to Glacier tiers are generally more cost-effective.', 21, 'm_21_1', 16, NULL, NULL),
  ('mock_18_all_1774924049788', 'A data analytics team uses an Amazon EBS volume for a temporary data processing workload on an Amazon EC2 instance. The workload requires 4,000 IOPS and 200 MiB/s throughput. The Solutions Architect needs to select the MOST cost-effective EBS volume type that meets these performance requirements. Which EBS volume type should be chosen?', '["Provisioned IOPS SSD (io2) volume.","General Purpose SSD (gp3) volume.","Throughput Optimized HDD (st1) volume.","Cold HDD (sc1) volume."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most cost-effective EBS volume type that meets the specified performance requirements. General Purpose SSD (gp3) volumes provide a baseline of 3,000 IOPS and 125 MiB/s throughput at no extra cost, and can be provisioned up to 16,000 IOPS and 1,000 MiB/s throughput independently of storage size. For 4,000 IOPS and 200 MiB/s, gp3 can be configured to meet these needs at a lower cost than io2. Option A (incorrect) is an anti-pattern because Provisioned IOPS SSD (io2) volumes are significantly more expensive and are typically used for mission-critical applications requiring extremely high IOPS and durability (up to 256,000 IOPS), exceeding the requirements of this workload. Option C (incorrect) is designed for frequently accessed, throughput-intensive workloads like big data, but it is an HDD type and would not meet the IOPS requirement for an SSD-based workload. Option D (incorrect) is for infrequently accessed, large sequential workloads and would not meet the performance requirements.', 21, 'm_21_1', 17, NULL, NULL),
  ('mock_18_all_1774924049788', 'A startup is building a new application that generates a large volume of small files (kilobytes to megabytes) that are stored in Amazon S3. The access patterns for these files are highly unpredictable; some files are accessed frequently, others infrequently, and some not at all after initial upload. The Solutions Architect needs to minimize storage costs without manual intervention. Which S3 storage class should be chosen?', '["Amazon S3 Standard.","Amazon S3 Standard-Infrequent Access (S3 Standard-IA).","Amazon S3 One Zone-Infrequent Access (S3 One Zone-IA).","Amazon S3 Intelligent-Tiering."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is the most suitable and cost-effective choice for data with unknown or changing access patterns. Amazon S3 Intelligent-Tiering automatically moves objects between two access tiers (frequent and infrequent) when access patterns change, with no retrieval fees. This eliminates the need for manual lifecycle policies and ensures cost optimization without operational overhead. Option A (incorrect) is the most expensive tier for data that is not consistently accessed frequently. Option B (incorrect) and Option C (incorrect) are designed for data that is accessed infrequently but requires retrieval fees, making them less suitable and potentially more expensive for unpredictable access patterns where data might become ''frequent'' again.', 21, 'm_21_1', 18, NULL, NULL);

