INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_18_all_1774925287644', 'A development team is deploying an application on Amazon EC2 instances that needs to interact with Amazon S3 and Amazon DynamoDB. The security team requires that the application adheres to the principle of least privilege and does not store any long-term credentials directly on the instances. Which approach provides the MOST secure and operationally efficient way for the application to access AWS services?', '["Configure an IAM role with the necessary S3 and DynamoDB permissions and attach it to the EC2 instances. The application will automatically receive temporary credentials.","Generate an IAM user with programmatic access keys for S3 and DynamoDB, then embed these credentials as environment variables within the application code.","Create an IAM user with S3 and DynamoDB permissions, then store the access keys in an encrypted file on the EC2 instance, managed by a custom script.","Grant the EC2 instance''s default service role full administrator access to all AWS services, allowing the application to access S3 and DynamoDB."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most secure and operationally efficient approach. By attaching an IAM role to the EC2 instance, the application running on the instance can automatically assume the role and receive temporary, frequently rotated credentials. This eliminates the need to manage long-term credentials on the instance, adhering to the principle of least privilege and minimizing the risk of credential compromise. Option B (incorrect) violates the best practice of not embedding long-term access keys in application code, which risks exposure via version control and makes key rotation difficult. This aligns with anti-pattern [ap-1.1-002]. Option C (incorrect) involves custom script management and storing credentials on the instance, which is less secure and more complex than using IAM roles for EC2 instances. Option D (incorrect) violates the principle of least privilege by granting excessive permissions, increasing the blast radius if the instance is compromised.', 18, 'm_18_1', 1, NULL, NULL),
  ('mock_18_all_1774925287644', 'A large enterprise wants to integrate its existing on-premises Active Directory with AWS to provide single sign-on (SSO) for its employees across multiple AWS accounts. The solution must minimize administrative overhead for managing user identities and permissions in AWS. Which AWS service combination should a Solutions Architect recommend?', '["Manually create individual IAM users in each AWS account and synchronize passwords with Active Directory using a custom script.","Implement AWS IAM Identity Center (successor to AWS SSO) and connect it to the on-premises Active Directory using AWS Directory Service for Microsoft Active Directory.","Set up an Amazon Cognito User Pool to manage corporate identities and configure it to federate with Active Directory Federation Services (AD FS).","Use IAM roles with SAML 2.0 federation configured directly in each AWS account, requiring manual setup of identity providers and role trusts in every account."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most suitable solution. AWS IAM Identity Center provides a centralized way to manage access to multiple AWS accounts and business applications. It can be easily integrated with AWS Directory Service for Microsoft Active Directory, which in turn connects to the on-premises Active Directory, enabling single sign-on and minimizing administrative overhead for user management. Option A (incorrect) involves significant manual effort and does not provide centralized identity management or SSO, leading to high administrative overhead. Option C (incorrect) is primarily designed for customer-facing applications and user directories, not for enterprise workforce SSO with Active Directory. While Cognito can federate, IAM Identity Center is the dedicated solution for this enterprise use case. Option D (incorrect) would require configuring SAML 2.0 federation individually in each AWS account, which increases administrative overhead compared to the centralized management offered by AWS IAM Identity Center, especially across multiple accounts.', 18, 'm_18_1', 2, NULL, NULL),
  ('mock_18_all_1774925287644', 'A company operates a multi-account AWS environment managed by AWS Organizations. The security team needs to audit resource configurations and activity across all accounts. They require a secure, centralized, and automated way to grant read-only access to their auditing tools in a dedicated security account, without granting direct access to individual production accounts. Which approach should be implemented?', '["Create an IAM user in each member account with read-only permissions and provide the credentials to the auditing tools.","Configure an IAM role in the security account with permissions to assume roles in member accounts, and create corresponding IAM roles in each member account with read-only permissions, trusted by the security account role.","Enable AWS CloudTrail in each member account to send logs to a central S3 bucket in the security account, then grant the auditing tools direct S3 access.","Use AWS IAM Identity Center to provision individual read-only access for each auditing tool, requiring manual user creation for each tool."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) provides a secure, centralized, and scalable solution for cross-account auditing. By establishing an IAM role in the security account that can assume roles in member accounts, and configuring corresponding read-only roles in each member account trusted by the security account role, the auditing tools only need credentials for the security account role. This adheres to the principle of least privilege and provides a clear audit trail. Option A (incorrect) involves managing multiple IAM user credentials, which is not scalable, increases operational overhead, and is less secure than role-based access. Option C (incorrect) only provides access to CloudTrail logs, not real-time resource configuration or other service activity, and might not cover all auditing requirements without additional services. Option D (incorrect) is designed for human users to access accounts, not typically for automated auditing tools, and would still require manual configuration for each tool.', 18, 'm_18_1', 3, NULL, NULL),
  ('mock_18_all_1774925287644', 'A new AWS Solutions Architect is onboarding to a company''s existing AWS environment. During the initial review, they discover that the AWS account root user credentials are being used for daily operational tasks, including creating and managing resources. This practice poses a significant security risk. What is the MOST appropriate immediate action to rectify this situation and align with AWS best practices?', '["Create a new IAM user with administrator privileges and use these credentials for daily operations, while keeping the root user credentials for emergencies.","Implement multi-factor authentication (MFA) on the root user account and restrict its use to only essential account and service management tasks.","Disable the root user account entirely to prevent any further use and rely solely on IAM users for all operations.","Rotate the root user credentials monthly and store them in a secure password manager, ensuring only authorized personnel have access."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most appropriate immediate action. The AWS root user has unrestricted access to all resources in the account and cannot be scoped down, making its use for daily operations a major security risk, aligning with anti-pattern [ap-1.1-001]. Implementing MFA significantly enhances the security of the root user. Restricting its use to only essential tasks (like changing account settings or recovering from a compromise) and performing daily operations with IAM users/roles adhering to the principle of least privilege is a fundamental AWS security best practice. Option A (incorrect) still involves using a highly privileged account for daily operations, even if it''s an IAM user, which is better than the root user but still not ideal without least privilege. Option C (incorrect) is not possible, as the root user cannot be disabled; it is required for certain account management activities. Option D (incorrect) focuses on credential rotation, which is good, but doesn''t address the fundamental issue of using the root user for daily operations and its inherent broad permissions.', 18, 'm_18_1', 4, NULL, NULL),
  ('mock_18_all_1774925287644', 'A mobile application needs to allow users to sign up, sign in, and then access specific AWS resources (e.g., upload images to Amazon S3). The development team requires a fully managed service for user authentication and authorization that can scale globally and integrate easily with the mobile app. Which combination of AWS services should the Solutions Architect recommend?', '["Amazon Cognito User Pools for user sign-up/sign-in and Amazon Cognito Identity Pools to exchange tokens for temporary AWS credentials.","AWS IAM Identity Center for user authentication and AWS IAM roles for granting access to AWS resources.","AWS Directory Service for Microsoft Active Directory for user authentication and IAM policies for resource authorization.","Amazon DynamoDB to store user credentials and custom AWS Lambda functions to handle authentication and authorization logic."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the ideal solution for mobile applications requiring user authentication and authorization to AWS resources. Amazon Cognito User Pools handle user sign-up, sign-in, and directory management, issuing tokens upon successful authentication. Amazon Cognito Identity Pools then exchange these tokens for temporary, limited-privilege AWS credentials, allowing the mobile app to securely access services like Amazon S3. This aligns with the distinct purposes of User Pools (authentication) and Identity Pools (authorization), addressing anti-pattern [ap-1.1-004]. Option B (incorrect) is designed for workforce identity and access management for AWS accounts, not for customer-facing mobile applications. Option C (incorrect) is for enterprise directories and not suitable for public-facing mobile application user management. Option D (incorrect) would require significant custom development and operational overhead for authentication and authorization, which Amazon Cognito provides as a fully managed service.', 18, 'm_18_1', 5, NULL, NULL),
  ('mock_18_all_1774925287644', 'A company stores highly confidential documents in an Amazon S3 bucket. Access to these documents must be restricted to a specific group of IAM users within the same AWS account and a single IAM role from a different AWS account. The solution must enforce the principle of least privilege and be easily auditable. How should this access control be implemented?', '["Apply an S3 bucket policy that explicitly grants access to the specific IAM users and the cross-account IAM role, while implicitly denying all other access.","Create individual IAM policies for each IAM user and the cross-account IAM role, granting access to the S3 bucket, and attach these policies to the respective identities.","Use S3 Access Control Lists (ACLs) to grant read and write permissions to the specific IAM users and the cross-account IAM role.","Configure AWS WAF on the S3 bucket to filter IP addresses of the authorized users and the cross-account role''s origin."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most effective and auditable method. An S3 bucket policy is a resource-based policy that can explicitly define who has access to the bucket and its objects, including IAM users within the same account and roles from other accounts. It works in conjunction with IAM policies and adheres to the principle of least privilege by specifying allowed actions. Option B (incorrect) would require managing multiple IAM policies, which can become complex and harder to audit for a single resource. While IAM policies are part of the overall access control, a bucket policy is more suitable for centralizing access control for a specific S3 bucket. Option C (incorrect) is an older access control mechanism that is less granular and more complex to manage than bucket policies, especially for cross-account access and specific IAM users. Option D (incorrect) is for protecting web applications from common exploits and is not designed for granular access control to S3 buckets based on IAM identities.', 18, 'm_18_1', 6, NULL, NULL),
  ('mock_18_all_1774925287644', 'A global organization is expanding its AWS footprint across multiple accounts and regions. They need to ensure that all new AWS accounts automatically adhere to specific security and compliance guardrails, such as preventing the creation of unencrypted Amazon S3 buckets or disallowing specific AWS services. The solution must be centrally managed and automatically applied to new accounts. Which AWS service and feature should be used?', '["AWS Config rules deployed individually in each account to monitor for non-compliant resources and trigger remediation.","AWS Organizations with Service Control Policies (SCPs) applied to Organizational Units (OUs) to restrict actions at the account level.","Amazon GuardDuty enabled in each account to detect malicious activity and alert security teams.","AWS Security Hub to aggregate security findings from various services and provide a centralized view of compliance status."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most effective solution for enforcing preventative guardrails across multiple accounts in AWS Organizations. Service Control Policies (SCPs) allow you to centrally manage permissions for all accounts in your organization. They can be attached to an Organizational Unit (OU) or directly to accounts, preventing specified actions (like creating unencrypted S3 buckets) even before resources are provisioned. Option A (incorrect) provides detective controls and remediation after a resource is created, which is not preventative. It also requires deployment in each account, increasing management overhead compared to SCPs. Option C (incorrect) is a threat detection service, not a preventative control for resource provisioning. Option D (incorrect) is an aggregation and dashboard service for security findings, not a mechanism for enforcing preventative policies across accounts.', 18, 'm_18_1', 7, NULL, NULL);

